  // paint far to near by each slice's middle, slid or not: a slice pulled toward the viewer paints last
  let painted = "";
  const depth = (sl) => (Math.cos(sl.am) + Math.sin(sl.am)) * (R * 0.6 + sl.last);
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const sl of slices) {
      const d = tval(sl.tw, now);
      if (d !== sl.last) { draw(sl, d); sl.last = d; }
      if (!tdone(sl.tw, now)) moving = true;
    }
    const byDepth = slices.slice().sort((a, b) => depth(a) - depth(b)), key = byDepth.map((sl) => sl.k).join();
    if (key !== painted) { painted = key; for (const sl of byDepth) g.appendChild(sl.s.g); }
    return moving;
  });
  bag.add(B.unregister);

  /** The slice facing the point, read on the plane of the cake's middle, which never moves; -1 off the board. */
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H / 2);
    if (Math.hypot(x, y) > R + 34) return -1;
    const t = (Math.atan2(y, x) + 2 * Math.PI) % (2 * Math.PI);
    return clamp(Math.floor(t / rad(360 / N)), 0, N - 1);
  }

  let act = -2;
  const ring = (i, a) => { const d = Math.abs(i - a) % N; return Math.min(d, N - d); };
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    for (const sl of slices) {
      const r = a < 0 ? -1 : ring(sl.k, a);
      const d = a < 0 ? (sl.k === FAV ? 10 : RESTOUT) : r === 0 ? OUT : r === 1 ? 4 : RESTOUT;
      tset(sl.tw, d, now, from < 0 ? 0 : ring(sl.k, from) * 40);
      sl.s.sil.classList.toggle("hi", sl.k === (a < 0 ? FAV : a));
    }
    read.textContent = a < 0 ? "rest" : "slice " + (a + 1);
    B.wake();
  }

  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());

  return {
    set: (v) => { OUT = v; if (act >= 0) { const a = act; act = -2; setActive(a); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "layercake",
  means: "A round cake cut in eight: the slice facing the pointer slides out to show its layers, and its neighbours part.",
  rules: [1, 2, 5, 9],
  range: [10, 18, 26],
  tour: [[270, 190], [150, 200], [200, 110], null],
  mount,
});

coinstacks.code:
/**
 * Coin stacks: twenty stacks of coins on a rounded tray, each a column of
 * thin discs with a line at every coin. At rest the stacks climb from front
 * left to back right, savings growing. The pointer rises the stacks around
 * it, the near ones tallest, each on its own spring. The slider is the reach.
 *
 * The pattern: a continuous field (terrain), on round stacks.
 */
const {
  Cam, circ, clamp, facing, fit, open, prism, proj, rings, ringAt, run, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NX = 5, NY = 4, CELL = 22, R = 8.4, COIN = 2.4, HMAX = 50;
const EXT_X = NX * CELL, EXT_Y = NY * CELL;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.42 ? 1 - (u / 0.42) * 0.62 : u <= 1 ? 0.38 - ((u - 0.42) / 0.58) * 0.26 : 0.12);
const disc = (cx, cy, r) => circ(r, 40).map((q) => ({ ...q, u: q.u + cx, v: q.v + cy }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * CELL, over = null;
  const C = Cam(45, 0.5, 1.7);
  fit(C, [[-8, -8, -4], [EXT_X + 8, EXT_Y + 8, -4], [EXT_X + 8, -8, -4], [-8, EXT_Y + 8, -4], [0, 0, HMAX + 4]], 200, 168);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-8, -8, EXT_X + 8, EXT_Y + 8, 10, 2);
  put(solid(g), prism(P, front, tr, ti, -4, 0));

  const stacks = [];
  for (let s = 0; s <= NX + NY - 2; s++) for (let i = 0; i < NX; i++) {
    const j = s - i;
    if (j < 0 || j >= NY) continue;
    const cx = (i + 0.5) * CELL, cy = (j + 0.5) * CELL;
    // savings growing: taller toward the back right, with a little unevenness
    const h0 = COIN * Math.round(2 + i * 2.2 + (NY - 1 - j) * 1.1 + ((i * 7 + j * 3) % 3) * 0.6);
    const ring = disc(cx, cy, R), inner = disc(cx, cy, R - 1.6);
    const el = solid(g), lines = mk("path", { class: "nf lo" }, el.g);
    stacks.push({ i, j, cx, cy, h0, ring, inner, el, lines, sp: spring(h0, { eps: 0.04 }), drawn: NaN });
  }

  function draw(st) {
    const h = Math.max(COIN, st.sp.x);
    if (h === st.drawn) return;
    st.drawn = h;
    put(st.el, prism(P, front, st.ring, st.inner, 0, h));
    const f = run(st.ring, front);
    let d = "";
    for (let z = COIN; z < h - 0.6; z += COIN) d += open(ringAt(P, f, z));
    st.lines.setAttribute("d", d);
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const st of stacks) { if (stepS(st.sp, dt)) m = true; draw(st); }
    return m;
  });
  bag.add(B.unregister);

  const tallest = stacks.reduce((a, b) => (b.h0 > a.h0 ? b : a));
  function retarget() {
    let mark = tallest;
    for (const st of stacks) {
      if (!over) { st.sp.t = st.h0; continue; }
      st.sp.t = Math.max(COIN, Math.round((HMAX * falloff(Math.hypot(st.cx - over[0], st.cy - over[1]) / RAD)) / COIN) * COIN);
    }
    if (over) {
      const i = clamp(Math.floor(over[0] / CELL), 0, NX - 1), j = clamp(Math.floor(over[1] / CELL), 0, NY - 1);
      mark = stacks.find((st) => st.i === i && st.j === j);
      read.textContent = `stack ${i + 1}·${j + 1}`;
    } else read.textContent = "rest";
    for (const st of stacks) st.el.sil.classList.toggle("hi", st === mark);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { const q = unproj(C, p[0], p[1], 0); over = [clamp(q[0], 0, EXT_X), clamp(q[1], 0, EXT_Y)]; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();

  return { set: (v) => { RAD = v * CELL; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "coinstacks",
  means: "Twenty stacks of coins on a tray: the stacks around the pointer rise, the nearest tallest.",
  rules: [1, 3, 5, 9],
  range: [1.2, 2.2, 3.5],
  tour: [[150, 200], [240, 170], [200, 240], null],
  mount,
});

bookshelf.code:
/**
 * Bookshelf: a row of eleven books of different heights and widths on a
 * shelf board between two bookends, each with bands near the top and foot of
 * its spine. The pointer picks a book by where it stands: it slides out
 * toward the reader and lifts, and the books beside it ease out a little,
 * staggered from it. At rest one book is half pulled, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the book
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = [8, 6, 9, 7, 10, 6, 8, 7, 9, 6, 8], HT = [52, 46, 56, 44, 50, 54, 42, 48, 55, 45, 51];
const D = 30, GAP = 0.8, OUT = 18, LIFT = 4, FAV = 4, END = 4;
const xs = []; { let x = END + 1; for (const w of W) { xs.push(x); x += w + GAP; } }
const X1 = xs[xs.length - 1] + W[W.length - 1] + 1 + END;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[0, -2, -4], [X1, D + OUT + 2, -4], [X1, -2, -4], [0, D + OUT, -4], [0, 0, 60], [X1, 0, 60]], 200, 170);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, -2, X1, D + 6, 2, 1);
  put(solid(g), prism(P, front, br, bi, -4, 0));
  const end = (x0, x1) => { const [r, i] = rings(x0, 0, x1, D, 1.2, 0.6); put(solid(g), prism(P, front, r, i, 0, 40)); };
  end(0, END);

  const books = W.map((w, k) => {
    const el = solid(g), bands = mk("path", { class: "nf lo" }, el.g);
    return { k, w, h: HT[k], x0: xs[k], el, bands, y: tween(k === FAV ? 9 : 0), z: tween(0), last: "" };
  });
  const endR = solid(g);
  { const [r, i] = rings(X1 - END, 0, X1, D, 1.2, 0.6); put(endR, prism(P, front, r, i, 0, 40)); }

  function draw(b, y, z) {
    const key = y.toFixed(2) + "," + z.toFixed(2);
    if (key === b.last) return false;
    b.last = key;
    const [r, i] = rings(b.x0, y, b.x0 + b.w, y + D, 1.2, 0.7);
    put(b.el, prism(P, front, r, i, z, z + b.h));
    const f = (zz) => seg(P(b.x0 + 0.8, y + D, z + zz), P(b.x0 + b.w - 0.8, y + D, z + zz));
    b.bands.setAttribute("d", f(b.h - 6) + f(b.h - 9) + f(7));
    return true;
  }

  // paint far to near: a book pulled toward the reader goes after its neighbours, so does the right bookend
  let painted = "";
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of books) { draw(b, tval(b.y, now), tval(b.z, now)); if (!tdone(b.y, now) || !tdone(b.z, now)) moving = true; }
    const order = books.slice().sort((a, c) => a.x0 + tval(a.y, now) * 1.4 - (c.x0 + tval(c.y, now) * 1.4));
    const key = order.map((b) => b.k).join();
    if (key !== painted) { painted = key; for (const b of order) g.appendChild(b.el.g); g.appendChild(endR.g); }
    return moving;
  });
  bag.add(B.unregister);

  /** The book whose resting middle is nearest the pointer's x on screen; -1 off the shelf. */
  const mids = books.map((b) => P(b.x0 + b.w / 2, D, b.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    const m = mids[best];
    return bd < 14 && Math.abs(m[1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    books.forEach((b, k) => {
      const d = Math.abs(k - a);
      const y = a < 0 ? (k === FAV ? 9 : 0) : d === 0 ? OUT : d === 1 ? 5 : d === 2 ? 2 : 0;
      const delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(b.y, y, now, delay); tset(b.z, a === k ? LIFT : 0, now, delay);
      b.el.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "book " + String(a + 1).padStart(2, "0");
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "bookshelf",
  means: "Eleven books on a shelf: the one under the pointer slides out and lifts, and its neighbours ease out in turn.",
  rules: [1, 2, 5, 8],
  range: [0, 40, 80],
  tour: [[135, 155], [190, 180], [250, 210], null],
  mount,
});

lockers.code:
/**
 * Parcel lockers: a cabinet of twelve locker doors, four across and three
 * high, each door with a handle by its free edge, hinged on its left. The
 * pointer picks a locker on the cabinet's face: its door swings open on the
 * parcel inside, and the doors around it come ajar, staggered from it. At
 * rest one door stands open on a parcel, bright. The slider is the stagger.
 *
 * The pattern: one of many on a face. Tweens per door; the hit is read on the
 * face plane, which never moves.
 */
const {
  Cam, clamp, facing, fit, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NC = 4, NR = 3, CW = 24, CH = 22, D = 26, BASE = 6, IN = 1.3, TK = 1.4, OPEN = 105, AJAR = 16;
const W = NC * CW, H = BASE + NR * CH + 3, FAV = [1, 1];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D + CW, 0], [0, 0, H], [W, 0, H], [0, D + CW, H - 3]], 200, 162);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const [cr, ci] = rings(0, 0, W, D, 3, 1.3);
  put(solid(g), prism(P, front, cr, ci, 0, H));
  const onFace = (x, z) => P(x, D, z);
  // plinth line across the face
  mk("path", { d: seg(onFace(1, BASE - 1.5), onFace(W - 1, BASE - 1.5)), class: "nf lo" }, g);

  const doors = [];
  for (let c = 0; c < NC; c++) for (let r = 0; r < NR; r++) {
    const x0 = c * CW + IN, x1 = (c + 1) * CW - IN, z0 = BASE + r * CH + IN, z1 = BASE + (r + 1) * CH - IN;
    // the compartment's mouth and the parcel inside, painted before the door that hides them
    mk("path", { d: poly([onFace(x0, z0), onFace(x1, z0), onFace(x1, z1), onFace(x0, z1)]), class: "nf lo" }, g);
    const px0 = x0 + 4, px1 = x1 - 4, pz1 = z0 + CH * 0.62, mid = (px0 + px1) / 2;
    const at = (x, z) => P(x, D - 2, z);
    mk("path", { d: poly([at(px0, z0 + 1), at(px1, z0 + 1), at(px1, pz1), at(px0, pz1)]) }, g);
    mk("path", { d: seg(at(mid, z0 + 1), at(mid, pz1)), class: "nf lo" }, g);
    const grp = mk("g", {}, g);
    const back = mk("path", { class: "lo" }, grp), face = mk("path", { class: "sil" }, grp), handle = mk("path", { class: "nf" }, grp);
    const fav = c === FAV[0] && r === FAV[1];
    doors.push({ c, r, x0, x1, z0, z1, back, face, handle, a: tween(fav ? OPEN * 0.8 : 0), last: NaN });
  }

  function draw(d, a) {
    const cs = Math.cos(rad(a)), sn = Math.sin(rad(a)), w = d.x1 - d.x0;
    const pt = (u, z, t) => P(d.x0 + u * cs + sn * t, D + 0.4 + u * sn - cs * t, z);
    const out = (t) => poly([pt(0, d.z0, t), pt(w, d.z0, t), pt(w, d.z1, t), pt(0, d.z1, t)]);
    const shows = a < 45; // past 45 degrees the door's inside faces the viewer
    d.back.setAttribute("d", out(shows ? -TK : 0));
    d.face.setAttribute("d", out(shows ? 0 : -TK));
    const hz = (d.z0 + d.z1) / 2, t = shows ? 0 : -TK;
    d.handle.setAttribute("d", seg(pt(w - 3, hz - 3.5, t), pt(w - 3, hz + 3.5, t)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const d of doors) {
      const a = tval(d.a, now);
      if (a !== d.last) { draw(d, a); d.last = a; }
      if (!tdone(d.a, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  /** The locker under the point, read on the cabinet's face plane (y = D), which never moves. */
  function hit([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    if (x < 0 || x > W || z < BASE || z > BASE + NR * CH) return -1;
    return clamp(Math.floor(x / CW), 0, NC - 1) * NR + clamp(Math.floor((z - BASE) / CH), 0, NR - 1);
  }

  let act = -2;
  const favI = FAV[0] * NR + FAV[1];
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const ac = a >= 0 ? doors[a] : null, fc = from >= 0 ? doors[from] : null;
    doors.forEach((d, i) => {
      const dist = ac ? Math.abs(d.c - ac.c) + Math.abs(d.r - ac.r) : 0;
      const th = a < 0 ? (i === favI ? OPEN * 0.8 : 0) : dist === 0 ? OPEN : dist === 1 ? AJAR : 0;
      tset(d.a, th, now, fc ? (Math.abs(d.c - fc.c) + Math.abs(d.r - fc.r)) * stag : 0);
      d.face.classList.toggle("hi", i === (a < 0 ? favI : a));
    });
    read.textContent = a < 0 ? "rest" : `locker ${ac.c + 1}·${NR - ac.r}`;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "lockers",
  means: "Twelve parcel lockers: the door under the pointer swings open on its parcel, and the doors around it come ajar.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[145, 178], [200, 150], [255, 148], null],
  mount,
});

serverrack.code:
/**
 * Server rack: a cabinet of eight blades, each with a pull handle, vents and
 * a status light on its face. The pointer's height says where the update is:
 * the blades near it slide out of the rack, the farther the less, each on its
 * own spring, and the one under it is bright. At rest a few blades stand half
 * out where the last update stopped. The slider is the reach, in blades.
 *
 * The pattern: a field along one axis (terrain). The pick is read on the
 * cabinet's face plane, which never moves.
 */
const {
  Cam, clamp, facing, fit, poly, prism, proj, rings, seg, spring, stepS,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const N = 8, W = 64, D = 48, BH = 10, GAP = 2.4, Z0 = 7, OUT = 28, IN = 4;
const H = Z0 + N * (BH + GAP) + 5;
const REST = [0, 0, 5, 13, 7, 0, 0, 0], FAV = 3;
const fall = (u) => (u <= 0.5 ? 1 : u <= 1 ? 1 - (u - 0.5) * 1.5 : 0.1);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value, over = null;
  const C = Cam(45, 0.5, 1.78);
  fit(C, [[0, 0, 0], [W, D + OUT, 0], [W, 0, 0], [0, D + OUT, 0], [0, 0, H], [W, 0, H]], 200, 162);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  // the cabinet's body, then the mouth of its open front, behind the blades
  const [cr, ci] = rings(0, 0, W, D, 2.5, 1.2);
  put(solid(g), prism(P, front, cr, null, 0, H));
  const f = (x, z) => P(x, D, z);
  mk("path", { d: poly([f(2.5, 3), f(W - 2.5, 3), f(W - 2.5, H - 3), f(2.5, H - 3)]), class: "nf lo" }, g);

  const blades = [];
  for (let k = 0; k < N; k++) {
    const z0 = Z0 + k * (BH + GAP), el = solid(g), face = mk("g", {}, el.g);
    const vents = mk("path", { class: "nf lo" }, face), handle = mk("path", { class: "nf" }, face);
    const led = mk("circle", { r: 1.3, class: k === FAV ? "dot" : "dot off" }, face);
    blades.push({ k, z0, el, vents, handle, led, sp: spring(REST[k], { eps: 0.05 }), drawn: NaN });
  }
  // the cabinet's side and top, painted over the blades' insides
  const side = mk("path", { class: "sil" }, g), top = solid(g);
  side.setAttribute("d", poly([P(W, 0, 0), P(W, D, 0), P(W, D, H), P(W, 0, H)]));
  put(top, prism(P, front, cr, ci, H - 0.01, H));

  function draw(b) {
    const s = Math.max(0, b.sp.x);
    if (s === b.drawn) return;
    b.drawn = s;
    const [r, i] = rings(IN, s, W - IN, D + s, 1.4, 0.8);
    put(b.el, prism(P, front, r, i, b.z0, b.z0 + BH));
    const y = D + s, zm = b.z0 + BH / 2, q = (x, z) => P(x, y, z);
    let v = "";
    for (let x = IN + 6; x < IN + 26; x += 3.2) v += seg(q(x, zm - 2.2), q(x, zm + 2.2));
    b.vents.setAttribute("d", v);
    b.handle.setAttribute("d", seg(q(W - IN - 14, zm), q(W - IN - 6, zm)));
    place(b.led, q(IN + 3.5, zm));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const b of blades) { if (stepS(b.sp, dt)) m = true; draw(b); }
    return m;
  });
  bag.add(B.unregister);

  /** The height on the cabinet's face (y = D) under the point; null off the face. */
  function height([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    return x < -6 || x > W + 6 || z < 0 || z > H ? null : z;
  }

  function retarget() {
    let mark = FAV;
    if (over == null) blades.forEach((b) => (b.sp.t = REST[b.k]));
    else {
      blades.forEach((b) => (b.sp.t = OUT * fall(Math.abs(b.z0 + BH / 2 - over) / (reach * (BH + GAP)))));
      mark = clamp(Math.floor((over - Z0) / (BH + GAP)), 0, N - 1);
    }
    blades.forEach((b) => { b.el.sil.classList.toggle("hi", b.k === mark); b.led.setAttribute("class", b.k === mark ? "dot" : "dot off"); });
    read.textContent = over == null ? "rest" : "blade " + (mark + 1);
    B.wake();
  }

  bag.add(pointer(stage, { move: (p) => { over = height(p); retarget(); }, leave: () => { over = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; if (over != null) retarget(); }, destroy: bag.dispose };
}

