padlocks.code:
/**
 * Padlocks: five padlocks hung on a rail, each a rounded body with a keyhole
 * under a U-shaped shackle. The pointer picks a lock: its shackle springs up
 * open, and the shackles beside it lift a little, staggered from it. At rest
 * one lock hangs open, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the lock
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fit, facing, open, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const N = 5, BW = 20, BD = 12, BH = 22, GAP = 12, SR = 6, LEG = 9, OPEN = 11, FAV = 2;
const X1 = N * BW + (N - 1) * GAP, RAIL = BH + LEG + SR + 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-8, 0, 0], [X1 + 8, BD, 0], [X1 + 8, 0, 0], [-8, BD, 0], [-8, BD / 2, RAIL + 4], [X1 + 8, BD / 2, RAIL + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the rail the locks hang from: a bar on two posts
  const [pr, pi] = rings(-8, BD / 2 - 2, -4, BD / 2 + 2, 1, 0.5);
  put(solid(g), prism(P, front, pr, pi, 0, RAIL + 3));
  const [rr, ri] = rings(-8, BD / 2 - 1.6, X1 + 8, BD / 2 + 1.6, 1.4, 0.5);
  const rail = solid(g);

  const locks = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * (BW + GAP), cx = x0 + BW / 2;
    const shackle = mk("path", { class: "nf sil" }, g);
    const body = solid(g), hole = mk("path", { class: "nf" }, body.g);
    const [r, i] = rings(x0, 0, x0 + BW, BD, 3.5, 1.4);
    put(body, prism(P, front, r, i, 0, BH));
    const kz = BH * 0.45;
    hole.setAttribute("d", seg(P(cx, BD, kz - 1), P(cx, BD, kz - 5)));
    place(mk("circle", { r: 1.6, class: "dot m" }, body.g), P(cx, BD, kz));
    locks.push({ k, cx, shackle, body, z: tween(k === FAV ? OPEN : 0), last: NaN });
  }
  put(rail, prism(P, front, rr, ri, RAIL, RAIL + 3));
  const [qr, qi] = rings(X1 + 4, BD / 2 - 2, X1 + 8, BD / 2 + 2, 1, 0.5);
  put(solid(g), prism(P, front, qr, qi, 0, RAIL + 3));

  /** The shackle lifted z: two legs and the arch, in the lock's middle plane; open, the left leg clears the body. */
  function draw(l, z) {
    if (z === l.last) return;
    l.last = z;
    const y = BD / 2, base = BH + z, top = base + LEG, arc = [];
    for (let i = 0; i <= 12; i++) { const t = Math.PI - (Math.PI * i) / 12; arc.push(P(l.cx + SR * Math.cos(t), y, top + SR * Math.sin(t))); }
    const leftFoot = z > 0.5 ? base + Math.min(z, 5) : BH - 1;
    l.shackle.setAttribute("d", open([P(l.cx - SR, y, leftFoot), ...arc, P(l.cx + SR, y, BH - 1)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const l of locks) { draw(l, tval(l.z, now)); if (!tdone(l.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = locks.map((l) => P(l.cx, BD, BH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 20 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    locks.forEach((l, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? OPEN : 0) : dd === 0 ? OPEN : dd === 1 ? 3 : 0;
      tset(l.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      l.shackle.setAttribute("class", on ? "nf hi" : "nf sil");
      l.body.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "lock " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "padlocks",
  means: "Five padlocks on a rail: the shackle of the one under the pointer springs open, and its neighbours lift a little.",
  rules: [1, 2, 5, 10],
  range: [0, 45, 90],
  tour: [[115, 150], [233, 206], [272, 224], null],
  mount,
});

cropfield.code:
/**
 * Crop field: four raised beds of soil, each with a row of six seedlings, a
 * stem and two leaves apiece. The pointer is the sun and the rain: the plants
 * near it grow tall and open their leaves, the farther the less, each on its
 * own spring. At rest the field is young, a little taller toward the back.
 * The slider is the reach, in plants.
 *
 * The pattern: a continuous field (terrain), on plants; the hit is on the
 * ground plane, which never moves.
 */
const {
  Cam, clamp, facing, fit, open, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NX = 6, NY = 4, SX = 18, SY = 24, BEDW = 12, BEDH = 5, HMAX = 34;
const EX = NX * SX, EY = NY * SY;
const falloff = (u) => (u <= 0.4 ? 1 : u <= 1 ? 1 - ((u - 0.4) / 0.6) * 0.78 : 0.22);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * SX, over = null;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-6, -6, -3], [EX + 6, EY + 6, -3], [EX + 6, -6, -3], [-6, EY + 6, -3], [0, 0, BEDH + HMAX + 6]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [gr, gi] = rings(-6, -6, EX + 6, EY + 6, 8, 2);
  put(solid(g), prism(P, front, gr, gi, -3, 0));

  const plants = [];
  for (let j = 0; j < NY; j++) {
    // the bed for row j, then its plants back to front
    const y0 = j * SY + (SY - BEDW) / 2;
    const [br, bi] = rings(2, y0, EX - 2, y0 + BEDW, 4, 1.4);
    put(solid(g), prism(P, front, br, bi, 0, BEDH));
    for (let i = 0; i < NX; i++) {
      const cx = (i + 0.5) * SX, cy = j * SY + SY / 2;
      const h0 = 7 + (NY - 1 - j) * 2.5 + ((i * 5 + j * 3) % 4);
      const stem = mk("path", { class: "nf sil" }, g), leaves = mk("path", { class: "nf" }, g);
      plants.push({ i, j, cx, cy, h0, stem, leaves, sp: spring(h0, { eps: 0.04 }), drawn: NaN });
    }
  }

  /** A seedling h tall: a stem, and two leaves that open wider as it grows. */
  function draw(p) {
    const h = Math.max(3, p.sp.x);
    if (h === p.drawn) return;
    p.drawn = h;
    const z0 = BEDH, top = z0 + h, s = clamp(h / HMAX, 0.25, 1), L = 6 + 9 * s;
    p.stem.setAttribute("d", open([P(p.cx, p.cy, z0), P(p.cx + 0.6, p.cy, z0 + h * 0.5), P(p.cx, p.cy, top)]));
    const zl = top - h * 0.35, leaf = (dx, dz) => open([P(p.cx, p.cy, zl), P(p.cx + dx * 0.45, p.cy, zl + dz + 3.5), P(p.cx + dx, p.cy, zl + dz), P(p.cx + dx * 0.5, p.cy, zl + dz - 2.2), P(p.cx, p.cy, zl)]);
    p.leaves.setAttribute("d", leaf(-L, 2 + 4 * s) + leaf(L, 1 + 4 * s));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const p of plants) { if (stepS(p.sp, dt)) m = true; draw(p); }
    return m;
  });
  bag.add(B.unregister);

  const tallest = plants.reduce((a, b) => (b.h0 > a.h0 ? b : a));
  function retarget() {
    let mark = tallest;
    for (const p of plants) p.sp.t = over ? HMAX * falloff(Math.hypot(p.cx - over[0], p.cy - over[1]) / RAD) : p.h0;
    if (over) {
      const i = clamp(Math.floor(over[0] / SX), 0, NX - 1), j = clamp(Math.floor(over[1] / SY), 0, NY - 1);
      mark = plants.find((p) => p.i === i && p.j === j);
      read.textContent = `row ${j + 1}·${i + 1}`;
    } else read.textContent = "rest";
    for (const p of plants) { p.stem.setAttribute("class", p === mark ? "nf hi" : "nf sil"); }
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (pt) => { const q = unproj(C, pt[0], pt[1], BEDH); over = [clamp(q[0], 0, EX), clamp(q[1], 0, EY)]; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v * SX; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "cropfield",
  means: "Four beds of seedlings: the plants near the pointer grow tall and open their leaves, the farther ones less.",
  rules: [1, 3, 5, 8],
  range: [1.5, 2.5, 4],
  tour: [[150, 190], [250, 170], [210, 235], null],
  mount,
});

dumbbells.code:
/**
 * Dumbbells: six dumbbells resting across a rack, light to heavy, each two
 * round plates on a short grip. The pointer picks one by where it rests: it
 * lifts off the rack, and the ones beside it rise a little, staggered from
 * it. At rest the heaviest pair is lifted, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = [4.5, 5, 5.6, 6.2, 6.8, 7.6], PT = 3.6, GRIP = 9, STEP = 19, RACK = 16, LIFT = 18, FAV = 5;
const X1 = (R.length - 1) * STEP + 20, YL = PT * 2 + GRIP;

/** A round plate with its axis along y, from y0 to y1, centred at (x, z): its outline and its front face. */
function plate(P, x, z, r, y0, y1) {
  const ring = (y) => Array.from({ length: 28 }, (_, i) => { const t = (i / 28) * Math.PI * 2; return P(x + r * Math.cos(t), y, z + r * Math.sin(t)); });
  return { sil: poly(hull(ring(y0).concat(ring(y1)))), face: poly(ring(y1)) };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-6, -6, 0], [X1 + 6, YL + 8, 0], [X1 + 6, -6, 0], [-6, YL + 8, 0], [0, 0, RACK + 8 + LIFT + 2], [X1, 0, RACK + 8 + LIFT + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the rack: a board on two feet
  for (const x0 of [2, X1 - 8]) { const [r, i] = rings(x0, -2, x0 + 6, YL + 4, 1.2, 0.6); put(solid(g), prism(P, front, r, i, 0, RACK - 3)); }
  const [br, bi] = rings(-4, -4, X1 + 4, YL + 6, 2.5, 1.2);
  put(solid(g), prism(P, front, br, bi, RACK - 3, RACK));

  const bells = R.map((r, k) => {
    const x = 10 + k * STEP, grp = mk("g", {}, g);
    const back = mk("path", { class: "sil" }, grp), backFace = mk("path", { class: "nf lo" }, grp);
    const grip = mk("path", { class: "nf sil" }, grp);
    const frontP = mk("path", { class: "sil" }, grp), frontFace = mk("path", { class: "nf lo" }, grp);
    return { k, x, r, grp, back, backFace, grip, frontP, frontFace, z: tween(k === FAV ? LIFT * 0.75 : 0), last: NaN };
  });

  function draw(b, lift) {
    if (lift === b.last) return;
    b.last = lift;
    const z = RACK + b.r + lift, y0 = 1, y1 = y0 + PT, y2 = y1 + GRIP, y3 = y2 + PT;
    const a = plate(P, b.x, z, b.r, y0, y1), c = plate(P, b.x, z, b.r, y2, y3);
    b.back.setAttribute("d", a.sil); b.backFace.setAttribute("d", a.face);
    b.grip.setAttribute("d", seg(P(b.x, y1, z + 1.3), P(b.x, y2, z + 1.3)) + seg(P(b.x, y1, z - 1.3), P(b.x, y2, z - 1.3)));
    b.frontP.setAttribute("d", c.sil); b.frontFace.setAttribute("d", c.face);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of bells) { draw(b, tval(b.z, now)); if (!tdone(b.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = bells.map((b) => P(b.x, YL / 2, RACK + b.r));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 16 && Math.abs(mids[best][1] - sy) < 55 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    bells.forEach((b, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.75 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(b.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      b.back.classList.toggle("hi", on); b.frontP.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "dumbbell " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "dumbbells",
  means: "Six dumbbells on a rack, light to heavy: the one under the pointer lifts off, and its neighbours rise a little.",
  rules: [1, 2, 5, 9],
  range: [0, 45, 90],
  tour: [[122, 121], [185, 152], [282, 196], null],
  mount,
});

swatchfan.code:
/**
 * Swatch fan: nine colour cards fanned out from a pin, each card ruled into
 * three swatches, a hole at its foot. The pointer picks the card pointing its
 * way: it slides out along its length and lifts, and the cards beside it lean
 * away, staggered from it. At rest the fan is open with one card drawn out,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many round a pivot (riffle). The pick is the card whose
 * resting angle is nearest the pointer's angle about the pin.
 */
const {
  Cam, circ, clamp, fit, facing, fillet, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 9, L = 78, W = 15, TK = 0.9, A0 = -18, SPREAD = 8, OUT = 12, LEAN = 4, FAV = 5;
const restA = (k) => A0 + k * SPREAD;
const SHAPE = fillet([[0, -W / 2], [L, -W / 2], [L, W / 2], [0, W / 2]], [W / 2, 2.5, 2.5, W / 2]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.2);
  const ext = [];
  // every card's far corners at its widest lean and furthest slide, the stack's top and foot, and the pin
  for (let a = A0 - LEAN; a <= restA(N - 1) + LEAN; a += 4) for (const v of [-W / 2, W / 2]) for (const z of [0, N * 1.2 + 6]) {
    const u = L + OUT; ext.push([u * Math.cos(rad(a)) - v * Math.sin(rad(a)), u * Math.sin(rad(a)) + v * Math.cos(rad(a)), z]);
  }
  fit(C, [...ext, [-W / 2, -W / 2, 0], [W / 2, W / 2, N * 1.2 + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const cards = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    const edge = mk("path", { class: "lo" }, grp), face = mk("path", { class: "sil" }, grp), lines = mk("path", { class: "nf lo" }, grp);
    cards.push({ k, grp, edge, face, lines, a: tween(restA(k)), s: tween(k === FAV ? OUT * 0.7 : 0), last: "" });
  }
  // the pin through every card's foot, over the stack
  const pin = solid(g);
  { const ring = circ(3.2, 24), inner = circ(2, 24); put(pin, prism(P, front, ring, inner, 0, N * 1.2 + 3)); }

  function draw(c, a, s) {
    const key = a.toFixed(2) + "," + s.toFixed(2);
    if (key === c.last) return;
    c.last = key;
    const ca = Math.cos(rad(a)), sa = Math.sin(rad(a)), z = 1 + c.k * 1.2 + (s > 0.1 ? s * 0.3 : 0);
    const w = (u, v, zz = z) => P((u + s) * ca - v * sa, (u + s) * sa + v * ca, zz);
    c.face.setAttribute("d", poly(SHAPE.map(([u, v]) => w(u, v))));
    c.edge.setAttribute("d", poly(SHAPE.map(([u, v]) => w(u, v, z - TK))));
    let d = "";
    for (const u of [L * 0.4, L * 0.6, L * 0.8]) d += seg(w(u, -W / 2 + 1.2), w(u, W / 2 - 1.2));
    c.lines.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of cards) { draw(c, tval(c.a, now), tval(c.s, now)); if (!tdone(c.a, now) || !tdone(c.s, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  /** The card whose resting angle is nearest the pointer's angle about the pin, on the ground plane. */
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, N * 0.6), r = Math.hypot(x, y);
    if (r < 10 || r > L + OUT + 8) return -1;
    const ang = (Math.atan2(y, x) * 180) / Math.PI;
    if (ang < A0 - SPREAD || ang > restA(N - 1) + SPREAD) return -1;
    return clamp(Math.round((ang - A0) / SPREAD), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cards.forEach((c, k) => {
      const delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(c.a, a < 0 ? restA(k) : restA(k) + (k < a ? -LEAN : k > a ? LEAN : 0), now, delay);
      tset(c.s, a < 0 ? (k === FAV ? OUT * 0.7 : 0) : k === a ? OUT : 0, now, delay);
      c.face.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "card " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "swatchfan",
  means: "A fan of nine colour cards: the card pointing toward the pointer slides out, and the cards beside it lean away.",
  rules: [1, 2, 5, 10],
  range: [0, 40, 80],
  tour: [[243, 143], [187, 169], [110, 183], null],
  mount,
});

spotlights.code:
/**
 * Spotlights: four stage lamps hung from a truss over a round stage, each a
 * flared can on a yoke. The pointer is where the light should fall: every
 * lamp turns to aim at it, the spot on the stage follows on a spring, and the
 * lamp nearest it is bright. At rest the lamps meet on a spot left of centre.
 * The slider is how quickly the lamps follow (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (terrain's spring, on an angle); the hit is on
 * the stage's plane, which never moves.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RS = 62, TRUSS = 92, HANG = 12, XS = [-48, -16, 16, 48], LEN = 18, RB = 5, RF = 7.5;
const REST = [-14, 10];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[-RS, -RS, -6], [RS, RS, -6], [RS, -RS, -6], [-RS, RS, -6], [-58, 0, TRUSS + 4], [58, 0, TRUSS + 4]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(RS, 72), circ(RS - 2, 72), -6, 0));
  const spotEl = mk("path", { class: "nf hi" }, g);
  // the truss: one bar along x, and the lamps under it, far to near
  const [tr, ti] = rings(-58, -2.5, 58, 2.5, 1.5, 0.6);
  put(solid(g), prism(P, front, tr, ti, TRUSS, TRUSS + 5));
  const lamps = XS.map((x, k) => {
    const yoke = mk("path", { class: "nf sil" }, g), body = mk("path", { class: "sil" }, g), lens = mk("path", { class: "nf" }, g);
    return { k, c: [x, 0, TRUSS - HANG], yoke, body, lens };
  });
  const tx = spring(REST[0], { k: 100 * value, c: 18 * Math.sqrt(value) }), ty = spring(REST[1], { k: 100 * value, c: 18 * Math.sqrt(value) });
  let lastKey = "", over = null;

  /** A can from back (radius RB) to a flared front (RF), along d from its middle. */
  function can(l, d) {
    const [cx, cy, cz] = l.c, z = [0, 0, 1];
    let u = [d[1] * z[2] - d[2] * z[1], d[2] * z[0] - d[0] * z[2], d[0] * z[1] - d[1] * z[0]];
    const un = Math.hypot(...u) || 1; u = u.map((x) => x / un);
    const v = [u[1] * d[2] - u[2] * d[1], u[2] * d[0] - u[0] * d[2], u[0] * d[1] - u[1] * d[0]];
    const ring = (off, r) => Array.from({ length: 24 }, (_, i) => {
      const t = (i / 24) * Math.PI * 2, q = (j) => [cx, cy, cz][j] + d[j] * off + r * (Math.cos(t) * u[j] + Math.sin(t) * v[j]);
      return P(q(0), q(1), q(2));
    });
    const back = ring(-LEN / 2, RB), lensRing = ring(LEN / 2, RF);
    l.body.setAttribute("d", poly(hull(back.concat(lensRing))));
    l.lens.setAttribute("d", poly(lensRing));
    l.yoke.setAttribute("d", seg(P(cx, cy, TRUSS), P(cx, cy, cz + RB)));
  }

  function draw() {
    const key = tx.x.toFixed(2) + "," + ty.x.toFixed(2);
    if (key === lastKey) return;
    lastKey = key;
    for (const l of lamps) {
      const d = [tx.x - l.c[0], ty.x - l.c[1], 0 - l.c[2]], n = Math.hypot(...d);
      can(l, d.map((x) => x / n));
    }
    const ring = circ(9, 40).map((q) => P(tx.x + q.u, ty.x + q.v, 0.2));
    spotEl.setAttribute("d", poly(ring));
  }

  const B = register(stage, (dt) => { const a = stepS(tx, dt), b = stepS(ty, dt); draw(); return a || b; });
  bag.add(B.unregister);

  function retarget() {
    const [x, y] = over ?? REST;
    tx.t = x; ty.t = y;
    let near = -1;
    if (over) { let bd = Infinity; lamps.forEach((l, k) => { const dd = Math.abs(l.c[0] - x); if (dd < bd) { bd = dd; near = k; } }); }
    lamps.forEach((l, k) => l.body.classList.toggle("hi", k === near));
    read.textContent = over ? `lamp ${near + 1} · ${Math.round(Math.hypot(x, y))}` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y), k = Math.min(1, (RS - 10) / r);
      over = r > RS + 30 ? null : [x * k, y * k];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { tx.k = ty.k = 100 * v; tx.c = ty.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "spotlights",
  means: "Four stage lamps on a truss: they turn to aim where the pointer is, and the spot follows across the stage.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[140, 230], [260, 230], [200, 260], null],
  mount,
});

testtubes.code:
/**
 * Test tubes: six glass tubes standing in a two-deck rack, each with a
 * rounded foot, a lip at the mouth and liquid filled to its own level. The
 * pointer picks a tube by where it stands: it lifts out of the rack, and the
 * tubes beside it rise a little, staggered from it. At rest one tube stands
 * raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, STEP = 15, R = 4.6, TL = 52, DECK = 26, RW = 12, LIFT = 22, FAV = 2;
const LEVEL = [0.55, 0.35, 0.7, 0.45, 0.6, 0.3];
const X1 = (N - 1) * STEP + 16;
const ringAtXY = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-6, -6, 0], [X1 + 6, RW + 6, 0], [X1 + 6, -6, 0], [-6, RW + 6, 0], [0, RW / 2, TL + LIFT + 4], [X1, RW / 2, TL + LIFT + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the rack: a base, two end posts and the upper deck with a hole per tube
  const [br, bi] = rings(-6, -2, X1 + 6, RW + 2, 2.5, 1.2);
  put(solid(g), prism(P, front, br, bi, 0, 3));
  for (const x0 of [-6, X1 + 2]) { const [r, i] = rings(x0, 0, x0 + 4, RW, 1, 0.5); put(solid(g), prism(P, front, r, i, 3, DECK)); }

  const tubes = [];
  for (let k = 0; k < N; k++) {
    const x = 8 + k * STEP, y = RW / 2, grp = mk("g", {}, g);
    const glass = mk("path", { class: "sil" }, grp), liquid = mk("path", { class: "nf lo" }, grp), lip = mk("path", { class: "nf" }, grp);
    tubes.push({ k, x, y, grp, glass, liquid, lip, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }
  const deck = solid(g);
  const [dr, di] = rings(-6, -1, X1 + 6, RW + 1, 2, 1);
  put(deck, prism(P, front, dr, di, DECK, DECK + 3));
  const holes = mk("path", { class: "nf lo" }, deck.g);
  holes.setAttribute("d", tubes.map((t) => poly(ringAt(P, ringAtXY(t.x, t.y, R + 0.8), DECK + 3))).join(""));
  // tubes rise through the deck: the part above it is drawn again after the deck
  const tops = tubes.map((t) => { const grp = mk("g", {}, g); return { grp, glass: mk("path", { class: "sil" }, grp), liquid: mk("path", { class: "nf lo" }, grp), lip: mk("path", { class: "nf" }, grp) }; });

  function shape(t, lift, from) {
    const z0 = 3 + lift, z1 = z0 + TL, foot = [];
    for (let i = 0; i <= 10; i++) { const a = Math.PI + (Math.PI * i) / 10; foot.push(P(t.x + R * Math.cos(a), t.y + R * Math.sin(a) * 0.0, z0 + R + R * Math.sin(a))); }
    const ring = ringAtXY(t.x, t.y, R), lo = Math.max(z0 + R, from);
    const pts = ringAt(P, ring, z1).concat(ringAt(P, ring, lo)).concat(lo <= z0 + R ? ringAt(P, ringAtXY(t.x, t.y, R * 0.55), z0 + 0.8) : []);
    const lvl = z0 + R + (TL - R - 6) * LEVEL[t.k];
    return {
      glass: poly(hull(pts)),
      liquid: lvl > from ? open(ringAt(P, run(ring, front), lvl)) : "",
      lip: poly(ringAt(P, ringAtXY(t.x, t.y, R + 1), z1)),
    };
  }

  function draw(t, i, lift) {
    if (lift === t.last) return;
    t.last = lift;
    const a = shape(t, lift, 0), b = shape(t, lift, DECK + 3);
    t.glass.setAttribute("d", a.glass); t.liquid.setAttribute("d", a.liquid); t.lip.setAttribute("d", "");
    const top = tops[i];
    top.glass.setAttribute("d", b.glass); top.liquid.setAttribute("d", b.liquid); top.lip.setAttribute("d", b.lip);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    tubes.forEach((t, i) => { draw(t, i, tval(t.z, now)); if (!tdone(t.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  const mids = tubes.map((t) => P(t.x, t.y, TL * 0.6));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 12 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    tubes.forEach((t, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 6 : 0;
      tset(t.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      tops[k].glass.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tube " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "testtubes",
  means: "Six test tubes in a rack: the one under the pointer lifts out, and the tubes beside it rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[135, 124], [213, 163], [265, 189], null],
  mount,
});

brickwall.code:
/**
 * Brick wall: a garden wall of thirty bricks in running bond on a footing,
 * with a coping course on top. The pointer presses on the wall's face: the
 * bricks near it push out toward the reader, the farther the less, each on
 * its own spring. At rest a few bricks stand proud near one corner, as if
 * the wall were half built. The slider is the reach, in bricks.
 *
 * The pattern: a continuous field on a face (terrain, turned upright); the hit
 * is read on the wall's face plane, which never moves.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const COLS = 6, ROWS = 5, BW = 20, BH = 8, D = 10, J = 0.9, OUT = 9, FOOT = 4;
const W = COLS * BW, H = FOOT + ROWS * BH;
const fall = (u) => (u <= 0.35 ? 1 : u <= 1 ? 1 - ((u - 0.35) / 0.65) * 0.9 : 0.1);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value, over = null;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-4, -2, 0], [W + 4, D + OUT + 2, 0], [W + 4, -2, 0], [-4, D + OUT, 0], [-4, 0, H + 6], [W + 4, 0, H + 6]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-4, -2, W + 4, D + 3, 1.5, 0.8);
  put(solid(g), prism(P, front, fr, fi, 0, FOOT));

  const bricks = [];
  for (let r = 0; r < ROWS; r++) {
    const off = r % 2 ? -BW / 2 : 0;
    for (let c = 0; c <= COLS; c++) {
      let x0 = c * BW + off, x1 = x0 + BW;
      x0 = Math.max(0, x0); x1 = Math.min(W, x1);
      if (x1 - x0 < 4) continue;
      const z0 = FOOT + r * BH, cx = (x0 + x1) / 2, cz = z0 + BH / 2;
      const rest = Math.max(0, 6 - Math.hypot((cx - W * 0.85) / BW, (cz - H * 0.8) / BH) * 2.4);
      bricks.push({ r, x0, x1, z0, cx, cz, rest, el: solid(g), sp: spring(rest, { eps: 0.03 }), drawn: NaN });
    }
  }
  const coping = solid(g);
  { const [r, i] = rings(-2, -1.5, W + 2, D + 1.5, 1.2, 0.7); put(coping, prism(P, front, r, i, H + 0.4, H + 3.6)); }

  // proud bricks paint after flush ones; within a course, left to right
  let painted = "";
  function order() {
    const o = bricks.slice().sort((a, b) => a.sp.x - b.sp.x || a.cx + a.cz * 0.01 - (b.cx + b.cz * 0.01));
    const key = o.map((b) => bricks.indexOf(b)).join();
    if (key !== painted) { painted = key; for (const b of o) g.appendChild(b.el.g); g.appendChild(coping.g); }
  }
  function draw(b) {
    const s = Math.max(0, b.sp.x);
    if (s === b.drawn) return;
    b.drawn = s;
    const [r, i] = rings(b.x0 + J / 2, s, b.x1 - J / 2, D + s, 1, 0.5);
    put(b.el, prism(P, front, r, i, b.z0 + J / 2, b.z0 + BH - J / 2));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const b of bricks) { if (stepS(b.sp, dt)) m = true; draw(b); }
    order();
    return m;
  });
  bag.add(B.unregister);

  /** Where the point lands on the wall's face (y = D), which never moves; null off the wall. */
  function onFace([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    return x < -6 || x > W + 6 || z < FOOT - 4 || z > H + 6 ? null : [x, z];
  }

  const restMark = bricks.reduce((a, b) => (b.rest > a.rest ? b : a));
  function retarget() {
    let mark = restMark;
    for (const b of bricks) b.sp.t = over ? OUT * fall(Math.hypot((b.cx - over[0]) / BW, (b.cz - over[1]) / BH) / reach) : b.rest;
    if (over) {
      mark = bricks.reduce((a, b) => (Math.hypot(b.cx - over[0], (b.cz - over[1]) * 2) < Math.hypot(a.cx - over[0], (a.cz - over[1]) * 2) ? b : a));
      read.textContent = `brick ${ROWS - mark.r}·${clamp(Math.floor(mark.cx / BW) + 1, 1, COLS + 1)}`;
    } else read.textContent = "rest";
    for (const b of bricks) b.el.sil.classList.toggle("hi", b === mark);
    B.wake();
  }

  bag.add(pointer(stage, { move: (p) => { over = onFace(p); retarget(); }, leave: () => { over = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "brickwall",
  means: "A brick wall: the bricks near the pointer push out toward you, the nearest furthest.",
  rules: [1, 3, 5, 6],
  range: [1, 1.8, 3],
  tour: [[140, 150], [210, 200], [260, 190], null],
  mount,
});

wrenches.code:
/**
 * Wrenches: a fitted tray of six spanners lying in size order, each a flat
 * handle with an open jaw at one end and a ring at the other. The pointer
 * picks a spanner by where it lies: it lifts out of the tray, and the ones
 * beside it rise a little, staggered from it. At rest one spanner is lifted,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), lying flat.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SIZES = [0.72, 0.8, 0.88, 0.96, 1.04, 1.12], GAP = 15, LEN = 74, TK = 1.6, LIFT = 14, FAV = 3;
const X1 = SIZES.length * GAP + 10;

/** A spanner's outline in its own plane (u along it, v across), scale s: an open jaw, a waisted handle, a ring. */
function outline(s) {
  const pts = [], jaw = 7 * s, ring = 6 * s, hw = 2.6 * s, L = LEN * (0.8 + 0.2 * s);
  // open jaw at u = 0: an arc with a notch
  for (let i = 0; i <= 10; i++) { const a = Math.PI * 0.55 + (Math.PI * 1.45 * i) / 10; pts.push([jaw * Math.cos(a), jaw * Math.sin(a)]); }
  pts.push([jaw * 0.2, -jaw * 0.35], [jaw * 0.2, jaw * 0.35]);
  const jawPts = pts.splice(0);
  const out = [];
  out.push([jaw * 0.6, hw], [L - ring * 1.1, hw]);
  for (let i = 0; i <= 14; i++) { const a = Math.PI * 0.75 - (Math.PI * 1.5 * i) / 14; out.push([L + ring * Math.cos(a), ring * Math.sin(a)]); }
  out.push([L - ring * 1.1, -hw], [jaw * 0.6, -hw]);
  // join: handle top edge, ring, handle bottom edge, then the jaw back round to the start
  return out.concat(jawPts.slice(0, 6).reverse().map(([u, v]) => [u, -Math.abs(v)]), [[jaw * 0.2, -jaw * 0.35], [jaw * 0.2, jaw * 0.35]], jawPts.slice(6).map(([u, v]) => [u, Math.abs(v)]));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-6, -14, -4], [LEN + 20, X1, -4], [LEN + 20, -14, -4], [-6, X1, -4], [LEN / 2, 0, LIFT + 4]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-12, -14, LEN + 22, X1, 6, 2);
  put(solid(g), prism(P, front, tr, ti, -4, 0));

  const tools = SIZES.map((s, k) => {
    const y = k * GAP, grp = mk("g", {}, g);
    const edge = mk("path", { class: "lo" }, grp), face = mk("path", { class: "sil" }, grp);
    // its fitted recess in the tray
    return { k, s, y, shape: outline(s), grp, edge, face, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN };
  });

  function draw(t, z) {
    if (z === t.last) return;
    t.last = z;
    const w = (u, v, zz) => P(u + 4, t.y + v, zz);
    t.edge.setAttribute("d", poly(t.shape.map(([u, v]) => w(u, v, 0.4 + z))));
    t.face.setAttribute("d", poly(t.shape.map(([u, v]) => w(u, v, 0.4 + z + TK))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const t of tools) { draw(t, tval(t.z, now)); if (!tdone(t.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = tools.map((t) => P(LEN / 2, t.y, 1));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    // across the row the spanners lie along +y: the screen direction of y picks them
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    tools.forEach((t, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 4 : 0;
      tset(t.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      t.face.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "spanner " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "wrenches",
  means: "A tray of six spanners in size order: the one under the pointer lifts out, and its neighbours rise a little.",
  rules: [1, 2, 5, 9],
  range: [0, 45, 90],
  tour: [[251, 122], [187, 154], [145, 175], null],
  mount,
});

clothesrack.code:
/**
 * Clothes rack: seven shirts on hangers along a rail on two stands, each a
 * flat shirt with sleeves and a collar notch under a wire hanger. The pointer
 * picks a shirt by where it hangs: it swings out toward the reader on its
 * hook, and the shirts beside it slide apart along the rail, staggered from
 * it. At rest one shirt is swung out a little, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle), hanging.
 */
const {
  Cam, fillet, fit, facing, open, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, STEP = 13, RZ = 86, SW = 34, SWING = 32, PART = 7, FAV = 4;
const X1 = (N - 1) * STEP + 24;
// a shirt in its own plane: w across (centred), d down from the hook
const SHIRT = fillet([
  [-6, 10], [-3, 12], [3, 12], [6, 10], [16, 14], [20, 26], [14, 28], [12, 22], [12, 60], [-12, 60], [-12, 22], [-14, 28], [-20, 26], [-16, 14],
], [1, 2, 2, 1, 3, 2, 2, 1, 2, 2, 1, 2, 2, 3]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-12, -14, 0], [X1 + 12, SW, 0], [X1 + 12, -14, 0], [-12, SW, 0], [-12, 0, RZ + 6], [X1 + 12, 0, RZ + 6], [X1, 36, RZ - 50]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // two stands and the rail
  for (const x of [-10, X1 + 6]) {
    const [fr, fi] = rings(x - 6, -14, x + 10, 14, 3, 1); put(solid(g), prism(P, front, fr, fi, 0, 3));
    const [pr, pi] = rings(x, -1.5, x + 3, 1.5, 1, 0.4); put(solid(g), prism(P, front, pr, pi, 3, RZ + 2));
  }
  const [rr, ri] = rings(-10, -1.4, X1 + 9, 1.4, 1.2, 0.5);
  const railEl = solid(g);
  put(railEl, prism(P, front, rr, ri, RZ, RZ + 2.4));

  const shirts = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    const back = mk("path", { class: "lo" }, grp), face = mk("path", { class: "sil" }, grp);
    const hanger = mk("path", { class: "nf" }, grp), placket = mk("path", { class: "nf lo" }, grp);
    shirts.push({ k, x: 12 + k * STEP, grp, back, face, hanger, placket, a: tween(k === FAV ? SWING * 0.45 : 0), dx: tween(0), last: "" });
  }
  g.appendChild(railEl.g);

  function draw(s, a, dx) {
    const key = a.toFixed(2) + "," + dx.toFixed(2);
    if (key === s.last) return;
    s.last = key;
    const ca = Math.cos(rad(a)), sa = Math.sin(rad(a)), x = s.x + dx;
    // the shirt hangs in the plane x = const and swings about the rail (the x axis) toward +y
    const w = (u, d, off = 0) => P(x + off, u * ca + d * sa, RZ - 4 - (d * ca - u * sa * 0));
    s.face.setAttribute("d", poly(SHIRT.map(([u, d]) => w(u, d))));
    s.back.setAttribute("d", poly(SHIRT.map(([u, d]) => w(u, d, -1))));
    s.hanger.setAttribute("d", open([P(x, 0, RZ + 3), P(x, 0, RZ + 1), w(-15, 12), w(15, 12), P(x, 0, RZ + 1)]));
    s.placket.setAttribute("d", seg(w(0, 13), w(0, 58)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const s of shirts) { draw(s, tval(s.a, now), tval(s.dx, now)); if (!tdone(s.a, now) || !tdone(s.dx, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = shirts.map((s) => P(s.x, 0, RZ - 34));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 12 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    shirts.forEach((s, k) => {
      const delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(s.a, a < 0 ? (k === FAV ? SWING * 0.45 : 0) : k === a ? SWING : 0, now, delay);
      tset(s.dx, a < 0 ? 0 : k < a ? -PART * Math.max(0, 1 - (a - k - 1) * 0.5) : k > a ? PART * Math.max(0, 1 - (k - a - 1) * 0.5) : 0, now, delay);
      s.face.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "shirt " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "clothesrack",
  means: "Seven shirts on a rail: the one under the pointer swings out toward you, and the shirts beside it slide apart.",
  rules: [1, 2, 5, 10],
  range: [0, 40, 80],
  tour: [[164, 123], [212, 147], [261, 172], null],
  mount,
});

cloches.code:
/**
 * Cloches: four domed covers on plates along a counter, each dome with a
 * knob, each plate holding a dish under it. The pointer picks a cloche by
 * where it stands: its dome lifts off the plate to show the dish, and the
 * domes beside it lift a little, staggered from it. At rest one dome is
 * raised, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 40, DR = 15, PR = 18, LIFT = 22, FAV = 1, CZ = 4;
const X1 = (N - 1) * STEP + 2 * PR;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.85);
  fit(C, [[-6, -6, 0], [X1 + 6, 2 * PR + 6, 0], [X1 + 6, -6, 0], [-6, 2 * PR + 6, 0], [PR, PR, CZ + DR + LIFT + 6], [X1 - PR, PR, CZ + DR + LIFT + 6]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-6, -6, X1 + 6, 2 * PR + 6, 6, 2);
  put(solid(g), prism(P, front, cr, ci, 0, CZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = PR + k * STEP, y = PR, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, y, PR), disc(x, y, PR - 3), CZ, CZ + 1.6));
    // the dish: a low mound on the plate
    const mound = [];
    for (const [r, z] of [[9, 0], [7.5, 2.5], [5, 4.5], [2, 5.5]]) mound.push(...ringAt(P, disc(x + 1, y, r, 20), CZ + 1.6 + z));
    mk("path", { d: poly(hull(mound)), class: "nf" }, grp);
    const dome = mk("path", { class: "sil" }, grp), rim = mk("path", { class: "nf lo" }, grp), knob = mk("path", { class: "nf" }, grp);
    items.push({ k, x, y, grp, dome, rim, knob, z: tween(k === FAV ? LIFT * 0.75 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const base = CZ + 1.8 + lift, pts = [];
    for (let i = 0; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); pts.push(...ringAt(P, disc(it.x, it.y, DR * Math.cos(t), 28), base + DR * 0.9 * Math.sin(t))); }
    it.dome.setAttribute("d", poly(hull(pts)));
    it.rim.setAttribute("d", poly(ringAt(P, disc(it.x, it.y, DR, 40), base + 1.2)));
    const top = base + DR * 0.9;
    it.knob.setAttribute("d", poly(hull(ringAt(P, disc(it.x, it.y, 2.2, 16), top).concat(ringAt(P, disc(it.x, it.y, 2.2, 16), top + 3)))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, CZ + DR / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.75 : 0) : dd === 0 ? LIFT : dd === 1 ? 5 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.dome.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "plate " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cloches",
  means: "Four domed covers on a counter: the dome under the pointer lifts to show the dish, and its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[122, 135], [226, 187], [278, 213], null],
  mount,
});

mailboxes.code:
/**
 * Mailboxes: four round-topped mailboxes on posts along a kerb, each with a
 * door on its street end and a flag on its side. The pointer picks a mailbox
 * by where it stands: its door drops open and its flag swings up, and the
 * flags beside it lift a little, staggered from it. At rest one flag is up,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 34, BW = 14, BL = 30, BH = 10, POST = 34, FAV = 2;
const X1 = (N - 1) * STEP + BW;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-8, -8, 0], [X1 + 8, BL + 22, 0], [X1 + 8, -8, 0], [-8, BL + 22, 0], [0, 0, POST + BH + BW / 2 + 16], [X1, 0, POST + BH + BW / 2 + 16]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [kr, ki] = rings(-8, -8, X1 + 8, BL + 6, 4, 1.4);
  put(solid(g), prism(P, front, kr, ki, 0, 3));

  const boxes = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * STEP, xc = x0 + BW / 2;
    const [pr, pi] = rings(xc - 2, BL / 2 - 2, xc + 2, BL / 2 + 2, 1, 0.4);
    put(solid(g), prism(P, front, pr, pi, 3, POST));
    // the box: a round-topped tube along y, as the hull of its two end profiles
    const prof = (y) => {
      const pts = [P(x0, y, POST), P(x0 + BW, y, POST)];
      for (let i = 0; i <= 10; i++) { const t = (Math.PI * i) / 10; pts.push(P(xc + (BW / 2) * Math.cos(t), y, POST + BH + (BW / 2) * Math.sin(t))); }
      return pts;
    };
    const body = mk("path", { d: poly(hull(prof(0).concat(prof(BL)))), class: "sil" }, g);
    const mouth = mk("path", { d: poly(prof(BL)), class: "nf lo" }, g);
    const door = mk("path", { class: "sil" }, g), flag = mk("path", { class: "sil" }, g), pin = mk("path", { class: "nf" }, g);
    boxes.push({ k, x0, xc, body, mouth, door, flag, pin, a: tween(k === FAV ? 1 : 0), last: NaN });
  }

  function draw(b, t) {
    if (t === b.last) return;
    b.last = t;
    // the door hinges at the bottom of the street end and drops toward the reader
    const da = rad(78 * t), ca = Math.cos(da), sa = Math.sin(da), y = BL;
    const dp = (x, h) => P(x, y + h * sa, POST + h * ca);
    const pts = [dp(b.x0, 0), dp(b.x0 + BW, 0)];
    for (let i = 0; i <= 10; i++) { const th = (Math.PI * i) / 10; const hz = BH + (BW / 2) * Math.sin(th); pts.push(P(b.xc + (BW / 2) * Math.cos(th), y + hz * sa, POST + hz * ca)); }
    b.door.setAttribute("d", poly(hull(pts)));
    // the flag on the +x side, pivoting near the back: down along the box at rest, up when raised
    const fa = rad(90 * t), px = b.x0 + BW + 0.6, py = 6, pz = POST + BH * 0.6;
    const fl = (u, v) => P(px, py + u * Math.cos(fa) - v * Math.sin(fa), pz + u * Math.sin(fa) + v * Math.cos(fa));
    b.flag.setAttribute("d", poly([fl(0, -1), fl(14, -1), fl(14, 4), fl(9, 4), fl(9, 1), fl(0, 1)]));
    b.pin.setAttribute("d", seg(P(px, py, pz), P(px + 1, py, pz)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of boxes) { draw(b, tval(b.a, now)); if (!tdone(b.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = boxes.map((b) => P(b.xc, BL / 2, POST * 0.7));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    boxes.forEach((b, k) => {
      const dd = Math.abs(k - a), t = a < 0 ? (k === FAV ? 1 : 0) : dd === 0 ? 1 : dd === 1 ? 0.3 : 0;
      tset(b.a, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      b.flag.classList.toggle("hi", on); b.body.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "mailbox " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "mailboxes",
  means: "Four mailboxes on posts: the one under the pointer drops its door and raises its flag, and the flags beside it lift.",
  rules: [1, 2, 5, 10],
  range: [0, 45, 90],
  tour: [[141, 139], [232, 185], [278, 208], null],
  mount,
});

filingcabinet.code:
/**
 * Filing cabinet: a steel cabinet of four drawers, each with a cup pull and
 * a label slot on its front and hanging files inside. The pointer's height
 * says which drawer: the drawer at that height slides open, the drawers near
 * it come ajar, the farther the less, each on its own spring, and the one
 * under it is bright. At rest one drawer stands half open on its files and
 * the one under it is ajar. The slider is the reach, in drawers.
 *
 * The pattern: a field along one axis (terrain). The height is read on the
 * cabinet's face plane, which never moves.
 */
const {
  Cam, clamp, facing, fit, poly, prism, proj, rings, rrect, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 50, D = 54, DH = 21, GAP = 2.2, Z0 = 5, OUT = 32, IN = 2.4;
const H = Z0 + N * (DH + GAP) + 4;
const REST = [5, 18, 0, 0], FAV = 1;
// 1 at the pointer, .31 at 42% of the reach, .09 beyond it
const fall = (u) => (u <= 0.42 ? 1 - (u / 0.42) * 0.69 : u <= 1 ? 0.31 - ((u - 0.42) / 0.58) * 0.22 : 0.09);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value, over = null;
  const C = Cam(45, 0.5, 1.86);
  fit(C, [[0, 0, 0], [W, D + OUT, 0], [W, 0, 0], [0, D + OUT, 0], [0, 0, H], [W, 0, H]], 200, 164);
  const P = proj(C), front = facing(C);
  const onFace = (y) => (q) => P(q.u, y, q.v);

  const g = mk("g", {}, svg);
  // the cabinet's body, its plinth, and the mouth of its open front, behind the drawers
  const [cr, ci] = rings(0, 0, W, D, 3, 1.4);
  put(solid(g), prism(P, front, cr, null, 0, H));
  mk("path", { d: seg(P(1.5, D, Z0 - 2), P(W - 1.5, D, Z0 - 2)), class: "nf lo" }, g);
  mk("path", { d: poly(rrect(1.4, Z0 - 0.6, W - 1.4, H - 2.4, 1.2, 2).map(onFace(D))), class: "nf lo" }, g);

  const drawers = [];
  for (let k = 0; k < N; k++) {
    const z0 = Z0 + k * (DH + GAP), el = solid(g);
    const files = mk("path", { class: "nf lo" }, el.g), pull = mk("path", { class: "nf" }, el.g), label = mk("path", { class: "nf lo" }, el.g);
    drawers.push({ k, z0, el, files, pull, label, sp: spring(REST[k], { eps: 0.05 }), drawn: NaN });
  }
  // the cabinet's side, top and lock, painted over the drawers' insides
  mk("path", { d: poly([P(W, 0, 0), P(W, D, 0), P(W, D, H), P(W, 0, H)]), class: "sil" }, g);
  const [tr, ti] = rings(-0.6, -0.6, W + 0.6, D + 0.6, 3.2, 1.6);
  put(solid(g), prism(P, front, tr, ti, H - 0.01, H + 1.4));
  mk("path", { d: poly(rrect(W / 2 - 1.6, H - 3.6, W / 2 + 1.6, H - 0.8, 1.4, 3).map(onFace(D))), class: "nf" }, g);

  function draw(b) {
    const s = Math.max(0, b.sp.x);
    if (s === b.drawn) return;
    b.drawn = s;
    const zt = b.z0 + DH, y = D + s, xm = W / 2;
    const [r, i] = rings(IN, s, W - IN, y, 1.6, 1);
    put(b.el, prism(P, front, r, i, b.z0, zt));
    // hanging files: the tops of the folders, where the drawer has left the cabinet
    let f = "";
    for (let fy = y - 5; fy > D + 1.5; fy -= 3.6) f += seg(P(IN + 4, fy, zt), P(W - IN - 4, fy, zt));
    b.files.setAttribute("d", f);
    b.pull.setAttribute("d", poly(rrect(xm - 9, zt - 11.5, xm + 9, zt - 8, 1.6, 3).map(onFace(y))));
    b.label.setAttribute("d", poly(rrect(xm - 7, zt - 6, xm + 7, zt - 2.6, 0.8, 2).map(onFace(y))));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const b of drawers) { if (stepS(b.sp, dt)) m = true; draw(b); }
    return m;
  });
  bag.add(B.unregister);

  /** The height on the cabinet's face (y = D) under the point; null off the face. */
  function height([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    return x < -OUT || x > W + 6 || z < 0 || z > H ? null : z;
  }

  function retarget() {
    let mark = FAV;
    if (over == null) drawers.forEach((b) => (b.sp.t = REST[b.k]));
    else {
      drawers.forEach((b) => (b.sp.t = clamp(OUT * fall(Math.abs(b.z0 + DH / 2 - over) / (reach * (DH + GAP))), 0, OUT)));
      mark = clamp(Math.floor((over - Z0) / (DH + GAP)), 0, N - 1);
    }
    drawers.forEach((b) => b.el.sil.classList.toggle("hi", b.k === mark));
    read.textContent = over == null ? "rest" : "drawer " + (N - mark);
    B.wake();
  }

  bag.add(pointer(stage, { move: (p) => { over = height(p); retarget(); }, leave: () => { over = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; if (over != null) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "filingcabinet",
  means: "A four-drawer filing cabinet: the drawer at the pointer's height slides open on its files, the ones near it come ajar.",
  rules: [1, 3, 5, 6],
  range: [1.2, 2, 3],
  tour: [[186, 108], [186, 189], [186, 237], null],
  mount,
});

containeryard.code:
/**
 * Container yard: twelve shipping containers in four stacks of three, ribbed
 * along their sides with a door split at the end, under a gantry crane whose
 * beam spans the yard on two portal frames. The pointer picks a stack: the
 * trolley runs over it and its top container lifts on the cables, and the
 * tops beside it lift a little, staggered from it. At rest the second stack's
 * top hangs part way up, bright. The slider is the lift.
 *
 * The pattern: one of many in a row (riffle); tweens per top, a tween for the
 * trolley; the hit is read on each stack's rest outline, which never moves.
 */
const {
  Cam, clamp, facing, fit, hull, lerp, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, CW = 12, GAP = 3, L = 38, H = 12, STACK = 3 * H, YM = L / 2, BZ = 54, FAV = 1, NEAR = 0.22;
const W = N * (CW + GAP) - GAP, PX = 13;
const cx = (i) => i * (CW + GAP) + CW / 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-PX - 2, 0, 0], [W + PX + 2, L, 0], [W + PX + 2, 0, 0], [-PX - 2, L, 0], [-PX - 4, YM, BZ + 11], [W + PX + 4, YM, BZ + 11]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  /** A container from z0, its ribs on the long side and its door split at the end, into solid el. */
  function box(el, x0, z0) {
    const x1 = x0 + CW, z1 = z0 + H;
    const [r, i] = rings(x0, 0, x1, L, 1.2, 0.7);
    put(el, prism(P, front, r, i, z0, z1));
    let d = "";
    for (let y = 3.5; y < L - 2; y += 3) d += seg(P(x1, y, z0 + 1.2), P(x1, y, z1 - 1.2));
    for (const x of [x0 + 2.8, x1 - 2.8]) d += seg(P(x, L, z0 + 1.2), P(x, L, z1 - 1.2));
    el.ribs.setAttribute("d", d);
    el.door.setAttribute("d", seg(P(x0 + CW / 2, L, z0 + 0.8), P(x0 + CW / 2, L, z1 - 0.8)));
  }
  const mkBox = () => { const el = solid(g); el.ribs = mk("path", { class: "nf lo" }, el.g); el.door = mk("path", { class: "nf" }, el.g); return el; };

  /** A portal frame at x: two legs and a sill along y under the beam. */
  function portal(x) {
    for (const y of [2, L - 5]) { const [r, i] = rings(x - 1.5, y, x + 1.5, y + 3, 1, 0.5); put(solid(g), prism(P, front, r, i, 0, BZ)); }
    const [r, i] = rings(x - 2, 0, x + 2, L, 1.2, 0.6);
    put(solid(g), prism(P, front, r, i, BZ, BZ + 4));
  }

  portal(-PX);
  const stacks = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * (CW + GAP);
    box(mkBox(), x0, 0); box(mkBox(), x0, H);
    const top = mkBox();
    stacks.push({ k, x0, top, z: tween(k === FAV ? 0.75 : 0), last: NaN });
  }
  const cables = mk("path", { class: "nf" }, g);
  portal(W + PX);
  const [br, bi] = rings(-PX - 3, YM - 2.5, W + PX + 3, YM + 2.5, 1.5, 0.7);
  put(solid(g), prism(P, front, br, bi, BZ + 4, BZ + 8));
  const trolley = solid(g);
  const tx = tween(cx(FAV));
  let lastT = NaN, cableAt = -1;

  /** The height of the stack tops under trolley position x, read between the two stacks it lies between. */
  function topAt(x, now) {
    const u = clamp((x - CW / 2) / (CW + GAP), 0, N - 1), a = Math.floor(u), b = Math.min(N - 1, a + 1);
    return STACK + lerp(tval(stacks[a].z, now), tval(stacks[b].z, now), u - a) * lift;
  }

  const B = register(stage, (_dt, now) => {
    let moving = !tdone(tx, now);
    for (const s of stacks) {
      const z = tval(s.z, now) * lift;
      if (z !== s.last) { box(s.top, s.x0, 2 * H + z); s.last = z; }
      if (!tdone(s.z, now)) moving = true;
    }
    const x = tval(tx, now), top = topAt(x, now), key = x + "," + top;
    if (key !== lastT) {
      lastT = key;
      const [r, i] = rings(x - 4, YM - 3, x + 4, YM + 3, 1.2, 0.6);
      put(trolley, prism(P, front, r, i, BZ + 8, BZ + 11));
      // the cables are painted just after the stack they hang over, so nearer stacks cover them
      const near = clamp(Math.round((x - CW / 2) / (CW + GAP)), 0, N - 1);
      if (near !== cableAt) { cableAt = near; stacks[near].top.g.after(cables); }
      cables.setAttribute("d", seg(P(x, YM - 2, BZ + 4), P(x, YM - 9, top)) + seg(P(x, YM + 2, BZ + 4), P(x, YM + 9, top)));
    }
    return moving;
  });
  bag.add(B.unregister);

  // each stack's outline at rest, a little over its top: static, and nothing draws it
  const outlines = stacks.map((s) => hull([0, STACK + 4].flatMap((z) => [[s.x0, 0], [s.x0 + CW, 0], [s.x0 + CW, L], [s.x0, L]].map(([x, y]) => P(x, y, z)))));
  const inside = (pt, poly) => {
    let c = false;
    for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
      const [xi, yi] = poly[i], [xj, yj] = poly[j];
      if (yi > pt[1] !== yj > pt[1] && pt[0] < ((xj - xi) * (pt[1] - yi)) / (yj - yi) + xi) c = !c;
    }
    return c;
  };
  /** The nearest stack whose rest outline holds the point; -1 outside them all. */
  const hit = (p) => { for (let k = N - 1; k >= 0; k--) if (inside(p, outlines[k])) return k; return -1; };

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    stacks.forEach((s, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? 0.75 : 0) : dd === 0 ? 1 : dd === 1 ? NEAR : 0;
      tset(s.z, z, now, from < 0 ? 0 : Math.abs(k - from) * 45);
      s.top.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    tset(tx, cx(a < 0 ? FAV : a), now, 0);
    read.textContent = a < 0 ? "rest" : "bay " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; for (const s of stacks) s.last = NaN; lastT = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "containeryard",
  means: "A container yard under a gantry: the top container of the stack under the pointer lifts on the cables.",
  rules: [1, 2, 5, 6],
  range: [6, 10, 14],
  tour: [[159, 132], [241, 172], [214, 158], null],
  mount,
});

windturbines.code:
/**
 * Wind turbines: five turbines along the ridge of a terraced hill, each a
 * tapering tower, a nacelle and three tapered blades on a hub. The rotors
 * always turn slowly while the figure is in view; the ones near the pointer
 * spin up, the nearest fastest, each on a spring on its speed, and the
 * nearest is bright. At rest the summit turbine is bright. The slider is the
 * reach.
 *
 * The pattern: a field (terrain) put on a rate (slow); the hit is read
 * against the hubs, which never move.
 */
const {
  Cam, facing, fillet, fit, hull, poly, prism, proj, rad, reducedMotion, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const T = [-84, -42, 0, 42, 84], S_OFF = [5, -4, 0, -4, 5], TIER = [8, 16, 24], TOWER = 46, R = 21, YAW = 32;
const W0 = 0.55, WMAX = 7.5, TERR = [[104, 36], [64, 24], [24, 14]];
const M = [Math.SQRT1_2, -Math.SQRT1_2], NV = [Math.SQRT1_2, Math.SQRT1_2];
const at = (t, s) => [t * M[0] + s * NV[0], t * M[1] + s * NV[1]];
const fall = (u) => (u <= 0.35 ? 1 : u <= 1 ? 1 - ((u - 0.35) / 0.65) * 0.9 : 0.1);
// one blade in its own plane: r along the blade, w across it, a wide root tapering to the tip
const BLADE = fillet([[2, -0.9], [6, -1.1], [R, -0.35], [R + 0.6, 0.1], [R - 1, 0.5], [6.5, 2.8], [2, 1.2]], [0.4, 0.8, 0.3, 0.3, 0.4, 1, 0.4], 3);

/** A ring of an ellipse laid along the hill's ridge, as the samples prism() takes. */
function ell(a, b, n = 48) {
  return Array.from({ length: n }, (_, i) => {
    const t = (i / n) * Math.PI * 2, c = Math.cos(t), s = Math.sin(t), nl = Math.hypot(c / a, s / b);
    const nu = c / a / nl, nv = s / b / nl;
    return { u: a * c * M[0] + b * s * NV[0], v: a * c * M[1] + b * s * NV[1], nu: nu * M[0] + nv * NV[0], nv: nu * M[1] + nv * NV[1] };
  });
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value, over = null;
  const C = Cam(45, 0.5, 1.48);
  const ext = [[...at(-106, 0), 0], [...at(106, 0), 0], [...at(0, 38), 0], [...at(0, -38), 0], [...at(0, 0), TIER[2] + TOWER + R + 3], [...at(-84, 5), TIER[0] + TOWER + R + 2]];
  fit(C, ext, 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  TERR.forEach(([a, b], k) => put(solid(g), prism(P, front, ell(a, b), ell(a - 1.6, b - 1.6), k * 8, k * 8 + 8)));

  const fa = rad(45 + YAW), F = [Math.cos(fa), Math.sin(fa)], U = [-F[1], F[0]];
  const ring = (c, r, z) => Array.from({ length: 24 }, (_, i) => { const t = (i / 24) * Math.PI * 2; return P(c[0] + r * Math.cos(t), c[1] + r * Math.sin(t), z); });
  /** A circle of radius r in the rotor's plane, centred d along the rotor's axis from point h. */
  const disc = (h, d, r) => Array.from({ length: 20 }, (_, i) => {
    const t = (i / 20) * Math.PI * 2, c = Math.cos(t) * r;
    return P(h[0] + F[0] * d + U[0] * c, h[1] + F[1] * d + U[1] * c, h[2] + Math.sin(t) * r);
  });

  const order = T.map((_, k) => k).sort((a, b) => S_OFF[a] - S_OFF[b]);
  const units = [];
  for (const k of order) {
    const b = at(T[k], S_OFF[k]), z0 = TIER[Math.min(2, 2 - Math.round(Math.abs(T[k]) / 42))], zt = z0 + TOWER;
    mk("path", { d: poly(hull(ring(b, 2.4, z0).concat(ring(b, 1.2, zt)))), class: "sil" }, g);
    const hub = [b[0] + F[0] * 2.5, b[1] + F[1] * 2.5, zt + 1.6];
    mk("path", { d: poly(hull(disc(hub, -9, 2.1).concat(disc(hub, -1, 2.4)))), class: "sil" }, g);
    const grp = mk("g", {}, g);
    const blades = [0, 1, 2].map(() => mk("path", { class: "sil" }, grp));
    const nose = mk("path", { class: "sil" }, grp);
    nose.setAttribute("d", poly(hull(disc(hub, 0, 2.2).concat(disc(hub, 2.6, 0.6)))));
    units.push({ k, hub, scr: P(...hub), blades, nose, th: rad(k * 41 + 10), w: spring(W0, { eps: 0.01 }), drawn: NaN });
  }
  units.sort((a, b) => a.k - b.k);

  function draw(u) {
    if (u.th === u.drawn) return;
    u.drawn = u.th;
    u.blades.forEach((el, i) => {
      const a = u.th + (i * Math.PI * 2) / 3, e = [Math.cos(a), Math.sin(a)], n = [-e[1], e[0]];
      el.setAttribute("d", poly(BLADE.map(([r, w]) => {
        const cu = r * e[0] + w * n[0], cz = r * e[1] + w * n[1];
        return P(u.hub[0] + F[0] * 1.2 + U[0] * cu, u.hub[1] + F[1] * 1.2 + U[1] * cu, u.hub[2] + cz);
      })));
    });
  }

  const still = reducedMotion();
  const B = register(stage, (dt) => {
    let m = false;
    for (const u of units) {
      if (stepS(u.w, dt)) m = true;
      if (!still) { u.th = (u.th + u.w.x * dt) % (Math.PI * 2); m = true; }
      draw(u);
    }
    return m;
  });
  bag.add(B.unregister);

  const dist = (u) => Math.hypot(u.scr[0] - over[0], (u.scr[1] - over[1]) * 0.6);
  function retarget() {
    let mark = units[2];
    for (const u of units) u.w.t = over ? W0 + (WMAX - W0) * fall(dist(u) / reach) : W0;
    if (over) { mark = units.reduce((a, b) => (dist(b) < dist(a) ? b : a)); read.textContent = "turbine " + (mark.k + 1); } else read.textContent = "rest";
    for (const u of units) { const on = u === mark; u.blades.forEach((el) => el.classList.toggle("hi", on)); u.nose.classList.toggle("hi", on); }
    B.wake();
  }

  bag.add(pointer(stage, { move: (p) => { over = p; retarget(); }, leave: () => { over = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "windturbines",
  means: "Five wind turbines on a hill: the rotors near the pointer spin up, the nearest fastest.",
  rules: [1, 3, 5, 8],
  range: [45, 75, 115],
  tour: [[80, 150], [262, 140], [200, 126], null],
  mount,
});

evchargers.code:
/**
 * EV chargers: four charging posts on a curb island at the head of four
 * parking bays, each post under a cap with a screen and a holster, its plug
 * seated in the holster on a cable that loops down from the post. The pointer
 * picks a post: its plug lifts out toward the reader on its cable and its
 * screen dot lights; the plugs beside it lift a little, staggered from it. At
 * rest the third post's plug is out, bright. The slider is how far it comes.
 *
 * The pattern: one of many in a single row (riffle); the hit is read against
 * the posts' rest centres, which never move.
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const N = 4, PITCH = 24, PW = 11, PD = 8, CURB = 3, PH = 38, FAV = 2, NEAR = 0.25;
const W = (N - 1) * PITCH + PW;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[-9, -6, -4], [W + 9, 34, -4], [W + 9, -6, -4], [-9, 34, -4], [-2, -2, PH + 2], [W + 2, -2, PH + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  { const [r, i] = rings(-9, -6, W + 9, 34, 4, 1.6); put(solid(g), prism(P, front, r, i, -4, 0)); }
  // the bays' lines, painted on the ground in front of the island
  let lines = "";
  for (let k = 0; k <= N; k++) { const x = k * PITCH - (PITCH - PW) / 2; lines += seg(P(x, 14, 0), P(x, 32, 0)); }
  mk("path", { d: lines, class: "nf lo" }, g);
  { const [r, i] = rings(-5, -3, W + 5, 12, 2.5, 1); put(solid(g), prism(P, front, r, i, 0, CURB)); }

  const posts = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * PITCH, x1 = x0 + PW;
    { const [r, i] = rings(x0, 0, x1, PD, 2.5, 1); put(solid(g), prism(P, front, r, i, CURB, PH - 2)); }
    { const [r, i] = rings(x0 - 1.2, -1.2, x1 + 1.2, PD + 1.2, 3, 1); put(solid(g), prism(P, front, r, i, PH - 2, PH)); }
    const onFace = (q) => P(x0 + q.u, PD, q.v);
    mk("path", { d: poly(rrect(2, 25, PW - 2, 32.5, 1.6, 4).map(onFace)), class: "nf" }, g);
    const dot = mk("circle", { r: 1.2, class: "dot off" }, g);
    place(dot, P(x0 + PW / 2, PD, 28.75));
    { const [r, i] = rings(x0 + 5, PD, x0 + 9.5, PD + 2.6, 1, 0.5); put(solid(g), prism(P, front, r, i, 14, 17.5)); }
    const cable = mk("path", { class: "nf" }, g), plug = solid(g);
    posts.push({ k, x0, dot, cable, plug, t: tween(k === FAV ? 0.75 : 0), last: NaN, mid: P(x0 + PW / 2, PD, 18) });
  }

  /** Post p with its plug a share t of the way out: the plug's block and the cable that loops down to it. */
  function draw(p, t) {
    const px = p.x0 + 7.25, py = PD + 2.4 + t * reach, pz = 17.5 + t * 8;
    const [r, i] = rings(px - 2, py - 1.6, px + 2, py + 1.6, 1.2, 0.6);
    put(p.plug, prism(P, front, r, i, pz, pz + 8));
    // a quadratic sag from the post's foot to the plug's tail, kept above the curb
    const a = [p.x0 + 2.5, PD, 9], b = [px, py, pz], c = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2 + 3, -4 + t * 6];
    const pts = [];
    for (let s = 0; s <= 16; s++) {
      const u = s / 16, q = (j) => (1 - u) ** 2 * a[j] + 2 * u * (1 - u) * c[j] + u * u * b[j];
      pts.push(P(q(0), q(1), Math.max(CURB + 0.8, q(2))));
    }
    p.cable.setAttribute("d", open(pts));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const p of posts) {
      const t = tval(p.t, now);
      if (t !== p.last) { draw(p, t); p.last = t; }
      if (!tdone(p.t, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    posts.forEach((p, k) => { const d = Math.abs(p.mid[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 22 && Math.abs(posts[best].mid[1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    posts.forEach((p, k) => {
      const dd = Math.abs(k - a), t = a < 0 ? (k === FAV ? 0.75 : 0) : dd === 0 ? 1 : dd === 1 ? NEAR : 0;
      tset(p.t, t, now, from < 0 ? 0 : Math.abs(k - from) * 45);
      const on = k === (a < 0 ? FAV : a);
      p.plug.sil.classList.toggle("hi", on);
      p.dot.setAttribute("class", on ? "dot" : "dot off");
    });
    read.textContent = a < 0 ? "rest" : "bay " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; for (const p of posts) p.last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "evchargers",
  means: "Four EV chargers at their bays: the one under the pointer lifts its plug out on the cable, and its screen lights.",
  rules: [1, 2, 4, 5],
  range: [12, 17, 22],
  tour: [[151, 120], [266, 176], [190, 138], null],
  mount,
});

pianokeys.code:
/**
 * Piano keys: two octaves of a keyboard in its case, fourteen white keys and
 * ten raised black ones between a back panel and two end cheeks. The pointer
 * plays: the keys near it press down, each on its own spring, the one under it
 * deepest and bright. At rest a chord is held, its middle key bright. The
 * slider is the reach, in key widths.
 *
 * The pattern: a continuous field (terrain) along one row; the hit is on the
 * plane of the keys' resting tops, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NW = 14, WW = 9, GAP = 0.8, L = 48, KH = 8, DW = 5.2, DB = 3.6;
const BLK = [0, 1, 3, 4, 5], BWD = 5, BL = 30, BH = 6;
const X1 = NW * WW, BACK = -20, PH = KH + 13;
const NOTE = ["C", "D", "E", "F", "G", "A", "B"], SHARP = ["C#", "D#", "", "F#", "G#", "A#"];
const CHORD = { w7: 0.75, w9: 1, w11: 0.75 }, FAV = "w9";
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * WW, over = null;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-6, BACK, -6], [X1 + 6, L + 3, -6], [X1 + 6, BACK, -6], [-6, L + 3, -6], [-6, BACK, PH], [X1 + 6, BACK, PH]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1, el = solid(g)) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(el, prism(P, front, o, i, z0, z1)); return el; };

  // the case: a base, the back panel with its knobs and a slot, and the far cheek
  block(-6, BACK, X1 + 6, L + 3, 3, 1.2, -6, 0);
  const panel = block(-6, BACK, X1 + 6, -1.5, 3, 1.4, 0, PH);
  mk("path", { class: "nf lo", d: seg(P(30, BACK + 9, PH), P(X1 - 30, BACK + 9, PH)) + seg(P(30, BACK + 12, PH), P(X1 - 30, BACK + 12, PH)) }, panel.g);
  for (const kx of [10, 19]) put(solid(g), prism(P, front, circ(2.8, 24).map((q) => ({ ...q, u: q.u + kx, v: q.v + BACK + 10 })), circ(1.8, 24).map((q) => ({ ...q, u: q.u + kx, v: q.v + BACK + 10 })), PH, PH + 2.4));
  block(-6, -1.5, -1, L + 3, 1.6, 0.6, 0, KH + 5);

  // white keys far to near, then the black keys over them
  const keys = [];
  for (let k = 0; k < NW; k++) {
    const x0 = k * WW + GAP / 2, x1 = (k + 1) * WW - GAP / 2;
    keys.push({ id: "w" + k, cx: (x0 + x1) / 2, y1: L, z0: 0, z1: KH, dmax: DW, x0, x1, b: 0.8, el: solid(g), name: NOTE[k % 7] + (3 + Math.floor(k / 7)) });
  }
  for (let k = 0; k < NW - 1; k++) {
    if (!BLK.includes(k % 7)) continue;
    const cx = (k + 1) * WW;
    keys.push({ id: "b" + k, cx, y1: BL, z0: KH - 0.5, z1: KH + BH, dmax: DB, x0: cx - BWD / 2, x1: cx + BWD / 2, b: 0.7, el: solid(g), name: SHARP[k % 7] + (3 + Math.floor(k / 7)) });
  }
  for (const key of keys) {
    [key.ring, key.inner] = rings(key.x0, 0, key.x1, key.y1, 1.2, key.b);
    key.rest = (CHORD[key.id] || 0) * key.dmax * 0.7;
    key.sp = spring(key.rest, { eps: 0.02 });
    key.drawn = NaN;
  }
  block(X1 + 1, -1.5, X1 + 6, L + 3, 1.6, 0.6, 0, KH + 5);

  function draw(key) {
    const d = clamp(key.sp.x, 0, key.dmax);
    if (d === key.drawn) return;
    key.drawn = d;
    put(key.el, prism(P, front, key.ring, key.inner, key.z0 - d, key.z1 - d));
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const key of keys) { if (stepS(key.sp, dt)) m = true; draw(key); }
    return m;
  });
  bag.add(B.unregister);

  /** The key under a point of the keys' resting top plane: a black key on its stretch, else the white key below it. */
  function under([x, y]) {
    if (y < BL + 1) { const b = keys.find((k) => k.id[0] === "b" && x >= k.x0 - 0.6 && x <= k.x1 + 0.6); if (b) return b; }
    return keys[clamp(Math.floor(x / WW), 0, NW - 1)];
  }

  function retarget() {
    const hit = over ? under(over) : null;
    for (const key of keys) {
      if (!over) key.sp.t = key.rest;
      else key.sp.t = key === hit ? key.dmax : key.dmax * 0.8 * falloff(Math.abs(key.cx - over[0]) / RAD);
      key.el.sil.classList.toggle("hi", over ? key === hit : key.id === FAV);
    }
    read.textContent = hit ? "key " + hit.name : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], KH);
      over = x > -3 && x < X1 + 3 && y > -6 && y < L + 14 ? [clamp(x, 0, X1 - 0.01), y] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v * WW; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "pianokeys",
  means: "Two octaves of piano keys in a case: the keys near the pointer press down, the one under it deepest.",
  rules: [1, 3, 5, 9],
  range: [1, 2, 3.5],
  tour: [[120, 152], [189, 168], [275, 200], null],
  mount,
});

spicerack.code:
/**
 * Spice rack: a two-shelf wall rack with a back board, two side boards and a
 * front rail on each shelf, holding eight round glass jars filled to their own
 * level under screw lids. The pointer picks a jar by where it stands: it lifts
 * above the rail and its lid pops up, and the jars beside it lift a little,
 * staggered from it. At rest one jar stands raised, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many on two rows (riffle); the pick reads rest centres.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 15, R = 5.6, JH = 16, LH = 4, D = 14, SH = 42, LIFT = 13, POP = 8, FAV = 5;
const LEVEL = [0.7, 0.45, 0.85, 0.55, 0.6, 0.8, 0.35, 0.65];
const X1 = N * STEP + 4;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.8);
  const top = SH + 3 + JH + LIFT + LH + POP + 2;
  fit(C, [[-3, -3, 0], [X1 + 3, D, 0], [X1 + 3, -3, 0], [-3, D, 0], [0, -3, top], [X1, D, top]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r = 1.2, b = 0.6, par = g) => { const [a, i] = rings(x0, y0, x1, y1, r, b); const s = solid(par); put(s, prism(P, front, a, i, z0, z1)); return s; };
  box(-3, -3, X1 + 3, 0, 0, SH + 30);
  box(-3, 0, 0, D, 0, SH + 22);

  const jars = [];
  for (let s = 0; s < 2; s++) {
    const zb = s * SH;
    box(0, 0, X1, D, zb, zb + 3, 1.5, 0.8);
    for (let c = 0; c < N; c++) {
      const k = s * N + c, x = 2 + STEP / 2 + c * STEP, grp = mk("g", {}, g);
      const body = mk("path", { class: "sil" }, grp), level = mk("path", { class: "nf lo" }, grp), mouth = mk("path", { class: "nf lo" }, grp);
      const lid = solid(grp);
      jars.push({ k, s, c, x, y: D / 2, zb: zb + 3, body, level, mouth, lid, z: tween(k === FAV ? LIFT * 0.8 : 0), p: tween(k === FAV ? POP * 0.7 : 0), last: "" });
    }
    box(0, D - 1.6, X1, D, zb + 8, zb + 10, 1, 0.4);
  }
  box(X1, 0, X1 + 3, D, 0, SH + 22);

  function draw(j, lift, pop) {
    const key = lift.toFixed(2) + "," + pop.toFixed(2);
    if (key === j.last) return;
    j.last = key;
    const z0 = j.zb + lift, z1 = z0 + JH, ring = disc(j.x, j.y, R);
    j.body.setAttribute("d", poly(hull(ringAt(P, ring, z0).concat(ringAt(P, ring, z1)))));
    j.level.setAttribute("d", open(ringAt(P, run(ring, front), z0 + 2 + (JH - 5) * LEVEL[j.k])));
    j.mouth.setAttribute("d", poly(ringAt(P, disc(j.x, j.y, R - 1.2), z1)));
    put(j.lid, prism(P, front, disc(j.x, j.y, R + 0.5), disc(j.x, j.y, R - 0.6), z1 + pop, z1 + pop + LH));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const j of jars) { draw(j, tval(j.z, now), tval(j.p, now)); if (!tdone(j.z, now) || !tdone(j.p, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = jars.map((j) => P(j.x, j.y, j.zb + JH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, (m[1] - sy) * 0.6); if (dd < bd) { bd = dd; best = k; } });
    return bd < 22 ? best : -1;
  }

  let act = -2;
  const dist = (a, b) => Math.abs(jars[a].c - jars[b].c) + Math.abs(jars[a].s - jars[b].s);
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    jars.forEach((j, k) => {
      const dd = a < 0 ? 9 : dist(a, k);
      const z = a < 0 ? (k === FAV ? LIFT * 0.8 : 0) : dd === 0 ? LIFT : dd === 1 ? 3.5 : 0;
      const p = a < 0 ? (k === FAV ? POP * 0.7 : 0) : dd === 0 ? POP : dd === 1 ? 1.5 : 0;
      const delay = from < 0 ? 0 : dist(from, k) * stag;
      tset(j.z, z, now, delay); tset(j.p, p, now, delay + (dd === 0 ? 120 : 0));
      j.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "jar " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "spicerack",
  means: "Eight spice jars on a two-shelf rack: the jar under the pointer lifts and pops its lid, and its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[213, 125], [142, 196], [255, 140], null],
  mount,
});

arcadebuttons.code:
/**
 * Arcade buttons: an arcade control panel, a slab with a joystick on its left
 * and a 3 × 4 grid of round buttons, each a cap sunk in its own bezel. The
 * pointer plays: the buttons near it press down, each on its own spring, the
 * one under it deepest and bright, and the stick leans toward the hand. At
 * rest a combo is held, its middle button bright. The slider is the reach, in
 * button spacings.
 *
 * The pattern: a continuous field (terrain) over a grid; the hit is on the
 * plane of the caps' resting tops, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, poly, prism, proj, rings, ringAt, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const COLS = 4, ROWS = 3, SX = 17, SY = 15, X0 = 42, Y0 = 9, R = 5, H = 7.5, DMAX = 5.6, TOP = 9;
const JX = 17, JY = 24, STICK = 16, BALL = 4.8, LEAN = 7, LEAN0 = [3.2, -2.4];
const PX1 = X0 + (COLS - 1) * SX + 11, PY1 = Y0 + (ROWS - 1) * SY + 11;
const COMBO = { "1·2": 0.5, "1·3": 0.85, "2·3": 0.3 }, FAV = "1·3";
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * SX, over = null;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-2, -4, 0], [PX1, PY1, 0], [PX1, -4, 0], [-2, PY1, 0], [JX - LEAN, JY - LEAN, TOP + STICK + 2 * BALL], [JX, JY, TOP + STICK + 2 * BALL]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the panel, then the joystick at its far-left end: a washer, a dust boot, the stick and its ball
  const [pr, pi] = rings(-2, -4, PX1, PY1, 4, 1.6);
  put(solid(g), prism(P, front, pr, pi, 0, TOP));
  put(solid(g), prism(P, front, disc(JX, JY, 7.5), disc(JX, JY, 6.3), TOP, TOP + 1));
  mk("path", { class: "sil", d: poly(hull(ringAt(P, disc(JX, JY, 3.6, 20), TOP + 1).concat(ringAt(P, disc(JX, JY, 1.9, 20), TOP + 4)))) }, g);
  const shaft = mk("path", { class: "sil" }, g), ball = mk("path", { class: "sil" }, g);
  const lx = spring(LEAN0[0]), ly = spring(LEAN0[1]);
  let leanDrawn = "";

  // the buttons, far to near: a bezel on the panel, then the cap that presses into it
  const btns = [];
  for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) btns.push({ r, c, id: r + 1 + "·" + (c + 1), x: X0 + c * SX, y: Y0 + r * SY });
  btns.sort((a, b) => a.x + a.y - (b.x + b.y));
  for (const b of btns) {
    put(solid(g), prism(P, front, disc(b.x, b.y, R + 1.7), disc(b.x, b.y, R + 1), TOP, TOP + 1));
    b.cap = solid(g);
    b.ring = disc(b.x, b.y, R);
    b.inner = disc(b.x, b.y, R - 0.9);
    b.rest = (COMBO[b.id] || 0) * DMAX;
    b.sp = spring(b.rest, { eps: 0.02 });
    b.drawn = NaN;
  }

  function drawStick() {
    const key = lx.x.toFixed(2) + "," + ly.x.toFixed(2);
    if (key === leanDrawn) return;
    leanDrawn = key;
    const tx = JX + lx.x, ty = JY + ly.x, tz = TOP + STICK;
    shaft.setAttribute("d", poly(hull(ringAt(P, disc(JX, JY, 1.2, 16), TOP + 3).concat(ringAt(P, disc(tx, ty, 1.2, 16), tz)))));
    const k = 1 + BALL / STICK, bx = JX + lx.x * k, by = JY + ly.x * k, pts = [];
    for (let i = -3; i <= 3; i++) { const a = (i / 3) * 1.45; pts.push(...ringAt(P, disc(bx, by, BALL * Math.cos(a), 24), tz + BALL + BALL * Math.sin(a))); }
    ball.setAttribute("d", poly(hull(pts)));
  }
  function draw(b) {
    const d = clamp(b.sp.x, 0, DMAX);
    if (d === b.drawn) return;
    b.drawn = d;
    put(b.cap, prism(P, front, b.ring, b.inner, TOP + 1, TOP + 1 + H - d));
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const b of btns) { if (stepS(b.sp, dt)) m = true; draw(b); }
    if (stepS(lx, dt)) m = true;
    if (stepS(ly, dt)) m = true;
    drawStick();
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    let hit = null, bd = Infinity;
    const dist = (b) => Math.hypot(b.x - over[0], b.y - over[1]);
    if (over) for (const b of btns) if (dist(b) < bd) { bd = dist(b); hit = b; }
    for (const b of btns) {
      b.sp.t = !over ? b.rest : b === hit ? DMAX : DMAX * 0.85 * falloff(dist(b) / RAD);
      b.cap.sil.classList.toggle("hi", over ? b === hit : b.id === FAV);
    }
    if (over) {
      const dx = over[0] - JX, dy = over[1] - JY, n = Math.hypot(dx, dy) || 1;
      lx.t = (dx / n) * LEAN; ly.t = (dy / n) * LEAN;
    } else { lx.t = LEAN0[0]; ly.t = LEAN0[1]; }
    read.textContent = hit ? "button " + hit.id : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], TOP + 1 + H);
      const XL = X0 + (COLS - 1) * SX, YL = Y0 + (ROWS - 1) * SY;
      over = x > X0 - 9 && x < XL + 10 && y > Y0 - 9 && y < YL + 9 ? [clamp(x, X0, XL), clamp(y, Y0, YL)] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v * SX; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "arcadebuttons",
  means: "An arcade control panel: the buttons near the pointer press down, the one under it deepest, and the stick leans toward it.",
  rules: [1, 3, 5, 9],
  range: [1, 2, 3],
  tour: [[182, 144], [242, 174], [299, 176], null],
  mount,
});

officechairs.code:
/**
 * Office chairs: five swivel chairs round a meeting table, each a five-legged
 * star base on casters, a gas column, a seat and a backrest on its spine. The
 * pointer is what the room turns to: every chair swivels on its own spring to
 * face it, and the chair nearest it is bright. At rest the chairs face the
 * table, each left a little askew, one bright. The slider is how quickly the
 * chairs follow (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (terrain's spring, on an angle per chair); the
 * hit is on the floor's plane, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const N = 5, RC = 46, RT = 23, TT = 27, SEAT = 17, LEG = 9;
const SKEW = [-16, 12, 0, -24, 18], FAV = 2;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const turn = (ring, a, cx, cy) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.25);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([(RC + 13) * Math.cos(a), (RC + 13) * Math.sin(a), 0], [(RC + 11) * Math.cos(a), (RC + 11) * Math.sin(a), SEAT + 24]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // local footprints, facing +x: the seat, the spine behind it, the backrest on the spine
  const SEATR = rings(-9, -9, 9, 9, 3.5, 1.2), SPINE = rings(-12, -1.6, -9, 1.6, 0.8, 0.4), BACKR = rings(-13.5, -9, -10.5, 9, 1.4, 0.6);

  const chairs = [];
  for (let k = 0; k < N; k++) {
    const a = (18 + k * 72) * (Math.PI / 180), cx = RC * Math.cos(a), cy = RC * Math.sin(a);
    const rest = a + Math.PI + SKEW[k] * (Math.PI / 180);
    chairs.push({ k, cx, cy, rest, sp: spring(rest, { k: 100 * value, c: 18 * Math.sqrt(value) }), drawn: NaN });
  }
  const table = { cx: 0, cy: 0 };
  const order = [...chairs, table].sort((p, q) => p.cx + p.cy - (q.cx + q.cy));

  for (const it of order) {
    if (it === table) {
      put(solid(g), prism(P, front, circ(10, 48), circ(8.8, 48), 0, 1.5));
      put(solid(g), prism(P, front, circ(2.6, 24), null, 1.5, TT));
      put(solid(g), prism(P, front, circ(RT, 72), circ(RT - 1.6, 72), TT, TT + 2));
      continue;
    }
    const ch = it, grp = mk("g", {}, g), legs = [];
    for (let i = 0; i < 5; i++) {
      const b = ch.k * 0.5 + (i / 5) * Math.PI * 2, tx = ch.cx + LEG * Math.cos(b), ty = ch.cy + LEG * Math.sin(b);
      legs.push(seg(P(ch.cx, ch.cy, 3), P(tx, ty, 1.6)));
      place(flatDot(grp, C, 1.1, "dot off"), P(tx, ty, 0));
    }
    mk("path", { class: "nf sil", d: legs.join("") }, grp);
    put(solid(grp), prism(P, front, disc(ch.cx, ch.cy, 1.5, 16), null, 2.4, SEAT));
    ch.seat = solid(grp);
    ch.back = mk("g", {}, grp);
    ch.spine = solid(ch.back);
    ch.plate = solid(ch.back);
    ch.backFirst = null;
  }

  function draw(ch) {
    const a = ch.sp.x;
    if (Math.abs(a - ch.drawn) < 1e-4) return;
    ch.drawn = a;
    const T = (r) => turn(r, a, ch.cx, ch.cy);
    put(ch.seat, prism(P, front, T(SEATR[0]), T(SEATR[1]), SEAT, SEAT + 3.2));
    put(ch.spine, prism(P, front, T(SPINE[0]), null, SEAT + 0.5, SEAT + 10));
    put(ch.plate, prism(P, front, T(BACKR[0]), T(BACKR[1]), SEAT + 9, SEAT + 24));
    // the backrest is painted before the seat when it stands on the far side
    const backFirst = Math.cos(a) + Math.sin(a) > 0;
    if (backFirst !== ch.backFirst) {
      ch.backFirst = backFirst;
      if (backFirst) ch.back.after(ch.seat.g); else ch.seat.g.after(ch.back);
    }
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const ch of chairs) { if (stepS(ch.sp, dt)) m = true; draw(ch); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    for (const ch of chairs) {
      if (over) {
        const d = Math.hypot(over[0] - ch.cx, over[1] - ch.cy);
        if (d < bd) { bd = d; near = ch; }
        const aim = d < 4 ? ch.sp.t : Math.atan2(over[1] - ch.cy, over[0] - ch.cx);
        ch.sp.t = ch.sp.t + wrap(aim - ch.sp.t);
      } else ch.sp.t = ch.sp.t + wrap(ch.rest - ch.sp.t);
    }
    for (const ch of chairs) {
      const on = over ? ch === near : ch.k === FAV;
      ch.plate.sil.classList.toggle("hi", on);
      ch.seat.sil.classList.toggle("hi", on);
    }
    read.textContent = near ? "chair " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y), k = Math.min(1, (RC + 14) / r);
      over = r > RC + 34 ? null : [x * k, y * k];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const ch of chairs) { ch.sp.k = 100 * v; ch.sp.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "officechairs",
  means: "Five office chairs round a table: every chair swivels to face the pointer, and the nearest one is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[108, 142], [127, 202], [248, 251], null],
  mount,
});

toaster.code:
/**
 * Toaster: a four-slot toaster, a rounded body with a slot per slice along
 * its top, a lever in its groove and a browning dial on the end, and a slice
 * of bread standing in each slot. The pointer picks a slot by where it is
 * along the toaster: that slice pops up high, the others pop a little,
 * staggered from it, and the lever rises with them. At rest the bread is
 * toasting low, one slice peeking out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the hit is on a fixed
 * plane through the slices' resting tops.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, open, poly, prism, proj, rings, ringAt, rrect, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 13, XS0 = 11, TOP = 32, Y0 = -4, Y1 = 38, SW = 3, VIS = 11, LIFT = 24, BUMP = 6;
const X1 = XS0 + (N - 1) * STEP + 11;
const REST = [2, 0, 7, 1], FAV = 2, LX = (X1 - 2) / 2, LZ = [9, 24];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[-2, Y0, 0], [X1, Y1 + 5, 0], [X1, Y0, 0], [-2, Y1 + 5, 0], [XS0, 4, TOP + VIS + LIFT], [XS0, 32, TOP + VIS + LIFT]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the body: one rounded solid, with the slot openings on its top
  const outer = rrect(-2, Y0, X1, Y1, 10, 12), inner = rrect(-0.8, Y0 + 1.2, X1 - 1.2, Y1 - 1.2, 8.8, 12);
  const body = solid(g);
  put(body, prism(P, front, outer, inner, 0, TOP));
  const slots = [];
  for (let k = 0; k < N; k++) slots.push(poly(ringAt(P, rrect(XS0 + k * STEP - 3, 4, XS0 + k * STEP + 3, 32, 2.5, 4), TOP)));
  mk("path", { class: "nf lo", d: slots.join("") }, body.g);
  // the end facing us: the lever's groove and the browning dial
  const dial = [];
  for (let i = 0; i < 24; i++) { const a = (i / 24) * Math.PI * 2; dial.push(P(X1 - 16 + 4 * Math.cos(a), Y1, 13 + 4 * Math.sin(a))); }
  mk("path", { class: "nf lo", d: seg(P(LX, Y1, LZ[0] - 2), P(LX, Y1, LZ[1] + 4)) + poly(dial) + seg(P(X1 - 16, Y1, 13), P(X1 - 16, Y1, 16)) }, body.g);

  // a slice: a bread profile in the y–z plane, rounded crown, given a thickness along x
  const slices = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    slices.push({ k, x: XS0 + k * STEP, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), z: tween(REST[k]), last: NaN });
  }
  const lever = solid(g), lz = tween(LZ[0]);
  let leverLast = NaN;

  function profile(x, h) {
    const zt = TOP + h, zs = Math.max(TOP + 3, zt - 8);
    const pts = [[6, TOP], [30, TOP], [30, zs - 2], [31.5, zs], [29, zt], [7, zt], [4.5, zs], [6, zs - 2]];
    return fillet(pts, [0, 0, 2, 3, 4.5, 4.5, 3, 2], 4).map(([y, z]) => [x, y, z]);
  }
  function draw(s, lift) {
    if (lift === s.last) return;
    s.last = lift;
    const h = VIS + lift, near = profile(s.x + SW / 2, h), far = profile(s.x - SW / 2, h);
    s.sil.setAttribute("d", poly(hull(near.concat(far).map((p) => P(...p)))));
    s.cr.setAttribute("d", open(near.filter((p) => p[2] > TOP + 0.5).map((p) => P(...p))));
  }
  function drawLever(z) {
    if (z === leverLast) return;
    leverLast = z;
    const [r, i] = rings(LX - 6, Y1, LX + 6, Y1 + 5, 1.6, 0.6);
    put(lever, prism(P, front, r, i, z, z + 2.6));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    slices.forEach((s) => { draw(s, tval(s.z, now)); if (!tdone(s.z, now)) moving = true; });
    drawLever(tval(lz, now));
    return moving || !tdone(lz, now);
  });
  bag.add(B.unregister);

  // the hit: the pointer on a fixed plane through the resting slices, nearest slot along x
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TOP + VIS * 0.6);
    if (x < -4 || x > X1 + 2 || y < Y0 - 4 || y > Y1 + 2) return -1;
    return clamp(Math.round((x - XS0) / STEP), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    slices.forEach((s, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : BUMP - Math.abs(k - a);
      tset(s.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    tset(lz, a < 0 ? LZ[0] : LZ[1], now, 0);
    read.textContent = a < 0 ? "rest" : "slot " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "toaster",
  means: "A four-slot toaster: the slice in the slot under the pointer pops up high, the others pop a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[164, 111], [192, 125], [247, 152], null],
  mount,
});

knifeblock.code:
/**
 * Knife block: a wooden block leaning back, six slots cut in its top and six
 * knives in them, each handle its own size, a ferrule at its foot. The
 * pointer picks a knife by where it stands: it slides up along the slot and
 * shows its blade, and the knives beside it rise a little, staggered from it.
 * Sizes fall from the chef's knife at the back to the paring
 * knife in front. At rest the bread knife stands half drawn, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the knife
 * whose resting handle is nearest the pointer's x on screen.
 */
const {
  Cam, facing, fit, hull, open, poly, proj, rings, ringAt, run, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

// handle thickness (x), grip height (y), handle length, blade length, blade width
const TW = [5.6, 5, 4.4, 4.2, 3.6, 3.4], HD = [9, 8, 6.6, 7, 5.6, 5.2], HL_ = [21, 19, 17, 16, 13, 12];
const BL = [34, 31, 28, 24, 18, 16], BW = [10, 7, 4.6, 6, 4, 3.6];
const L = 54, D = 26, H = 32, T = 0.26, FAV = 1, RISE = 24;
const XS = TW.map((_, k) => 7 + k * 8), YA = TW.map((_, k) => (k % 2 ? 14.5 : 12));
const shY = (ring, dy) => ring.map((q) => ({ ...q, v: q.v + dy }));
/** Keeps the part of a polygon of [z, dy] points at or above zc. */
function clipZ(pts, zc) {
  const o = [];
  pts.forEach((a, i) => {
    const b = pts[(i + 1) % pts.length], ia = a[0] >= zc, ib = b[0] >= zc;
    if (ia) o.push(a);
    if (ia !== ib) { const t = (zc - a[0]) / (b[0] - a[0]); o.push([zc, a[1] + t * (b[1] - a[1])]); }
  });
  return o;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.85);
  const zTop = H + RISE + 21;
  fit(C, [[0, 0, 0], [L, D, 0], [L, 0, 0], [0, D, 0], [0, -T * zTop + 4, zTop], [L, -T * zTop + 4, zTop], [0, -T * H, H]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const axisY = (k, z) => YA[k] - T * z;

  // the block: an oblique solid, its top shifted back along the lean
  {
    const [foot] = rings(0, 0, L, D, 4, 1.6), [top, inner] = rings(0, -T * H, L, D - T * H, 4, 1.6);
    put(solid(g), { sil: poly(hull(ringAt(P, foot, 0).concat(ringAt(P, top, H)))), crease: open(ringAt(P, run(inner, front), H)) });
    let slots = "";
    XS.forEach((x, k) => { const y = axisY(k, H); slots += poly(ringAt(P, rings(x - 0.8, y - BW[k] * 0.35 - 0.6, x + 0.8, y + BW[k] * 0.65 + 0.6, 0.8, 0.3)[0], H)); });
    mk("path", { class: "nf lo", d: slots }, g);
  }

  const knives = XS.map((x, k) => {
    const grp = mk("g", {}, g), blade = mk("path", { class: "sil" }, grp), handle = solid(grp), fer = mk("path", { class: "nf lo" }, grp);
    const max = Math.min(RISE, BL[k] - 5);
    return { k, x, grp, blade, handle, fer, max, z: tween(k === FAV ? max * 0.45 : 0), last: "" };
  });

  function draw(n, lift) {
    const key = lift.toFixed(2);
    if (key === n.last) return;
    n.last = key;
    const k = n.k, x = n.x, zb = H + lift, z1 = zb + HL_[k], bw = BW[k], s = -bw * 0.35, e = s + bw, tip = zb - BL[k];
    const pts = clipZ([[zb, s], [tip + BL[k] * 0.1, s], [tip, s + bw * 0.12], [tip + BL[k] * 0.32, s + bw * 0.78], [tip + BL[k] * 0.7, e], [zb, e]], H + 0.2);
    n.blade.setAttribute("d", pts.length > 2 ? poly(pts.map(([z, dy]) => P(x, axisY(k, z) + dy, z))) : "");
    const [hr, hi] = rings(x - TW[k] / 2, -HD[k] / 2, x + TW[k] / 2, HD[k] / 2, 3, 0.7);
    const a = ringAt(P, shY(hr, axisY(k, zb)), zb), b = ringAt(P, shY(hr, axisY(k, z1)), z1);
    put(n.handle, { sil: poly(hull(a.concat(b))), crease: open(ringAt(P, run(shY(hi, axisY(k, z1)), front), z1)) });
    const zf = zb + 3, xf = x + TW[k] / 2;
    n.fer.setAttribute("d", seg(P(xf, axisY(k, zf) - HD[k] / 2 + 0.8, zf), P(xf, axisY(k, zf) + HD[k] / 2 - 0.8, zf)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const n of knives) { draw(n, tval(n.z, now)); if (!tdone(n.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  /** The knife whose resting handle is nearest the pointer's x on screen; -1 off the block. */
  const mids = knives.map((n) => { const z = H + HL_[n.k] / 2; return P(n.x, axisY(n.k, z), z); });
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 11 && Math.abs(mids[best][1] - sy) < 55 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    knives.forEach((n, k) => {
      const d = Math.abs(k - a);
      const z = a < 0 ? (k === FAV ? n.max * 0.45 : 0) : d === 0 ? n.max : d === 1 ? 4 : d === 2 ? 1.5 : 0;
      tset(n.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      n.handle.sil.classList.toggle("hi", on); n.blade.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "knife " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "knifeblock",
  means: "Six knives in a leaning block: the one under the pointer slides up out of its slot and shows its blade, and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[172, 150], [226, 175], [200, 162], null],
  mount,
});

beehive.code:
/**
 * Beehive: two wooden hive boxes stacked on a stand with a landing board, the
 * lid off and eight frames hanging in the top box, their top bars on the rim.
 * The pointer picks a frame by where it hangs: it lifts up out of the box,
 * showing its comb, and the frames beside it rise a little, staggered from
 * it. At rest one frame stands half drawn, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 8, STEP = 7.5, W = N * STEP + 4, D = 46, BH = 26, Z0 = 12, RIM = Z0 + 2 * BH;
const BAR = 2.4, HF = 22, LIFT = 30, FAV = 4;
const TOP = RIM + BAR + LIFT + 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[-3, -3, 0], [W + 3, D + 10, 0], [W + 3, -3, 0], [-3, D + 10, 0], [0, 0, TOP], [W, 0, TOP], [0, D, TOP], [W, D, TOP]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1) => { const s = solid(g); const [o, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, o, i, z0, z1)); return s; };

  // the stand: four legs, then the bottom board running out to a landing board
  for (const [x, y] of [[-1, -1], [W - 5, -1], [-1, D + 3], [W - 5, D + 3]]) block(x, y, x + 6, y + 6, 1.2, 0.8, 0, 7.5);
  block(-3, -3, W + 3, D + 10, 2.5, 1.4, 7.5, Z0);
  // two boxes: the top one's crease is its open rim
  const handle = (box, z) => {
    const m = mk("path", { class: "nf lo" }, box.g), fx = (y, zz) => P(W, y, zz), fy = (x, zz) => P(x, D, zz);
    return (d) => m.setAttribute("d", d +
      poly([fx(D / 2 - 7, z - 1.4), fx(D / 2 + 7, z - 1.4), fx(D / 2 + 7, z + 1.4), fx(D / 2 - 7, z + 1.4)]) +
      poly([fy(W / 2 - 8, z - 1.4), fy(W / 2 + 8, z - 1.4), fy(W / 2 + 8, z + 1.4), fy(W / 2 - 8, z + 1.4)]));
  };
  const b1 = block(0, 0, W, D, 2.2, 1.4, Z0, Z0 + BH);
  // the entrance: a slot at the foot of the lower box, over the landing board
  handle(b1, Z0 + BH * 0.62)(poly([P(12, D, Z0 + 0.6), P(W - 12, D, Z0 + 0.6), P(W - 12, D, Z0 + 3), P(12, D, Z0 + 3)]));
  const b2 = block(0, 0, W, D, 2.2, 1.4, Z0 + BH, RIM);
  handle(b2, Z0 + BH * 1.62)("");

  const [barR, barI] = rings(-1.5, 0.8, 1.5, D - 0.8, 0.8, 0.5);
  const [bodR, bodI] = rings(-1, 3, 1, D - 3, 0.5, 0.3);
  const shift = (ring, x) => ring.map((q) => ({ ...q, u: q.u + x }));
  const frames = [];
  for (let k = 0; k < N; k++) {
    const x = 2 + STEP / 2 + k * STEP, grp = mk("g", {}, g);
    const body = solid(grp), comb = mk("path", { class: "nf lo" }, grp), bar = solid(grp);
    frames.push({ k, x, body, comb, bar, z: tween(k === FAV ? LIFT * 0.6 : 0), last: NaN,
      rings: [shift(barR, x), shift(barI, x), shift(bodR, x), shift(bodI, x)] });
  }

  /** A frame lifted L: only what stands above the rim is drawn; the box hides the rest. */
  function draw(f, L) {
    if (L === f.last) return;
    f.last = L;
    const zt = RIM + BAR + L, zbar = zt - BAR, zb = zbar - HF, [br, bi, dr, di] = f.rings;
    put(f.bar, prism(P, front, br, bi, Math.max(zbar, RIM), zt));
    if (zbar > RIM + 0.3) put(f.body, prism(P, front, dr, di, Math.max(zb, RIM), zbar));
    else put(f.body, { sil: "", crease: "" });
    // the comb: an inset panel on the frame's face, open at the rim while the box still hides its foot
    const lo = Math.max(zb + 2.5, RIM + 0.4), hi = zbar - 2, fx = f.x + 1;
    if (hi - lo < 1) { f.comb.setAttribute("d", ""); return; }
    const a = P(fx, 6, lo), b = P(fx, 6, hi), c = P(fx, D - 6, hi), d = P(fx, D - 6, lo);
    let s = open([a, b, c, d]) + (lo > RIM + 0.4 ? seg(d, a) : "");
    for (const t of [0.35, 0.65]) { const zz = lo + (hi - lo) * t; if (zz > lo + 1) s += seg(P(fx, 6, zz), P(fx, D - 6, zz)); }
    f.comb.setAttribute("d", s);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const f of frames) { draw(f, tval(f.z, now)); if (!tdone(f.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // the hit test reads each frame's resting top bar, which never moves
  const mids = frames.map((f) => P(f.x, D / 2, RIM));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 9 && sy > mids[best][1] - 110 && sy < mids[best][1] + 40 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    frames.forEach((f, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.6 : 0) : dd === 0 ? LIFT : dd === 1 ? 8 : dd === 2 ? 3 : 0;
      tset(f.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      f.bar.sil.classList.toggle("hi", on); f.body.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "frame " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "beehive",
  means: "A beehive with its lid off: the frame under the pointer lifts out of the box, and the frames beside it rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[176, 116], [235, 146], [200, 128], null],
  mount,
});

abacus.code:
/**
 * Abacus: a wooden frame on two feet with six rods across it, eight beads on
 * each rod. At rest every rod holds a number, its beads split between the two
 * ends. The pointer picks a rod by height and draws the beads toward its x,
 * each bead on its own spring: the rod under it gathers fully, the rods beside
 * it follow less. The slider is the reach, in rods.
 *
 * The pattern: a continuous field (terrain), on a single row of rods.
 */
const {
  Cam, clamp, fit, facing, hull, open, poly, prism, proj, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NR = 6, NB = 8, L = 112, ZR0 = 17, SP = 15, H = ZR0 + (NR - 1) * SP + 14, R = 4.7, BL = 6.6, BW = 7, FAV = 3;
const RIGHT = [2, 5, 1, 6, 3, 4]; // beads pushed right on each rod, bottom up: the number at rest
const falloff = (u) => (u <= 0 ? 1 : u <= 0.42 ? 1 - (u / 0.42) * 0.62 : u <= 1 ? 0.38 - ((u - 0.42) / 0.58) * 0.26 : 0.12);
const restX = (r, i) => (i < NB - RIGHT[r] ? 1 + BW / 2 + i * BW : L - 1 - BW / 2 - (NB - 1 - i) * BW);
const PROFILE = [[-0.5, 0.5], [-0.36, 0.86], [0, 1], [0.36, 0.86], [0.5, 0.5]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value, over = null;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-7, -15, 0], [L + 7, 15, 0], [L + 7, -15, 0], [-7, 15, 0], [-7, -6, H], [L + 7, 6, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const o = P(0, 0, 0), ex = P(1, 0, 0), ez = P(0, 0, 1);
  const ax = [ex[0] - o[0], ex[1] - o[1]], az = [ez[0] - o[0], ez[1] - o[1]], det = ax[0] * az[1] - az[0] * ax[1];
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1) => { const s = solid(g); const [a, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, a, i, z0, z1)); return s; };

  // the far foot and post, the bottom rail; the rods and beads; then the top rail and the near post and foot
  block(-8, -15, 1, 15, 3, 1.4, 0, 4);
  block(-7, -6, 0, 6, 1.6, 1, 4, H);
  block(0, -5, L, 5, 1.4, 1, 4, 10);
  // a bead is round in y and z, swollen in the middle: its outline, relative to its centre, is the hull of five rings
  const ringYZ = (x, r, z) => Array.from({ length: 20 }, (_, n) => { const a = (n / 20) * Math.PI * 2; return [x, r * Math.cos(a), z + r * Math.sin(a)]; });
  const rods = [];
  for (let r = 0; r < NR; r++) {
    const z = ZR0 + r * SP, rg = mk("g", {}, g), rod = mk("path", { class: "sil" }, rg);
    rod.setAttribute("d", poly(hull(ringYZ(0, 1.1, z).concat(ringYZ(L, 1.1, z)).map((p) => P(...p)))));
    const c0 = P(0, 0, z);
    const shape = hull(PROFILE.flatMap(([u, k]) => ringYZ(u * BL, k * R, z).map((p) => P(...p)))).map((q) => [q[0] - c0[0], q[1] - c0[1]]);
    const belt = ringYZ(0, R, z).filter((p) => 0.61 * p[1] + 0.5 * (p[2] - z) > 0.4).map((p) => { const q = P(...p); return [q[0] - c0[0], q[1] - c0[1]]; });
    belt.sort((p, q) => p[1] - q[1]);
    const beads = [];
    for (let i = 0; i < NB; i++) {
      const el = mk("g", {}, rg), sil = mk("path", { class: "sil" }, el), cr = mk("path", { class: "nf lo" }, el);
      beads.push({ i, sil, cr, rest: restX(r, i), sp: spring(restX(r, i), { eps: 0.02 }), drawn: NaN });
    }
    rods.push({ r, z, c0, rod, shape, belt, beads });
  }
  block(0, -6, L, 6, 1.4, 1, H - 6, H);
  block(L, -6, L + 7, 6, 1.6, 1, 4, H);
  block(L - 1, -15, L + 8, 15, 3, 1.4, 0, 4);

  function draw(rd, b) {
    const x = b.sp.x;
    if (x === b.drawn) return;
    b.drawn = x;
    const dx = rd.c0[0] + ax[0] * x, dy = rd.c0[1] + ax[1] * x, at = (q) => [q[0] + dx, q[1] + dy];
    b.sil.setAttribute("d", poly(rd.shape.map(at)));
    b.cr.setAttribute("d", open(rd.belt.map(at)));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const rd of rods) for (const b of rd.beads) { if (stepS(b.sp, dt)) m = true; draw(rd, b); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    const lit = over ? over[1] : FAV;
    for (const rd of rods) {
      const w = over ? falloff(Math.abs(rd.r - over[1]) / reach) : 0;
      const c = clamp((over ? over[0] : 0) - ((NB - 1) / 2) * BW, 1 + BW / 2, L - 1 - BW / 2 - (NB - 1) * BW);
      for (const b of rd.beads) b.sp.t = b.rest + (c + b.i * BW - b.rest) * w;
      const on = rd.r === lit;
      rd.rod.classList.toggle("hi", on);
      for (const b of rd.beads) b.sil.classList.toggle("hi", on);
    }
    read.textContent = over ? "rod " + (NR - over[1]) : "rest";
    B.wake();
  }

  // the hit test: the pointer on the frame's own plane, which never moves; the rod is the nearest by height
  function hit([sx, sy]) {
    const u = sx - o[0], v = sy - o[1], x = (u * az[1] - az[0] * v) / det, z = (ax[0] * v - u * ax[1]) / det;
    const r = Math.round((z - ZR0) / SP);
    if (x < -4 || x > L + 4 || r < 0 || r >= NR || Math.abs(z - ZR0 - r * SP) > SP / 2) return null;
    return [clamp(x, 0, L), r];
  }
  const same = (a, b) => (a === b) || (a && b && a[0] === b[0] && a[1] === b[1]);
  bag.add(pointer(stage, {
    move: (p) => { const h = hit(p); if (!same(h, over)) { over = h; retarget(); } },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();

  return { set: (v) => { reach = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "abacus",
  means: "An abacus of six rods: the beads slide along their rods toward the pointer, the rod under it most.",
  rules: [1, 3, 5, 8],
  range: [1.5, 3, 6],
  tour: [[164, 180], [247, 146], [206, 176], null],
  mount,
});

gradcaps.code:
/**
 * Graduation caps: five mortarboards resting on a row of pegs along a stand,
 * each a round skull under a square board, a tassel hanging from one corner.
 * The pointer picks a cap by where it rests: it tosses up and tilts, and the
 * caps beside it hop a little and lean away, staggered from it. At rest one
 * cap is caught mid-toss, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fillet, fit, facing, hull, open, poly, prism, proj, rings, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, GAP = 34, X1 = (N - 1) * GAP, PEG = 30, HB = 12, SK = 8, LIFT = 34, TILT = 22, FAV = 1;
const YAW = [6, -10, 14, -4, 10];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.8);
  const TOPZ = PEG + LIFT + 14;
  fit(C, [[-14, -12, 0], [X1 + 14, 12, 0], [X1 + 14, -12, 0], [-14, 12, 0], [-14, -14, TOPZ], [X1 + 14, 14, TOPZ], [X1 + 14, -14, TOPZ], [-14, 14, TOPZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-14, -12, X1 + 14, 12, 6, 1.6);
  put(solid(g), prism(P, front, sr, si, 0, 5));
  for (let k = 0; k < N; k++) { const [r, i] = rings(k * GAP - 2.2, -2.2, k * GAP + 2.2, 2.2, 2.2, 0.8); put(solid(g), prism(P, front, r, i, 5, PEG)); }

  const caps = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g), skull = mk("path", { class: "sil" }, grp), board = mk("path", { class: "sil" }, grp);
    const top = mk("path", { class: "nf lo" }, grp), cord = mk("path", { class: "nf" }, grp), tassel = mk("path", { class: "sil" }, grp);
    const rest = k === FAV ? 0.45 : 0;
    caps.push({ k, x: k * GAP, grp, skull, board, top, cord, tassel, lift: tween(rest), tilt: tween(rest), last: "" });
  }

  /** A cap's local point: yawed about its own axis, rolled about the view's depth axis, lifted onto its peg. */
  function xf(c, lift, roll) {
    const yw = rad(YAW[c.k]), ro = rad(roll), cy = Math.cos(yw), sy = Math.sin(yw), cr = Math.cos(ro), sr2 = Math.sin(ro);
    const n = [Math.SQRT1_2, Math.SQRT1_2, 0];
    return (u, v, w) => {
      const p = [u * cy - v * sy, u * sy + v * cy, w];
      const d = n[0] * p[0] + n[1] * p[1], cx = [n[1] * p[2], -n[0] * p[2], n[0] * p[1] - n[1] * p[0]];
      const q = p.map((pi, i) => pi * cr + cx[i] * sr2 + n[i] * d * (1 - cr));
      return P(c.x + q[0], q[1], PEG + 1 + lift + q[2]);
    };
  }
  const circle = (r, n = 20) => Array.from({ length: n }, (_, i) => [r * Math.cos((i / n) * Math.PI * 2), r * Math.sin((i / n) * Math.PI * 2)]);
  const square = (h) => fillet([[h, h], [-h, h], [-h, -h], [h, -h]], [1.6, 1.6, 1.6, 1.6]);
  const o0 = P(0, 0, 0), o1 = P(0, 0, 1), UZ = o0[1] - o1[1], UX = (P(1, -1, 0)[0] - o0[0]) / Math.SQRT2;

  function draw(c, lift, roll) {
    const key = lift.toFixed(3) + roll.toFixed(3);
    if (key === c.last) return;
    c.last = key;
    const T = xf(c, lift, roll);
    c.skull.setAttribute("d", poly(hull(circle(SK).flatMap(([u, v]) => [T(u, v, -7), T(u * 1.05, v * 1.05, 0)]))));
    const sq = square(HB);
    c.board.setAttribute("d", poly(hull(sq.flatMap(([u, v]) => [T(u, v, 0), T(u, v, 1.6)]))));
    c.top.setAttribute("d", poly(sq.map(([u, v]) => T(u * 0.92, v * 0.92, 1.6))));
    // the tassel: a cord from the button to the near corner, then hanging straight down
    const corner = T(HB - 1, HB - 1, 1.6), hang = (dz) => [corner[0], corner[1] + dz * UZ];
    c.cord.setAttribute("d", open([T(0, 0, 1.8), T(HB * 0.5, HB * 0.5, 1.8), corner, hang(6)]));
    const tz = [6, 13], tw = [0.9, 2];
    c.tassel.setAttribute("d", poly(hull([[-tw[0], tz[0]], [tw[0], tz[0]], [tw[1], tz[1]], [-tw[1], tz[1]]].map(([dx, dz]) => [corner[0] + dx * UX, corner[1] + dz * UZ]))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of caps) { draw(c, tval(c.lift, now) * LIFT, tval(c.tilt, now) * TILT); if (!tdone(c.lift, now) || !tdone(c.tilt, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = caps.map((c) => P(c.x, 0, PEG));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 20 && sy > mids[best][1] - 90 && sy < mids[best][1] + 30 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    caps.forEach((c, k) => {
      const dd = Math.abs(k - a), up = a < 0 ? (k === FAV ? 0.45 : 0) : dd === 0 ? 1 : dd === 1 ? 0.25 : 0;
      const lean = a < 0 ? (k === FAV ? 0.45 : 0) : dd === 0 ? 1 : dd === 1 ? 0.3 * Math.sign(k - a) : 0;
      const delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(c.lift, up, now, delay); tset(c.tilt, lean, now, delay);
      const on = k === (a < 0 ? FAV : a);
      c.board.classList.toggle("hi", on); c.skull.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "cap " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "gradcaps",
  means: "Five graduation caps on pegs: the cap under the pointer tosses up and tilts, and the caps beside it hop a little.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[135, 146], [244, 200], [200, 178], null],
  mount,
});

deskcalendar.code:
/**
 * Desk calendar: an A-frame stand with eight month pages hung from a row of
 * wire rings along its ridge, each page with a month grid and an index tab
 * stepped along its foot, so every page shows one tab. The pointer picks a
 * page by where it falls along the stack: that page flips up over the rings
 * and stands, the pages in front of it flip on over to the back, the one
 * nearest still in the air, and the pages behind it lift off the stand a
 * little, staggered from it. At rest the front page is lifted, about to be
 * turned, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), hinged. Tweens on each
 * page's angle; the pick is read on the plane of the resting stack, which
 * never moves.
 */
const {
  Cam, clamp, fillet, fit, hull, poly, proj, rad, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, register,
} = HL;

const N = 8, PW = 88, PL = 40, TH = 5, TW = 9, STEP = 10.5, TK = 0.9, PX0 = 4, SW = PW + 8;
const ZR = 46, B = 20, ZH = ZR + 1.2, UPA = 165, FAV = 0;
const stackA = (i) => 24.8 + (N - 1 - i) * 0.7, backA = (i) => 335.4 - i * 0.6;
const restA = (i) => (i === FAV ? 40 : stackA(i));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  const L = PL + TH;
  fit(C, [[0, -B, 0], [SW, B, 0], [SW, -B, 0], [0, B, 0], [PX0, 0, ZH + L], [PX0 + PW, 0, ZH + L], [PX0, -L, ZH], [PX0 + PW, L * 0.8, ZH]], 200, 172);
  const P = proj(C);
  const g = mk("g", {}, svg);

  // the stand: a tent of two slopes meeting at the ridge, its silhouette and the bevel of its near end
  const tent = fillet([[-B, 0], [B, 0], [1.6, ZR], [-1.6, ZR]], [2, 2, 1.5, 1.5]);
  const bevel = fillet([[-B + 3.4, 1.4], [B - 3.4, 1.4], [0.9, ZR - 2.6], [-0.9, ZR - 2.6]], [1.4, 1.4, 1, 1]);
  const stand = mk("g", {}, g);
  mk("path", { d: poly(hull(tent.map(([y, z]) => P(0, y, z)).concat(tent.map(([y, z]) => P(SW, y, z))))), class: "sil" }, stand);
  mk("path", { d: poly(bevel.map(([y, z]) => P(SW, y, z))), class: "nf lo" }, stand);
  mk("path", { d: seg(P(1.5, B - 0.6, 1.4), P(SW - 1.5, B - 0.6, 1.4)), class: "nf lo" }, stand);

  const pages = [];
  for (let i = 0; i < N; i++) {
    const t = 3 + i * STEP;
    const shape = fillet(
      [[0, 1.5], [PW, 1.5], [PW, PL], [t + TW, PL], [t + TW, L], [t, L], [t, PL], [0, PL]],
      [1, 1, 2, 1.2, 1.6, 1.6, 1.2, 2],
    );
    const grp = mk("g", {}, g);
    const under = mk("path", { class: "lo" }, grp), over = mk("path", { class: "sil" }, grp);
    const head = mk("path", { class: "nf" }, grp), grid = mk("path", { class: "nf lo" }, grp);
    pages.push({ i, t, shape, grp, under, over, head, grid, a: tween(restA(i)), last: NaN });
  }
  // the wire rings over the ridge, through every page's holes
  const wire = mk("path", { class: "nf" }, g);
  let w = "";
  for (let k = 0; k < 9; k++) {
    const x = PX0 + 6 + k * ((PW - 12) / 8), pts = [];
    for (let s = 0; s < 14; s++) { const q = (s / 14) * Math.PI * 2; pts.push(P(x, 2.4 * Math.cos(q), ZH + 0.4 + 2.4 * Math.sin(q))); }
    w += poly(pts);
  }
  wire.setAttribute("d", w);

  function draw(p, a) {
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    const at = (u, v, o) => P(PX0 + u, v * s - o * c, ZH - v * c - o * s);
    const faces = c + 0.816 * s > 0; // the printed side turned toward the viewer
    const near = faces ? 0 : -TK, far = faces ? -TK : 0;
    p.under.setAttribute("d", poly(p.shape.map(([u, v]) => at(u, v, far))));
    p.over.setAttribute("d", poly(p.shape.map(([u, v]) => at(u, v, near))));
    if (!faces) { p.head.setAttribute("d", ""); p.grid.setAttribute("d", ""); return; }
    p.head.setAttribute("d", seg(at(6, 10, 0), at(PW - 6, 10, 0)));
    let d = "";
    for (let r = 0; r < 5; r++) d += seg(at(6, 14 + r * 5.6, 0), at(PW - 6, 14 + r * 5.6, 0));
    for (let k = 1; k < 7; k++) d += seg(at(6 + k * (PW - 12) / 7, 14, 0), at(6 + k * (PW - 12) / 7, 36.4, 0));
    p.grid.setAttribute("d", d);
  }

  // paint by how far each page leans toward the viewer: the back stack, the stand, then the front
  let painted = "";
  const B2 = register(stage, (_dt, now) => {
    let moving = false;
    for (const p of pages) {
      const a = tval(p.a, now);
      if (a !== p.last) { draw(p, a); p.last = a; }
      if (!tdone(p.a, now)) moving = true;
    }
    const items = pages.map((p) => ({ el: p.grp, k: Math.sin(rad(p.last)) + p.i * 1e-4 })).concat([{ el: stand, k: 0 }]);
    items.sort((x, y) => x.k - y.k);
    const key = items.map((it) => it.k.toFixed(3)).join();
    if (key !== painted) { painted = key; for (const it of items) g.appendChild(it.el); g.appendChild(wire); }
    return moving;
  });
  bag.add(B2.unregister);

  /** The page whose tab column holds the point, read on the plane of the resting stack, which never moves; -1 off it. */
  const A0 = stackA(N / 2), sa = Math.sin(rad(A0)), ca = Math.cos(rad(A0));
  const o = P(PX0, 0, ZH), pu = P(PX0 + 1, 0, ZH), pv = P(PX0, sa, ZH - ca);
  const eu = [pu[0] - o[0], pu[1] - o[1]], ev = [pv[0] - o[0], pv[1] - o[1]], det = eu[0] * ev[1] - eu[1] * ev[0];
  function hit([x, y]) {
    const qx = x - o[0], qy = y - o[1];
    const u = (qx * ev[1] - qy * ev[0]) / det, v = (eu[0] * qy - eu[1] * qx) / det;
    if (u < -2 || u > PW + 2 || v < 0 || v > L + 4) return -1;
    return clamp(Math.round((u - 3 - TW / 2) / STEP), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    pages.forEach((p, i) => {
      const d = Math.abs(i - a);
      let th = restA(i);
      if (a >= 0) th = i === a ? UPA : i < a ? (d === 1 ? 255 : d === 2 ? 308 : backA(i)) : stackA(i) + (d === 1 ? 16 : d === 2 ? 6 : d === 3 ? 2 : 0);
      tset(p.a, th, now, from < 0 ? 0 : Math.abs(i - from) * stag);
      p.over.classList.toggle("hi", i === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "page " + (a + 1);
    B2.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "deskcalendar",
  means: "A desk flip calendar: the page under the pointer flips up over the rings, the ones in front flip to the back, the ones behind lift.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[109, 223], [177, 257], [228, 282], null],
  mount,
});

depositboxes.code:
/**
 * Safe-deposit boxes: a bank vault wall of twelve boxes, four across and
 * three high, each front with a small card plate and the two keyholes of a
 * bank key and a guest key. The pointer picks a box on the wall's face: it
 * slides out of the wall, and the boxes around it come out a little,
 * staggered from it. Only the part of a box outside the face is drawn, so
 * the gaps of the grid never show through. At rest one box stands half
 * drawn, bright, and a few sit unevenly proud of the wall. The slider is
 * the stagger.
 *
 * The pattern: one of many on a face (lockers). Tweens per box; the hit is
 * read on the wall's face plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NC = 4, NR = 3, CW = 26, CH = 15, M = 6, BASE = 8, D = 16, IN = 1.1, OUT = 30;
const W = 2 * M + NC * CW, H = BASE + NR * CH + M, FAV = [1, 1];
const PROUD = [[1.2, 2.6, 1.2], [1.2, 16, 1.6], [1.2, 1.2, 2.2], [3, 1.2, 1.2]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D + OUT, BASE], [0, 0, H], [W, 0, H], [0, D + OUT, H - M]], 200, 166);
  const P = proj(C), front = facing(C);
  const onFace = (y) => (q) => P(q.u, y, q.v);

  const g = mk("g", {}, svg);
  // the wall: a slab with its plinth line and the frame of the box field on its face
  const [wr, wi] = rings(0, 0, W, D, 3, 1.4);
  put(solid(g), prism(P, front, wr, wi, 0, H));
  mk("path", { d: seg(P(1.5, D, BASE - 3), P(W - 1.5, D, BASE - 3)), class: "nf lo" }, g);
  mk("path", { d: poly(rrect(M - 2, BASE - 1.4, W - M + 2, BASE + NR * CH + 1.4, 1.4, 3).map(onFace(D))), class: "nf lo" }, g);

  const boxes = [];
  for (let c = 0; c < NC; c++) for (let r = 0; r < NR; r++) {
    const x0 = M + c * CW + IN, x1 = M + (c + 1) * CW - IN, z0 = BASE + r * CH + IN, z1 = BASE + (r + 1) * CH - IN;
    // the box's mouth in the wall, painted before any box comes out over it
    mk("path", { d: poly(rrect(x0 - 0.5, z0 - 0.5, x1 + 0.5, z1 + 0.5, 0.8, 2).map(onFace(D))), class: "nf lo" }, g);
    boxes.push({ c, r, x0, x1, z0, z1, rest: PROUD[c][r] });
  }
  // left to right, bottom to top: a box is only ever hidden by one to its right or above it
  for (const b of boxes) {
    b.el = solid(g);
    b.plate = mk("path", { class: "nf lo" }, b.el.g);
    b.keys = mk("path", { class: "nf" }, b.el.g);
    b.s = tween(b.rest);
    b.last = NaN;
  }

  const hole = circ(1.1, 12);
  function draw(b, s) {
    const y = D + s, xm = (b.x0 + b.x1) / 2, zm = (b.z0 + b.z1) / 2 - 1;
    const [r, i] = rings(b.x0, D, b.x1, y, 1.2, Math.min(0.9, s * 0.4));
    put(b.el, prism(P, front, r, i, b.z0, b.z1));
    b.plate.setAttribute("d", poly(rrect(xm - 5, b.z1 - 4.4, xm + 5, b.z1 - 1.8, 0.6, 2).map(onFace(y))));
    let k = "";
    for (const cx of [xm - 6, xm + 6]) {
      k += poly(hole.map((q) => P(cx + q.u, y, zm + 0.6 + q.v)));
      k += seg(P(cx, y, zm - 0.2), P(cx, y, zm - 2.6));
    }
    b.keys.setAttribute("d", k);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of boxes) {
      const s = tval(b.s, now);
      if (s !== b.last) { draw(b, s); b.last = s; }
      if (!tdone(b.s, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  /** The box under the point, read on the wall's face plane (y = D), which never moves. */
  function hit([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    if (x < M || x > W - M || z < BASE || z > BASE + NR * CH) return -1;
    return clamp(Math.floor((x - M) / CW), 0, NC - 1) * NR + clamp(Math.floor((z - BASE) / CH), 0, NR - 1);
  }

  let act = -2;
  const favI = FAV[0] * NR + FAV[1];
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const ac = a >= 0 ? boxes[a] : null, fc = from >= 0 ? boxes[from] : null;
    boxes.forEach((b, i) => {
      const dist = ac ? Math.abs(b.c - ac.c) + Math.abs(b.r - ac.r) : 0;
      const s = a < 0 ? b.rest : dist === 0 ? OUT : dist === 1 ? 7 : dist === 2 ? 2.6 : 1.2;
      tset(b.s, s, now, fc ? (Math.abs(b.c - fc.c) + Math.abs(b.r - fc.r)) * stag : 0);
      b.el.sil.classList.toggle("hi", i === (a < 0 ? favI : a));
    });
    read.textContent = a < 0 ? "rest" : `box ${ac.c + 1}·${NR - ac.r}`;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "depositboxes",
  means: "A vault wall of twelve safe-deposit boxes: the box under the pointer slides out of the wall, and the boxes around it come out a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[143, 105], [235, 166], [281, 239], null],
  mount,
});

ballotbox.code:
/**
 * Ballot box: a lidded box with a long slot in its lid and a hasp on its
 * front, and beside it a low tray of six sealed envelopes standing on edge,
 * leaning back, each with its flap. The pointer picks an envelope by its
 * top edge: it stands up and rises to hang over the slot, ready to drop,
 * and the envelopes beside it lift a little, staggered from it. At rest one
 * envelope sits a little proud of the others, bright. The slider is the
 * stagger.
 *
 * The pattern: discrete items in a tray (riffle). Tweens, a stagger by
 * distance, and a hit test on static bands along the resting top edges.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, open, poly, prism, proj, rad, ringAt, rings, rrect, run, seg,
  tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, EW = 40, EH = 28, G = 7, TK = 1.2, REST = -10, FAV = 2, UP = 44;
const X0 = -4, X1 = EW + 4, Y0 = -7, Y1 = (N - 1) * G + 7, WH = 10, WR = 4, WT = 2;
const BX0 = -68, BX1 = -14, BY0 = -6, BY1 = 41, BH = 36, SY = (BY0 + BY1) / 2, SX = (BX0 + BX1) / 2;
const REST_LIFT = (i) => (i === FAV ? 6 : 0);
const LR = (pts) => (pts[0][0] <= pts[pts.length - 1][0] ? pts : pts.slice().reverse());

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[BX0 - 1, BY0 - 1, 0], [BX1, BY1, 0], [X1, Y1, 0], [X1, Y0, 0], [BX0, BY0, BH], [SX, SY, UP + EH], [X0, Y0, EH + 8]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the ballot box: body, lid, the slot in the lid, and a hasp under the lid's lip
  const [br, bi] = rings(BX0, BY0, BX1, BY1, 3, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, BH - 4));
  const [lr, li] = rings(BX0 - 1.2, BY0 - 1.2, BX1 + 1.2, BY1 + 1.2, 3.6, 1.6);
  put(solid(g), prism(P, front, lr, li, BH - 4, BH));
  mk("path", { d: poly(ringAt(P, rrect(SX - 23, SY - 1.8, SX + 23, SY + 1.8, 1.6, 4), BH)), class: "nf" }, g);
  mk("path", { d: seg(P(SX - 21.5, SY - 1.8, BH - 1.6), P(SX + 21.5, SY - 1.8, BH - 1.6)), class: "nf lo" }, g);
  const onFront = (ring) => ring.map((q) => P(q.u, BY1, q.v));
  mk("path", { d: poly(onFront(rrect(SX - 3, BH - 13, SX + 3, BH - 4, 1.2, 3))), class: "nf" }, g);
  mk("path", { d: poly(onFront(rrect(SX - 1, BH - 10, SX + 1, BH - 7, 0.9, 2))), class: "nf lo" }, g);
  mk("path", { d: seg(P(BX0 + 3, BY1, 5), P(BX1 - 3, BY1, 5)), class: "nf lo" }, g);

  // the tray's far half, painted before the envelopes
  const outer = rrect(X0, Y0, X1, Y1, WR, 6), inner = rrect(X0 + WT, Y0 + WT, X1 - WT, Y1 - WT, WR - WT, 6);
  mk("path", { d: poly(hull(ringAt(P, outer, 0).concat(ringAt(P, outer, WH)))), class: "sil" }, g);
  mk("path", { d: poly(ringAt(P, inner, WH)), class: "nf" }, g);
  mk("path", { d: open(ringAt(P, run(inner, (q) => !front(q)), 2)), class: "nf lo" }, g);

  const shape = fillet([[0, 0], [EW, 0], [EW, EH], [0, EH]], [1.2, 1.2, 1.2, 1.2]);
  const envs = [];
  for (let i = 0; i < N; i++) {
    const grp = mk("g", {}, g);
    const back = mk("path", { class: "lo" }, grp), face = mk("path", { class: "sil" }, grp);
    const flap = mk("path", { class: "nf lo" }, grp);
    envs.push({ i, back, face, flap, a: tween(REST), z: tween(REST_LIFT(i)), m: tween(0), last: "" });
  }

  // the tray's near half: one opaque piece from the rim's inner edge down to the floor
  const iF = LR(ringAt(P, run(inner, front), WH)), oT = LR(ringAt(P, run(outer, front), WH)), oB = LR(ringAt(P, run(outer, front), 0));
  mk("path", { d: poly([...iF, oT[oT.length - 1], ...oB.slice().reverse(), oT[0]]), class: "fo" }, g);
  mk("path", { d: open(oT), class: "nf lo" }, g);
  mk("path", { d: open(iF), class: "nf" }, g);
  mk("path", { d: open([oT[0], ...oB, oT[oT.length - 1]]), class: "nf sil" }, g);

  /** Envelope i leaning th degrees, lifted by z, and carried m of the way over the slot. */
  function draw(e, th, z, m) {
    const key = th.toFixed(2) + "," + z.toFixed(2) + "," + m.toFixed(3);
    if (key === e.last) return;
    e.last = key;
    const s = Math.sin(rad(th)), c = Math.cos(rad(th));
    const x0 = m * (SX - EW / 2), y0 = e.i * G + m * (SY - e.i * G);
    const w = (u, v) => P(x0 + u, y0 + v * s, v * c + z);
    const wb = (u, v) => P(x0 + u, y0 + v * s - TK * c, v * c + TK * s + z);
    e.back.setAttribute("d", poly(shape.map((p) => wb(p[0], p[1]))));
    e.face.setAttribute("d", poly(shape.map((p) => w(p[0], p[1]))));
    e.flap.setAttribute("d", open([w(1.6, EH - 1.6), w(EW / 2, EH - 13), w(EW - 1.6, EH - 1.6)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const e of envs) {
      draw(e, tval(e.a, now), tval(e.z, now), tval(e.m, now));
      if (!tdone(e.a, now) || !tdone(e.z, now) || !tdone(e.m, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  // hit bands: oblique strips along the RESTING top edges. They never move, and nothing draws them.
  const top = (i) => P(EW / 2, i * G + EH * Math.sin(rad(REST)), EH * Math.cos(rad(REST)));
  const c0 = top(0), c1 = top(1), d = [c1[0] - c0[0], c1[1] - c0[1]];
  const px0 = P(0, 0, 0), px1 = P(1, 0, 0), ex = [px1[0] - px0[0], px1[1] - px0[1]];
  const HALF = EW / 2 + 4, det = d[0] * ex[1] - d[1] * ex[0];
  function hit([x, y]) {
    const qx = x - c0[0], qy = y - c0[1];
    const s = (qx * ex[1] - qy * ex[0]) / det, r = (d[0] * qy - d[1] * qx) / det;
    if (Math.abs(r) > HALF || s < -0.6 || s > N - 0.4) return -1;
    return clamp(Math.round(s), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    envs.forEach((e, i) => {
      const dd = Math.abs(i - a), delay = from < 0 ? 0 : Math.abs(i - from) * stag;
      const z = a < 0 ? REST_LIFT(i) : dd === 0 ? UP : dd === 1 ? 7 : dd === 2 ? 3 : 0;
      tset(e.a, a === i ? 0 : REST, now, delay); tset(e.z, z, now, delay); tset(e.m, a === i ? 1 : 0, now, delay);
      e.face.classList.toggle("hi", i === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "envelope " + (N - a);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "ballotbox",
  means: "A ballot box and a tray of six envelopes: the envelope under the pointer rises over the slot, and its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[223, 157], [227, 181], [219, 211], null],
  mount,
});

icecreamtubs.code:
/**
 * Ice cream tubs: a freezer counter holding eight tubs in two rows of four,
 * each a tapered tub under a domed lid, with a scoop lying on the counter
 * beside them. The pointer picks a tub: its lid lifts and tips back to show
 * the scooped mound inside, and the lids round it lift a little, staggered
 * from it. At rest one lid sits tipped open, bright. The slider is the stagger.
 *
 * The pattern: one of many on a grid; the pick reads each tub's rest lid top
 * (rule 01), nearest first.
 */
const {
  Cam, clamp, fit, facing, hull, open, poly, prism, proj, rings, rrect, run, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const COLS = 4, ROWS = 2, PITCH = 27, X0 = 15, Y0 = 15, R = 11.5, RF = 10, TH = 10, LR = 12.4;
const LIFT = 16, TIP = 0.3, FAV = [1, 2];
const CX0 = -4, CY0 = -4, CX1 = 128, CY1 = 61, CZ = -22;

/** A circle at (cx, cy), as a ring with enough sides to stay round on screen. */
const disc = (cx, cy, r, n = 10) => rrect(cx - r, cy - r, cx + r, cy + r, r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[CX0, CY0, CZ], [CX1, CY1, CZ], [CX1, CY0, 0], [CX0, CY1, CZ], [X0, Y0, TH + 5 + LIFT + 6]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the freezer cabinet, with the seam of its sliding door on the near face
  const [cr, ci] = rings(CX0, CY0, CX1, CY1, 6, 1.6);
  const cab = solid(g);
  put(cab, prism(P, front, cr, ci, CZ, 0));
  mk("path", { class: "nf lo", d: open([P(CX0 + 8, CY1, -6), P(CX1 - 6, CY1, -6)]) + open([P(CX1, CY1 - 6, -6), P(CX1, CY0 + 8, -6)]) }, cab.g);

  // the scoop: a round bowl and a handle, lying to the right of the tubs
  const [hr, hi] = rings(119, 22, 122.4, 43, 1.7, 0.6);
  put(solid(g), prism(P, front, hr, hi, 0, 2.2));
  const bowl = mk("path", { class: "sil" }, g);
  bowl.setAttribute("d", poly(hull([...disc(120.7, 47.5, 5.2).map((s) => P(s.u, s.v, 0)), ...disc(120.7, 47.5, 3.6).map((s) => P(s.u, s.v, 4))])));
  mk("path", { class: "nf lo", d: open(run(disc(120.7, 47.5, 3.6), front).map((s) => P(s.u, s.v, 4))) }, g);

  const tubs = [];
  for (let s = 0; s <= COLS + ROWS - 2; s++)
    for (let r = 0; r < ROWS; r++) {
      const c = s - r;
      if (c < 0 || c >= COLS) continue;
      const cx = X0 + c * PITCH, cy = Y0 + r * PITCH, fav = r === FAV[0] - 1 && c === FAV[1] - 1;
      const body = solid(g), mound = mk("path", { class: "sil" }, g), curl = mk("path", { class: "nf lo" }, g);
      put(body, { sil: poly(hull([...disc(cx, cy, RF).map((p) => P(p.u, p.v, 0)), ...disc(cx, cy, R).map((p) => P(p.u, p.v, TH))])), crease: poly(disc(cx, cy, R - 1).map((p) => P(p.u, p.v, TH))) });
      // the scooped mound, a dome a little lower than the lid, with the curl a scoop leaves
      const dome = [[R - 1.4, TH - 0.5], [R - 2.4, TH + 1.6], [R - 4.4, TH + 3], [R - 7.5, TH + 3.6]];
      mound.setAttribute("d", poly(hull(dome.flatMap(([rr, z]) => disc(cx, cy, rr).map((p) => P(p.u, p.v, z))))));
      curl.setAttribute("d", open(Array.from({ length: 9 }, (_, i) => { const a = -1.9 + i * 0.32, rr = 2 + i * 0.6; return P(cx + rr * Math.cos(a), cy + rr * Math.sin(a), TH + 3.4 - i * 0.16); })));
      const lid = solid(g);
      tubs.push({ r, c, cx, cy, lid, z: tween(fav ? LIFT * 0.75 : 0), last: NaN, fav });
    }

  const ring = disc(0, 0, LR, 8), cap = disc(0, 0, LR - 2.6, 8), inner = disc(0, 0, LR - 1, 8);
  /** The lid lifted z and tipped back on its far edge as it rises, so its near rim comes up first. */
  function draw(t, z) {
    if (z === t.last) return;
    t.last = z;
    const a = (z / LIFT) * TIP, ca = Math.cos(a), sa = Math.sin(a), zb = TH - 2 + z;
    const at = (p, h) => P(t.cx + p.u, t.cy + p.v * ca - h * sa, zb + h * ca + p.v * sa);
    const sil = poly(hull([...ring.map((p) => at(p, 0)), ...ring.map((p) => at(p, 4.5)), ...cap.map((p) => at(p, 6.5))]));
    put(t.lid, { sil, crease: open(run(inner, front).map((p) => at(p, 4.5))) });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const t of tubs) { draw(t, tval(t.z, now)); if (!tdone(t.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  /** The nearest tub whose closed lid top holds the point, read on that top's plane; then the counter. */
  function hit([sx, sy]) {
    for (let n = tubs.length - 1; n >= 0; n--) {
      const t = tubs[n], [x, y] = unproj(C, sx, sy, TH + 4.5);
      if (Math.hypot(x - t.cx, y - t.cy) < R + 2) return n;
    }
    for (let n = tubs.length - 1; n >= 0; n--) {
      const t = tubs[n], [x, y] = unproj(C, sx, sy, TH / 2);
      if (Math.hypot(x - t.cx, y - t.cy) < R) return n;
    }
    return -1;
  }

  let act = -2;
  const gd = (a, b) => Math.hypot(a.r - b.r, a.c - b.c);
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act, A = tubs[a];
    act = a;
    for (const t of tubs) {
      const z = a < 0 ? (t.fav ? LIFT * 0.75 : 0) : t === A ? LIFT : clamp(5 - gd(A, t) * 2.5, 0, 5);
      tset(t.z, z, now, from < 0 ? 0 : gd(tubs[from], t) * stag);
      t.lid.sil.classList.toggle("hi", a < 0 ? t.fav : t === A);
    }
    read.textContent = a < 0 ? "rest" : "tub " + (A.r + 1) + "·" + (A.c + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "icecreamtubs",
  means: "Eight ice cream tubs: the lid of the one under the pointer lifts off its scooped mound, and lids nearby lift a little.",
  rules: [1, 2, 5, 9],
  range: [0, 45, 90],
  tour: [[155, 98], [191, 152], [263, 152], null],
  mount,
});

railsignals.code:
/**
 * Rail signals: a short length of track, two rails on sleepers over a ballast
 * bed, with four semaphore signals on posts along its far side, each a post
 * with a finial, an arm that pivots near its top and a spectacle plate below
 * the pivot. The pointer picks a signal: its arm swings up to clear, and the
 * arms beside it swing partway, staggered from it. At rest one arm stands
 * clear, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the post whose
 * resting middle is nearest the pointer on screen.
 */
const {
  Cam, fillet, fit, facing, hull, open, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const L = 150, SX = [18, 56, 94, 132], PH = [48, 56, 52, 44], SY = -13, FAV = 2, UP = 60;
const AY = SY + 2.4, PIV = 6;
// the arm in its own plane: r along it from the pivot, w across it, a blade that narrows to a square end
const BLADE = fillet([[2, -2.9], [27, -2.4], [27, 2.4], [2, 2.9]], [1.2, 0.7, 0.7, 1.2], 3);
const SPEC = fillet([[-1.5, -3], [-1.5, -12.5], [-9.5, -12.5], [-9.5, -3]], [1.4, 2.4, 2.4, 1.4], 3);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-4, 24, -3], [L + 4, 24, -3], [L + 4, -6, -3], [SX[0] - 4, SY - 4, 0], [SX[1], SY, PH[1] + 3], [SX[1] + 16, SY, PH[1] - PIV + 24], [SX[3] + 28, SY, PH[3] - PIV]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const sigs = [];
  SX.forEach((px, k) => {
    const h = PH[k], pz = h - PIV;
    const [fr, fi] = rings(px - 4, SY - 4, px + 4, SY + 4, 1.6, 0.8);
    put(solid(g), prism(P, front, fr, fi, -1, 2));
    const [pr, pi] = rings(px - 1.8, SY - 1.8, px + 1.8, SY + 1.8, 0.9, 0.5);
    put(solid(g), prism(P, front, pr, pi, 2, h));
    const [cr, ci] = rings(px - 2.4, SY - 2.4, px + 2.4, SY + 2.4, 1.2, 0.6);
    put(solid(g), prism(P, front, cr, ci, h, h + 2.2));
    const spec = mk("path", { class: "sil" }, g), lens = mk("path", { class: "nf lo" }, g);
    const arm = mk("path", { class: "sil" }, g), band = mk("path", { class: "nf lo" }, g);
    place(mk("circle", { r: 1.7, class: "dot m" }, g), P(px, AY + 0.8, pz));
    sigs.push({ k, px, pz, spec, lens, arm, band, a: tween(k === FAV ? UP : 0), last: NaN, mid: P(px, SY, h * 0.6) });
  });

  // the ballast bed, then sleepers, then the two rails on them
  const [br, bi] = rings(-4, -6, L + 4, 24, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, -3, 0));
  for (let x = 5; x < L; x += 14) {
    const [sr, si] = rings(x - 2.2, -2.5, x + 2.2, 20.5, 0.8, 0.5);
    put(solid(g), prism(P, front, sr, si, 0, 1.4));
  }
  for (const y of [3.2, 14.8]) {
    const [rr, ri] = rings(-2, y - 0.9, L + 2, y + 0.9, 0.6, 0.35);
    put(solid(g), prism(P, front, rr, ri, 1.4, 3.6));
  }

  /** The arm at angle a above level, turned about its pivot in the plane in front of the post. */
  function draw(s, a) {
    if (a === s.last) return;
    s.last = a;
    const t = rad(a), c = Math.cos(t), n = Math.sin(t);
    const at = ([r, w], y) => P(s.px + r * c - w * n, y, s.pz + r * n + w * c);
    const plate = (pts) => poly(hull([...pts.map((p) => at(p, AY)), ...pts.map((p) => at(p, AY + 0.9))]));
    s.spec.setAttribute("d", plate(SPEC));
    s.arm.setAttribute("d", plate(BLADE));
    s.band.setAttribute("d", seg(at([18, -2.6], AY + 0.9), at([18, 2.6], AY + 0.9)) + seg(at([21.5, -2.5], AY + 0.9), at([21.5, 2.5], AY + 0.9)));
    s.lens.setAttribute("d", [-5.6, -9.9].map((w) => open(Array.from({ length: 13 }, (_, i) => { const u = (i / 12) * Math.PI * 2; return at([-5.5 + 1.9 * Math.cos(u), w + 1.9 * Math.sin(u)], AY + 0.9); }))).join(""));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const s of sigs) { draw(s, tval(s.a, now)); if (!tdone(s.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    sigs.forEach((s, k) => { const d = Math.hypot(s.mid[0] - sx, (s.mid[1] - sy) * 0.35); if (d < bd) { bd = d; best = k; } });
    return bd < 26 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    sigs.forEach((s, k) => {
      const d = Math.abs(k - a), to = a < 0 ? (k === FAV ? UP : 0) : d === 0 ? UP : d === 1 ? 30 : 12;
      tset(s.a, to, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      s.arm.classList.toggle("hi", on);
      s.spec.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "signal " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "railsignals",
  means: "Four semaphore signals beside a track: the arm under the pointer swings up to clear, and its neighbours swing partway.",
  rules: [1, 2, 5, 10],
  range: [0, 45, 90],
  tour: [[141, 90], [195, 114], [302, 182], null],
  mount,
});

conveyor.code:
/**
 * Conveyor: a factory belt on legs, fed by a chute at one end and running into
 * a hood at the other, with a scanner arch over its middle. Five boxes drop
 * from the chute, ride the belt under the arch and leave through the hood,
 * all the time the figure is in view. Hovering slows the belt, on a spring
 * on its rate, so a box can be read, and the box nearest the pointer is
 * bright. At rest the scanner's beam is bright. The slider is the slowed rate.
 *
 * The pattern: slow (dilate time); depth order changes as a box leaves the
 * chute, so its group moves between two layers instead of being redrawn.
 */
const {
  Cam, fit, facing, open, prism, proj, reducedMotion, rings, seg, spring, stepS,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const L = 168, W = 24, Z = 26, AX = 76, CH = 22, HD = 142, DROP = 12, RIDE = 139, U = DROP + RIDE, V0 = 16, FALL = 19;
// width along the belt, depth across it, height
const BOX = [[16, 14, 12], [13, 13, 10], [15, 16, 13], [12, 12, 9], [14, 15, 11]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let slow = value, over = null;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[0, -7, 0], [L, W + 7, 0], [L, -7, Z - 6], [0, W + 7, 0], [2, 1, Z + 36], [AX, -7, Z + 28]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (parent, x0, y0, x1, y1, r, b, z0, z1) => { const s = solid(parent), [o, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, o, i, z0, z1)); return s; };

  // legs, far row then near, each pair on a foot rail, then the belt over them
  for (const y of [1, W - 4]) for (const x of [12, 84, 150]) block(g, x - 1.6, y, x + 1.6, y + 3, 0.8, 0.5, 0, Z - 5);
  block(g, 0, 0, L, W, 3, 1.2, Z - 5, Z);
  place(mk("circle", { r: 1.6, class: "dot off" }, g), P(3, W, Z - 2.5));
  const cleats = mk("path", { class: "nf lo" }, g);
  mk("path", { class: "nf dash", d: seg(P(AX, 1, Z), P(AX, W - 1, Z)) }, g);

  const layA = mk("g", {}, g);
  block(g, 2, 1, CH, W - 1, 3, 1.2, Z + 16, Z + 36);
  block(g, AX - 2, -7, AX + 2, -3, 1, 0.5, 0, Z + 26);
  const layB = mk("g", {}, g);
  block(g, AX - 2, W + 3, AX + 2, W + 7, 1, 0.5, 0, Z + 26);
  const beam = block(g, AX - 2.6, -8, AX + 2.6, W + 8, 1.4, 0.7, Z + 24, Z + 28.5);
  block(g, HD, -3, L + 2, W + 3, 4, 1.6, Z - 6, Z + 18);

  const boxes = BOX.map(([w, d, h], k) => {
    const s = solid(layA), tape = mk("path", { class: "nf lo" }, s.g);
    return { k, w, d, h, s, tape, u: ((BOX.length - k) * U) / BOX.length % U, lay: layA, xc: 0, z: 0, last: "" };
  });

  /** Where a box is along its path: dropping out of the chute, then riding to the hood. */
  function pose(b) {
    if (b.u < DROP) { const t = b.u / DROP; b.xc = CH / 2 + 1; b.z = Z + FALL * (1 - t * t); }
    else { b.xc = CH / 2 + 1 + b.u - DROP; b.z = Z; }
  }
  function draw(b) {
    pose(b);
    const key = b.xc.toFixed(2) + b.z.toFixed(2);
    if (key === b.last) return;
    b.last = key;
    const x0 = b.xc - b.w / 2, y0 = (W - b.d) / 2, top = b.z + b.h;
    const [o, i] = rings(x0, y0, x0 + b.w, y0 + b.d, 1.6, 0.8);
    put(b.s, prism(P, front, o, i, b.z, top));
    b.tape.setAttribute("d", seg(P(x0 + 1, W / 2, top), P(x0 + b.w, W / 2, top)) + seg(P(x0 + b.w, W / 2, top), P(x0 + b.w, W / 2, top - 4)));
    const lay = x0 < CH ? layA : layB;
    if (lay !== b.lay) { b.lay = lay; lay.prepend(b.s.g); }
  }

  let phase = 0, drawnPhase = NaN;
  function drawCleats() {
    if (phase === drawnPhase) return;
    drawnPhase = phase;
    let d = "";
    for (let x = 3 + (phase % 10); x < HD; x += 10) d += seg(P(x, 1.5, Z), P(x, W - 1.5, Z));
    cleats.setAttribute("d", d);
  }

  let lit;
  const rate = spring(V0, { eps: 0.05 }), still = reducedMotion();
  const B = register(stage, (dt) => {
    let m = stepS(rate, dt);
    if (!still) {
      const du = rate.x * dt;
      phase = (phase + du) % 10;
      for (const b of boxes) b.u = (b.u + du) % U;
      m = true;
    }
    for (const b of boxes) draw(b);
    drawCleats();
    pick();
    return m;
  });
  bag.add(B.unregister);

  /** The box nearest the pointer on screen, from the top of where it is now; boxes in the chute or hood do not count. */
  function pick() {
    let best = null, bd = Infinity;
    if (over) for (const b of boxes) {
      if (b.xc + b.w / 2 > HD || b.z > Z + FALL / 2) continue;
      const [sx, sy] = P(b.xc, W / 2, b.z + b.h / 2), d = Math.hypot(sx - over[0], sy - over[1]);
      if (d < bd) { bd = d; best = b; }
    }
    if (best === lit && (over || lit === null)) return;
    lit = best;
    for (const b of boxes) b.s.sil.classList.toggle("hi", b === lit);
    beam.sil.classList.toggle("hi", !lit);
    read.textContent = lit ? "box " + (lit.k + 1) : over ? "belt" : "rest";
  }

  function retarget() { rate.t = over ? slow : V0; pick(); B.wake(); }
  bag.add(pointer(stage, { move: (p) => { over = p; retarget(); }, leave: () => { over = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  for (const b of boxes) draw(b);
  drawCleats();
  lit = undefined;
  pick();
  return { set: (v) => { slow = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "conveyor",
  means: "Boxes ride a conveyor belt through a scanner arch: hovering slows the belt, and the box nearest the pointer is bright.",
  rules: [1, 5, 7, 8],
  range: [0, 4, 10],
  tour: [[150, 140], [189, 156], [245, 185], null],
  mount,
});

barrels.code:
/**
 * Barrels: six oil drums lying in a pyramid, three, two and one, on a pallet,
 * each a hooped can with a bung in its end. The pointer picks a drum by where
 * it rests: that drum slides forward out of the stack toward the reader, and
 * the drums it touches shift a little, staggered from it. At rest the top
 * drum stands proud, bright. The slider is the stagger.
 *
 * The pattern: one of many at different heights (riffle, stepped): the hit
 * reads each drum's rest centre, never the pose on screen.
 */
const {
  Cam, facing, fit, hull, open, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 12, LD = 30, DECK = 9, SLIDE = 20, NB = 5, FAV = 5, X0 = 3;
const H3 = R * Math.sqrt(3);
// the stack, as [x, z] of each axis: the bottom row, the middle, the top
const AX = [[X0 + R, DECK + R], [X0 + 3 * R, DECK + R], [X0 + 5 * R, DECK + R],
  [X0 + 2 * R, DECK + R + H3], [X0 + 4 * R, DECK + R + H3], [X0 + 3 * R, DECK + R + 2 * H3]];
const REST = [1.5, -1, 3, 2.5, 0, 11];
const PX0 = -2, PX1 = X0 + 6 * R + 5, PY0 = -4, PY1 = LD + 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  const top = DECK + R + 2 * H3 + R;
  fit(C, [[PX0, PY0, 0], [PX1, PY1, 0], [PX1, PY0, 0], [PX0, PY1 + SLIDE - 6, 0], [X0 + 3 * R, 0, top], [X0 + 3 * R, LD + SLIDE, top], [X0 + R - R, LD + SLIDE, DECK + R]], 200, 166);
  const P = proj(C), front = facing(C);
  // the view direction, for the half of each hoop that faces the reader
  const vx = Math.sin(C.az) * Math.sqrt(1 - C.k * C.k), vz = C.k, phi = Math.atan2(vz, vx);
  const g = mk("g", {}, svg);

  // the pallet: three runners along x, far to near, then the deck and its board seams
  for (const [a, b] of [[PY0, PY0 + 6], [(PY0 + PY1) / 2 - 3, (PY0 + PY1) / 2 + 3], [PY1 - 6, PY1]]) {
    const [r, i] = rings(PX0 + 1, a, PX1 - 1, b, 1.2, 0.6);
    put(solid(g), prism(P, front, r, i, 0, DECK - 3));
  }
  const [dr, di] = rings(PX0, PY0, PX1, PY1, 2, 1.2);
  put(solid(g), prism(P, front, dr, di, DECK - 3, DECK));
  let seams = "";
  for (let k = 1; k < 4; k++) { const y = PY0 + ((PY1 - PY0) * k) / 4; seams += open([P(PX0 + 2.5, y, DECK), P(PX1 - 2.5, y, DECK)]); }
  mk("path", { class: "nf lo", d: seams }, g);

  // the drums, painted far to near: their axes all run along y, so depth is x and z alone
  const drums = AX.map(([x, z], k) => ({ k, x, z, o: tween(REST[k]), last: NaN }));
  const order = drums.slice().sort((a, b) => (0.61 * a.x + 0.5 * a.z) - (0.61 * b.x + 0.5 * b.z));
  for (const d of order) {
    d.grp = mk("g", {}, g);
    d.body = mk("path", { class: "sil" }, d.grp);
    d.marks = mk("path", { class: "nf lo" }, d.grp);
  }

  const around = (x, y, z, r, n, t0 = 0, t1 = Math.PI * 2, closed = true) =>
    Array.from({ length: n + (closed ? 0 : 1) }, (_, i) => { const t = t0 + ((t1 - t0) * i) / n; return P(x + r * Math.cos(t), y, z + r * Math.sin(t)); });

  /** The run of a closed ring off the hull, with the hull point at each end: the edge of the end not already on the silhouette. */
  function inside(ring, sil) {
    const n = ring.length, on = ring.map((p) => sil.some((q) => Math.abs(q[0] - p[0]) + Math.abs(q[1] - p[1]) < 1e-6));
    const s = on.findIndex((v, i) => v && !on[(i + 1) % n]);
    if (s < 0) return ring;
    const out = [ring[s]];
    for (let i = 1; i <= n; i++) { const j = (s + i) % n; out.push(ring[j]); if (on[j]) break; }
    return out;
  }

  /** A drum slid o along its axis: its body, then its end, two bungs and the two hoops' near halves. */
  function draw(d, o) {
    if (o === d.last) return;
    d.last = o;
    const y0 = o, y1 = o + LD, end = around(d.x, y1, d.z, R, 48), sil = hull(around(d.x, y0, d.z, R, 48).concat(end));
    d.body.setAttribute("d", poly(sil));
    let m = open(inside(end, sil));
    m += poly(around(d.x + 0.62 * R * Math.cos(1.05), y1, d.z + 0.62 * R * Math.sin(1.05), 2, 12));
    m += poly(around(d.x + 0.62 * R * Math.cos(2.4), y1, d.z + 0.62 * R * Math.sin(2.4), 1.1, 10));
    for (const f of [1 / 3, 2 / 3]) m += open(around(d.x, y0 + LD * f, d.z, R + 0.3, 16, phi - Math.PI / 2, phi + Math.PI / 2, false));
    d.marks.setAttribute("d", m);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const d of drums) { draw(d, tval(d.o, now)); if (!tdone(d.o, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // the hit: each drum's rest centre on screen, the nearest within reach
  const mids = drums.map((d) => P(d.x, LD * 0.55, d.z));
  const reach = R * C.S * 1.25;
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < reach ? best : -1;
  }
  const apart = (a, b) => Math.round(Math.hypot(drums[a].x - drums[b].x, drums[a].z - drums[b].z) / (2 * R));

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    drums.forEach((d, k) => {
      const n = a < 0 ? -1 : apart(k, a);
      const o = a < 0 ? REST[k] : n === 0 ? SLIDE : n === 1 ? NB + REST[k] * 0.4 : REST[k] * 0.3;
      tset(d.o, o, now, from < 0 ? 0 : apart(k, from) * stag);
      d.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "drum " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "barrels",
  means: "Six oil drums stacked on a pallet: the one under the pointer slides out toward you, and the drums it touches shift a little.",
  rules: [1, 2, 5, 9],
  range: [0, 45, 90],
  tour: [[193, 128], [213, 179], [229, 210], null],
  mount,
});

telescope.code:
/**
 * Telescope: a refractor on a tripod, a long tube with a dew shield, a finder
 * scope on top and a star diagonal at the back, on an alt-azimuth arm. The
 * pointer is a star: the tube swings in azimuth and tips in altitude to aim
 * at it, each on its own spring, and the star sits bright on the line of
 * sight. At rest it holds a star high to the left. The slider is how quickly
 * the tube follows (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (spotlights' spring, on two angles); the aim
 * reads the pointer alone, never the tube on screen.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rad, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PV = [0, 0, 64], R1 = 6, R2 = 7.4, BACK = rad(225), SPAN = rad(70), PMIN = rad(6), PMAX = rad(58);
const STAR = 64, DEEP = 80, FOOT = 34, TOP = 47, LEGS = [200, 320, 80].map(rad), REST = [rad(28), rad(34)];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.1);
  const dirOf = (a, p) => [Math.cos(BACK + a) * Math.cos(p), Math.sin(BACK + a) * Math.cos(p), Math.sin(p)];
  const at = (o, ...t) => [0, 1, 2].map((j) => t.reduce((s, [v, k]) => s + v[j] * k, o[j]));
  const pts = LEGS.map((t) => [FOOT * Math.cos(t), FOOT * Math.sin(t), 0]);
  for (const a of [-SPAN, 0, SPAN]) for (const p of [PMIN, PMAX]) { const d = dirOf(a, p); pts.push(at(PV, [d, STAR + 3]), at(PV, [d, -30])); }
  fit(C, pts, 200, 154);
  const P = proj(C), front = facing(C);
  const zf = Math.sqrt(1 - C.k * C.k), vw = [Math.sin(C.az) * zf, Math.cos(C.az) * zf, C.k];
  const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  const g = mk("g", {}, svg);

  /** The run of a closed ring off the hull, with the hull point at each end: the edge of an end not already on the silhouette. */
  function inside(ring, sil) {
    const n = ring.length, on = ring.map((p) => sil.some((q) => Math.abs(q[0] - p[0]) + Math.abs(q[1] - p[1]) < 1e-6));
    const s = on.findIndex((v, i) => v && !on[(i + 1) % n]);
    if (s < 0) return ring;
    const out = [ring[s]];
    for (let i = 1; i <= n; i++) { const j = (s + i) % n; out.push(ring[j]); if (on[j]) break; }
    return out;
  }
  /** A cylinder along ax through c, radius r from s0 to s1; e1, e2 span its rings. Its crease is the end that faces the reader. */
  function cyl(el, c, ax, e1, e2, r, s0, s1, n = 28) {
    const ring = (s) => Array.from({ length: n }, (_, i) => { const t = (i / n) * Math.PI * 2; return P(...at(c, [ax, s], [e1, r * Math.cos(t)], [e2, r * Math.sin(t)])); });
    const a = ring(s0), b = ring(s1), sil = hull(a.concat(b));
    el.sil.setAttribute("d", poly(sil));
    el.cr.setAttribute("d", open(inside(dot(ax, vw) > 0 ? b : a, sil)));
  }

  // the tripod: three legs, the far one first, then the head and the azimuth base
  const legs = LEGS.map((t) => {
    const f = [FOOT * Math.cos(t), FOOT * Math.sin(t), 0], h = [5 * Math.cos(t), 5 * Math.sin(t), TOP], ax = at(h, [f, -1]), L = Math.hypot(...ax);
    const d = ax.map((v) => v / L), e1 = [-Math.sin(t), Math.cos(t), 0], e2 = [d[1] * e1[2] - d[2] * e1[1], d[2] * e1[0] - d[0] * e1[2], d[0] * e1[1] - d[1] * e1[0]];
    const el = solid(g);
    cyl(el, f, d, e1, e2, 1.7, 0, L, 16);
    el.cr.setAttribute("d", seg(P(...at(f, [d, L * 0.5], [e1, -1.7])), P(...at(f, [d, L * 0.5], [e1, 1.7]))));
    return el;
  });
  put(solid(g), prism(P, front, circ(8, 40), circ(6.6, 40), TOP, TOP + 4));
  put(solid(g), prism(P, front, circ(5, 32), circ(3.8, 32), TOP + 4, TOP + 9));

  // the moving parts, in a group each, reordered by which way the tube faces
  const sight = mk("path", { class: "nf dash" }, g);
  const star = mk("circle", { r: 2.4, class: "dot" }, g);
  const parts = {};
  for (const k of ["armB", "dew", "body", "finder", "focus", "diag", "armF"]) parts[k] = solid(g);
  const brackets = mk("path", { class: "nf lo" }, parts.finder.g, );
  parts.finder.g.prepend(brackets);
  const ay = spring(REST[0], { k: 100 * value, c: 18 * Math.sqrt(value) }), ap = spring(REST[1], { k: 100 * value, c: 18 * Math.sqrt(value) });
  let lastKey = "", lastOrder = "";

  function draw() {
    const key = ay.x.toFixed(4) + "," + ap.x.toFixed(4);
    if (key === lastKey) return;
    lastKey = key;
    const y = BACK + ay.x, p = ap.x, d = dirOf(ay.x, p);
    const u = [-Math.sin(y), Math.cos(y), 0], v = [-Math.sin(p) * Math.cos(y), -Math.sin(p) * Math.sin(y), Math.cos(p)], nd = d.map((x) => -x);
    cyl(parts.dew, PV, d, u, v, R2, 27, 44);
    cyl(parts.body, PV, d, u, v, R1, -18, 28);
    const fc = at(PV, [v, R1 + 4.6]);
    cyl(parts.finder, fc, d, u, v, 2.2, 0, 17, 20);
    brackets.setAttribute("d", [3, 13].map((s) => seg(P(...at(PV, [d, s], [v, R1])), P(...at(fc, [d, s], [v, -2.2])))).join(""));
    cyl(parts.focus, PV, d, u, v, 3.2, -26, -18, 20);
    cyl(parts.diag, at(PV, [d, -24]), v, u, nd, 2.4, 2.5, 11, 18);
    // the altitude arm on the tube's +u side: a post from the base and a hub at the pivot
    const side = dot(u, vw) > 0 ? parts.armF : parts.armB, other = side === parts.armF ? parts.armB : parts.armF;
    const foot = at([0, 0, TOP + 7], [u, R1 + 4]);
    cyl(side, foot, [0, 0, 1], [1, 0, 0], [0, 1, 0], 2.3, 0, PV[2] - foot[2], 16);
    side.cr.setAttribute("d", side.cr.getAttribute("d") + poly(Array.from({ length: 16 }, (_, i) => { const t = (i / 16) * Math.PI * 2; return P(...at(PV, [u, R1 + 1.5], [d, 3.4 * Math.cos(t)], [v, 3.4 * Math.sin(t)])); })));
    other.sil.setAttribute("d", ""); other.cr.setAttribute("d", "");
    const tip = at(PV, [d, STAR]);
    sight.setAttribute("d", seg(P(...at(PV, [d, 47])), P(...at(PV, [d, STAR - 4]))));
    star.setAttribute("cx", P(...tip)[0]); star.setAttribute("cy", P(...tip)[1]);
    // the end that faces away is painted first
    const order = dot(d, vw) < 0 ? ["armB", "dew", "body", "finder", "focus", "diag", "armF"] : ["armB", "diag", "focus", "body", "finder", "dew", "armF"];
    if (order.join() !== lastOrder) { lastOrder = order.join(); for (const k of order) g.append(parts[k].g); }
  }

  const B = register(stage, (dt) => { const a = stepS(ay, dt), b = stepS(ap, dt); draw(); return a || b; });
  bag.add(B.unregister);

  // the aim: the world point under the pointer, DEEP behind the pivot along the line of sight; it never reads the tube
  function aim([sx, sy]) {
    const X = (sx - C.ox) / C.S, Ys = (sy - C.oy) / C.S, dp = dot(PV, vw) - DEEP;
    const Y = C.k * Ys + zf * dp, z = -zf * Ys + C.k * dp, c = Math.cos(C.az), s = Math.sin(C.az);
    const t = [X * c + Y * s - PV[0], -X * s + Y * c - PV[1], z - PV[2]];
    let a = Math.atan2(t[1], t[0]) - BACK;
    a = Math.atan2(Math.sin(a), Math.cos(a));
    return [clamp(a, -SPAN, SPAN), clamp(Math.atan2(t[2], Math.hypot(t[0], t[1])), PMIN, PMAX)];
  }

  function retarget(q) {
    const [a, p] = q ? aim(q) : REST;
    ay.t = a; ap.t = p;
    const az = Math.round(((((BACK + a) * 180) / Math.PI) % 360 + 360) % 360);
    read.textContent = q ? `az ${az}°` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, { move: (q) => retarget(q), leave: () => retarget(null) }));
  bag.add(() => svg.replaceChildren());
  retarget(null);
  return {
    set: (v) => { ay.k = ap.k = 100 * v; ay.c = ap.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "telescope",
  means: "A refracting telescope on a tripod swings and tips to aim at the pointer, as if tracking a star.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[120, 90], [280, 80], [200, 60], null],
  mount,
});

wifirouter.code:
/**
 * Wi-Fi router: a low rounded box with four hinged antennas along its back
 * and a row of status lights on its front. The pointer is where the signal
 * should go: every antenna tilts toward it on its own spring, the nearest
 * fully and the others less, and the nearest one's light comes on. At rest
 * the antennas stand in a loose fan and the second is bright. The slider is
 * how far the tilt reaches.
 *
 * The pattern: a continuous field (solarfarm): springs, a falloff by rank,
 * and a hit on the box top's plane, which never moves.
 */
const {
  Cam, clamp, facing, fit, hull, open, place, poly, prism, proj, rad, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 50, BY = 28, BH = 13, AX = [-36, -12, 12, 36], AY = -BY + 5, L = 44, AR = 2.6, MAX = 48, FAV = 1;
const REST = [[-26, 4], [-9, -5], [7, 3], [24, -4]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value, over = null;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-BX, -BY, 0], [BX, BY, 0], [BX, -BY, 0], [-BX, BY, 0], [-BX - 20, AY, BH + L], [BX + 20, AY, BH + L], [0, AY + 30, BH + L * 0.7], [0, AY - 30, BH + L * 0.7]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the box, its vents, and the lights on its front face
  const [br, bi] = rings(-BX, -BY, BX, BY, 7, 1.8);
  put(solid(g), prism(P, front, br, bi, 0, BH));
  let vents = "";
  for (let k = 0; k < 5; k++) { const x = -14 + k * 7; vents += seg(P(x, -4, BH), P(x, 14, BH)); }
  mk("path", { class: "nf lo", d: vents }, g);
  place(mk("circle", { r: 1.4, class: "dot m" }, g), P(-32, BY, BH * 0.5));
  const lights = AX.map((_, k) => { const el = mk("circle", { r: 1.4, class: "dot off" }, g); place(el, P(-20 + k * 9, BY, BH * 0.5)); return el; });

  // the antennas, left to right: a hinge block and a rounded rod each
  const ants = AX.map((x, k) => {
    const [hr, hi] = rings(x - 4, AY - 3.5, x + 4, AY + 3.5, 1.6, 0.7);
    put(solid(g), prism(P, front, hr, hi, BH, BH + 4));
    const grp = mk("g", {}, g), rod = mk("path", { class: "sil" }, grp), seam = mk("path", { class: "nf lo" }, grp);
    return { k, x, rod, seam, lx: spring(REST[k][0], { eps: 0.05 }), ly: spring(REST[k][1], { eps: 0.05 }), drawn: "" };
  });

  /** A rod leaning (lx, ly) degrees from upright: the hull of two round ends, and a seam at its swivel. */
  function draw(a) {
    const key = a.lx.x.toFixed(2) + "," + a.ly.x.toFixed(2);
    if (key === a.drawn) return;
    a.drawn = key;
    const t = rad(Math.hypot(a.lx.x, a.ly.x)), n = Math.hypot(a.lx.x, a.ly.x) || 1;
    const d = [Math.sin(t) * (a.lx.x / n), Math.sin(t) * (a.ly.x / n), Math.cos(t)];
    const b = [a.x, AY, BH + 2], q = (s) => P(b[0] + d[0] * s, b[1] + d[1] * s, b[2] + d[2] * s);
    const r = AR * C.S, ring = (c) => Array.from({ length: 18 }, (_, i) => [c[0] + r * Math.cos((i / 18) * Math.PI * 2), c[1] + r * Math.sin((i / 18) * Math.PI * 2)]);
    const p0 = q(0), p1 = q(L);
    a.rod.setAttribute("d", poly(hull(ring(p0).concat(ring(p1)))));
    const m = q(L * 0.24), dx = p1[0] - p0[0], dy = p1[1] - p0[1], dl = Math.hypot(dx, dy) || 1, ex = (-dy / dl) * (r - 1), ey = (dx / dl) * (r - 1);
    a.seam.setAttribute("d", open([[m[0] - ex, m[1] - ey], [m[0] + ex, m[1] + ey]]));
  }

  const B = register(stage, (dt) => {
    let mv = false;
    for (const a of ants) { if (stepS(a.lx, dt)) mv = true; if (stepS(a.ly, dt)) mv = true; draw(a); }
    return mv;
  });
  bag.add(B.unregister);

  const falloff = [1, 0.55, 0.32, 0.2], mids = AX.map((x) => P(x, AY, BH + L / 2)[0]);
  let sx = 0;
  function retarget() {
    let mark = FAV;
    if (over) {
      mark = ants.reduce((m, a) => (Math.abs(mids[a.k] - sx) < Math.abs(mids[m] - sx) ? a.k : m), 0);
      for (const a of ants) {
        const dx = over[0] - a.x, dy = over[1] - AY, dd = Math.hypot(dx, dy) || 1;
        const ang = clamp(dd * 0.9, 0, MAX) * (falloff[Math.min(3, Math.round(Math.abs(a.k - mark) / reach))] ?? 0.2);
        a.lx.t = (ang * dx) / dd; a.ly.t = (ang * dy) / dd;
      }
      read.textContent = "antenna " + (mark + 1);
    } else {
      for (const a of ants) { a.lx.t = REST[a.k][0]; a.ly.t = REST[a.k][1]; }
      read.textContent = "rest";
    }
    ants.forEach((a) => a.rod.classList.toggle("hi", a.k === mark));
    lights.forEach((el, k) => el.setAttribute("class", k === mark ? "dot" : "dot off"));
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { sx = p[0]; const w = unproj(C, p[0], p[1], BH); over = [clamp(w[0], -BX - 30, BX + 30), clamp(w[1], -BY - 50, BY + 30)]; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "wifirouter",
  means: "A router with four antennas: each tilts toward the pointer, the nearest fully, and its status light comes on.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 2],
  tour: [[170, 112], [240, 147], [275, 164], null],
  mount,
});

drumkit.code:
/**
 * Drum kit: a bass drum on its side with two toms mounted over it, a snare on
 * a tripod stand, a floor tom on three legs and a crash cymbal on a tall
 * stand. The pointer is a stick: the drums near it bounce down on their own
 * springs, the one under it deepest and bright. At rest the snare sits a
 * little low, bright, and the others settle unevenly. The slider is the reach.
 *
 * The pattern: a continuous field (terrain) over parts at different heights;
 * the hit is on each drum's own resting top, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, poly, prism, proj, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const Q = Math.SQRT1_2;
// a runs across the screen, b toward the viewer
const W = (a, b, z) => [(a + b) * Q, (b - a) * Q, z];
const KR = 17, KL = 8;
const DRUMS = [
  { name: "crash", a: -48, b: -16, r: 13, z0: 62, z1: 63.4, dmax: 5, rest: 2.2, cym: true },
  { name: "kick", a: 0, b: 0, r: KR, z0: 0, z1: 2 * KR, dmax: 1.6, rest: 0, kick: true },
  { name: "tom 1", a: -10, b: -4, r: 8, z0: 40, z1: 49, dmax: 4, rest: 1.4 },
  { name: "tom 2", a: 10, b: -4, r: 8.5, z0: 41, z1: 51, dmax: 4, rest: 0 },
  { name: "snare", a: -36, b: 6, r: 10, z0: 25, z1: 31, dmax: 4, rest: 2.8 },
  { name: "floor", a: 36, b: 8, r: 12, z0: 8, z1: 28, dmax: 4, rest: 0.8 },
];
const FAV = "snare";
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value, over = null;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [W(-62, -30, 0), W(50, -30, 0), W(-62, 22, 0), W(50, 22, 0), W(-62, -30, 66), W(50, -30, 66), W(-62, 22, 66)], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const disc = (d, r, n = 40) => { const [x, y] = W(d.a, d.b, 0); return circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y })); };
  const lines = (parts) => mk("path", { class: "nf sil", d: parts.join("") }, g);
  const tripod = (d, top, foot, spread, phase) => {
    const out = [seg(P(...W(d.a, d.b, 0.5)), P(...W(d.a, d.b, top)))];
    for (let i = 0; i < 3; i++) {
      const t = phase + (i / 3) * Math.PI * 2;
      out.push(seg(P(...W(d.a, d.b, foot)), P(...W(d.a + spread * Math.cos(t), d.b + spread * Math.sin(t), 0))));
    }
    return out;
  };

  for (const d of DRUMS) {
    d.sp = spring(d.rest, { eps: 0.02 });
    d.drawn = NaN;
    if (d.cym) { lines(tripod(d, d.z0, 12, 9, 0.6)); d.el = solid(g); d.bell = solid(g); }
    else if (d.kick) d.el = solid(g);
    else if (d.name === "snare") { lines(tripod(d, d.z0, 9, 8, -0.4)); d.el = solid(g); }
    else if (d.name === "floor") {
      const legs = [];
      for (const t of [Math.PI * 0.95, Math.PI * 1.5, Math.PI * 0.05]) {
        const c = Math.cos(t), s = Math.sin(t);
        legs.push(seg(P(...W(d.a + (d.r + 1.2) * c, d.b + (d.r + 1.2) * s, d.z0 + 12)), P(...W(d.a + (d.r + 5) * c, d.b + (d.r + 5) * s, 0))));
      }
      lines(legs); d.el = solid(g);
    } else d.el = solid(g);
    if (d.kick) {
      // the tom mounts rise from the bass drum's shell, and two spurs hold it
      const ms = [-10, 10].map((a) => seg(P(...W(a, -4, KR + Math.sqrt(KR * KR - a * a))), P(...W(a, -4, 40))));
      d.mounts = lines(ms);
    }
  }
  const kick = DRUMS[1];
  kick.spurs = lines([-1, 1].map((s) => seg(P(...W(s * (KR - 2.5), 5, 6)), P(...W(s * (KR + 5), 12, 0)))));

  function draw(d) {
    const z = clamp(d.sp.x, 0, d.dmax);
    if (z === d.drawn) return;
    d.drawn = z;
    if (d.kick) {
      const ring = (s, r) => circ(r, 48).map((q) => P(...W(d.a + q.u, d.b + s, KR - z + q.v)));
      put(d.el, { sil: poly(hull(ring(-KL, KR).concat(ring(KL, KR)))), crease: poly(ring(KL, KR - 1.6)) });
    } else if (d.cym) {
      put(d.el, prism(P, front, disc(d, d.r, 48), disc(d, d.r - 1.2, 48), d.z0 - z, d.z1 - z));
      put(d.bell, prism(P, front, disc(d, 3.2, 24), null, d.z1 - z, d.z1 + 1.8 - z));
    } else put(d.el, prism(P, front, disc(d, d.r), disc(d, d.r - 1.2), d.z0 - z, d.z1 - z));
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const d of DRUMS) { if (stepS(d.sp, dt)) m = true; draw(d); }
    return m;
  });
  bag.add(B.unregister);

  // each drum is tested on the plane of its own resting top; the bass drum on its axis
  const zones = DRUMS.map((d) => (d.kick ? { z: KR, a: 0, b: 4, ra: KR, rb: 33 } : { z: d.z1, a: d.a, b: d.b, ra: d.r * 1.15, rb: d.r * 1.15 }));
  function under(sx, sy) {
    let best = null, bd = 1.25;
    DRUMS.forEach((d, i) => {
      const zn = zones[i], [x, y] = unproj(C, sx, sy, zn.z), a = (x - y) * Q, b = (x + y) * Q;
      const s = Math.hypot((a - zn.a) / zn.ra, (b - zn.b) / zn.rb);
      if (s < bd) { bd = s; best = d; }
    });
    return best;
  }

  function retarget() {
    for (const d of DRUMS) {
      if (!over) d.sp.t = d.rest;
      else d.sp.t = d === over ? d.dmax : d.dmax * 0.8 * falloff(Math.hypot(d.a - over.a, d.b - over.b) / RAD);
      d.el.sil.classList.toggle("hi", over ? d === over : d.name === FAV);
    }
    read.textContent = over ? over.name : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { const h = under(p[0], p[1]); if (h !== over) { over = h; retarget(); } },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "drumkit",
  means: "A drum kit with a cymbal: the drums near the pointer bounce down on springs, the one under it deepest and bright.",
  rules: [1, 3, 5, 9],
  range: [18, 34, 60],
  tour: [[133, 181], [105, 94], [294, 189], null],
  mount,
});

podcastmics.code:
/**
 * Podcast mics: a round pedestal table with three broadcast microphones, each
 * on a boom arm clamped to the table's edge, and a pair of headphones lying
 * on the top. The pointer is whoever is talking: every mic swivels and tilts
 * on its own springs to point at it, and the mic nearest it is bright. At
 * rest each mic points out at its own guest, a little askew, one bright. The
 * slider is how quickly the mics follow (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (terrain's spring, on two angles per mic); the
 * hit is on the table top's plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 40, TT = 28.5, POST = 30, MR = 24, MZ = TT + 15, LEN = 20;
const ANG = [225, 105, 345], SKEW = [14, -18, 8], TILT = [-0.12, 0.06, -0.24], FAV = 1;
const V = [0.61, 0.61, 0.5];
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.9);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([(R + 6) * Math.cos(a), (R + 6) * Math.sin(a), 0], [(R + 2) * Math.cos(a), (R + 2) * Math.sin(a), TT + POST + 2]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the table: a foot, a column and a round top
  put(solid(g), prism(P, front, circ(14, 64), circ(12.6, 64), 0, 2));
  put(solid(g), prism(P, front, circ(3.5, 24), null, 2, TT - 2.5));
  put(solid(g), prism(P, front, circ(R, 96), circ(R - 1.8, 96), TT - 2.5, TT));

  // the headphones: two cups on the top, the band standing in an arc between them
  const hx = 7, hy = 7, ax = Q2(1, -1), HW = 9.6;
  const arc = (r, h) => Array.from({ length: 17 }, (_, i) => { const t = (i / 16) * Math.PI; return P(hx + r * Math.cos(t) * ax[0], hy + r * Math.cos(t) * ax[1], TT + 3.2 + h * Math.sin(t)); });
  for (const s of [-1, 1]) put(solid(g), prism(P, front, disc(hx + s * HW * ax[0], hy + s * HW * ax[1], 4.6, 28), disc(hx + s * HW * ax[0], hy + s * HW * ax[1], 3.4, 28), TT, TT + 3.2));
  mk("path", { class: "nf sil", d: open(arc(HW, 13)) }, g);
  mk("path", { class: "nf lo", d: open(arc(HW - 1.4, 11)) }, g);

  const mics = ANG.map((deg, k) => {
    const a = (deg * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a);
    const cx = (R - 2) * c, cy = (R - 2) * s, mx = MR * c, my = MR * s;
    const rest = a + (SKEW[k] * Math.PI) / 180;
    const opts = { k: 100 * value, c: 18 * Math.sqrt(value) };
    return { k, cx, cy, mx, my, rest, yaw: spring(rest, opts), tilt: spring(TILT[k], opts), last: "" };
  }).sort((p, q) => p.cx + p.cy - (q.cx + q.cy));
  for (const m of mics) {
    const top = P(m.cx, m.cy, TT + POST), over = P(m.mx, m.my, MZ + 5);
    mk("path", { class: "nf sil", d: seg(P(m.cx, m.cy, TT), top) + seg(top, over) + seg(over, P(m.mx, m.my, MZ + 2)) }, g);
    put(solid(g), prism(P, front, disc(m.cx, m.cy, 2, 16), null, TT - 3.5, TT + 1.5));
    m.body = mk("path", { class: "sil" }, g);
    m.end = mk("path", { class: "nf lo" }, g);
  }

  function draw(m) {
    const yaw = m.yaw.x, tilt = m.tilt.x, key = yaw.toFixed(4) + "," + tilt.toFixed(4);
    if (key === m.last) return;
    m.last = key;
    const d = [Math.cos(tilt) * Math.cos(yaw), Math.cos(tilt) * Math.sin(yaw), Math.sin(tilt)];
    const u = [-Math.sin(yaw), Math.cos(yaw), 0], v = [u[1] * d[2] - u[2] * d[1], u[2] * d[0] - u[0] * d[2], u[0] * d[1] - u[1] * d[0]];
    const ring = (off, r) => Array.from({ length: 28 }, (_, i) => {
      const t = (i / 28) * Math.PI * 2, q = (j) => [m.mx, m.my, MZ][j] + d[j] * off + r * (Math.cos(t) * u[j] + Math.sin(t) * v[j]);
      return P(q(0), q(1), q(2));
    });
    const back = ring(-LEN * 0.4, 3.6), head = ring(LEN * 0.6, 5.2);
    m.body.setAttribute("d", poly(hull(back.concat(head))));
    const facingUs = d[0] * V[0] + d[1] * V[1] + d[2] * V[2] > 0;
    m.end.setAttribute("d", poly(facingUs ? ring(LEN * 0.6, 3.9) : ring(-LEN * 0.4, 2.5)));
  }

  const B = register(stage, (dt) => {
    let mv = false;
    for (const m of mics) { if (stepS(m.yaw, dt)) mv = true; if (stepS(m.tilt, dt)) mv = true; draw(m); }
    return mv;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    for (const m of mics) {
      let aim = m.rest, tilt = TILT[m.k];
      if (over) {
        const dx = over[0] - m.mx, dy = over[1] - m.my, dd = Math.hypot(dx, dy);
        if (dd < bd) { bd = dd; near = m; }
        aim = dd < 3 ? m.yaw.t : Math.atan2(dy, dx);
        tilt = clamp(Math.atan2(-6, dd), -0.6, 0);
      }
      m.yaw.t = m.yaw.t + wrap(aim - m.yaw.t);
      m.tilt.t = tilt;
    }
    for (const m of mics) m.body.classList.toggle("hi", over ? m === near : m.k === FAV);
    read.textContent = near ? "mic " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], TT), r = Math.hypot(x, y), k = Math.min(1, (R + 14) / r);
      over = r > R + 36 ? null : [x * k, y * k];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const m of mics) for (const s of [m.yaw, m.tilt]) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

function Q2(a, b) { const n = Math.hypot(a, b); return [a / n, b / n]; }

hairline({
  name: "podcastmics",
  means: "Three podcast mics on boom arms round a table: every mic turns to point at the pointer, the nearest one bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[247, 104], [150, 175], [255, 215], null],
  mount,
});

cinemaseats.code:
/**
 * Cinema seats: two rows of five folding seats on a stepped floor, the back
 * row up a riser, each seat a backrest and a seat bottom hinged between two
 * armrest standards. The pointer is someone finding a place: the seat bottoms
 * near it flip down on their own springs, the one under it fully down and
 * bright. At rest the seats stand folded, a few left part-way, one down and
 * bright. The slider is the reach.
 *
 * The pattern: a continuous field (terrain) over two rows at different
 * heights; the hit is on each row's own resting seat plane, which never moves.
 */
const {
  Cam, clamp, facing, fit, hull, poly, prism, proj, rings, rrect, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, SP = 16, RISE = 10, SH = 11, SL = 12, ST = 2.2;
const ROWS = [{ id: "B", y0: -12, zf: RISE }, { id: "A", y0: 15, zf: 0 }];
const REST = { B: [86, 90, 0, 90, 70], A: [90, 76, 90, 84, 90] }, FAV = "B3";
const X1 = N * SP;
const V = [0.61, 0.61, 0.5];
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value, over = null;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-4, -24, -3], [X1 + 4, -24, -3], [-4, 26, -3], [X1 + 4, 26, -3], [-4, -24, RISE + 30], [X1 + 4, -24, RISE + 30]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };

  // the floor: the back row's riser, then the front row's floor before it
  block(-4, -24, X1 + 4, 0, 2.5, 1.2, -3, RISE);
  block(-4, 0, X1 + 4, 26, 2.5, 1.2, -3, 0);

  const seats = [];
  for (const row of ROWS) {
    const { y0, zf } = row;
    for (let k = 0; k <= N; k++) {
      block(k * SP - 1.3, y0 - 7, k * SP + 1.3, y0 + 4, 1, 0.5, zf, zf + 14);
      if (k === N) break;
      const x0 = k * SP + 2, x1 = (k + 1) * SP - 2;
      block(x0, y0 - 7.5, x1, y0 - 4.5, 1.2, 0.6, zf + 8, zf + 29);
      const el = solid(g), rest = REST[row.id][k];
      seats.push({ id: row.id + (k + 1), k, row, x0, x1, cx: (x0 + x1) / 2, cy: y0 + 2, el, rest, sp: spring(rest, { eps: 0.05 }), drawn: NaN });
    }
  }

  function draw(s) {
    const deg = clamp(s.sp.x, 0, 90);
    if (deg === s.drawn) return;
    s.drawn = deg;
    const a = (deg * Math.PI) / 180, c = Math.cos(a), sn = Math.sin(a), yp = s.row.y0 - 3.8, zp = s.row.zf + SH;
    const ring = rrect(s.x0, 0, s.x1, SL, 1.6, 4), inner = rrect(s.x0 + 1, 1, s.x1 - 1, SL - 1, 0.8, 4);
    const at = (q, t) => P(q.u, yp + q.v * c + t * sn, zp + q.v * sn - t * c);
    const top = ring.map((q) => at(q, 0)), bot = ring.map((q) => at(q, ST));
    // the face turned to the viewer gets the crease: the top when down, the underside when folded
    const upFace = -V[1] * sn + V[2] * c > 0;
    put(s.el, { sil: poly(hull(top.concat(bot))), crease: poly(inner.map((q) => at(q, upFace ? 0 : ST))) });
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const s of seats) { if (stepS(s.sp, dt)) m = true; draw(s); }
    return m;
  });
  bag.add(B.unregister);

  // each row is tested on its own seat plane at rest; the nearer row's middle wins
  function under(sx, sy) {
    let best = null, bd = 1;
    for (const row of ROWS) {
      const [x, y] = unproj(C, sx, sy, row.zf + SH), d = Math.abs(y - (row.y0 + 1)) / 10;
      if (x < -3 || x > X1 + 3 || d >= bd) continue;
      bd = d; best = seats.find((s) => s.row === row && s.k === clamp(Math.floor(x / SP), 0, N - 1));
    }
    return best;
  }

  function retarget() {
    for (const s of seats) {
      if (!over) s.sp.t = s.rest;
      else s.sp.t = s === over ? 0 : 90 - 90 * 0.8 * falloff(Math.hypot(s.cx - over.cx, s.cy - over.cy) / RAD);
      s.el.sil.classList.toggle("hi", over ? s === over : s.id === FAV);
    }
    read.textContent = over ? "seat " + over.id : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { const h = under(p[0], p[1]); if (h !== over) { over = h; retarget(); } },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "cinemaseats",
  means: "Two rows of folding cinema seats on a stepped floor: seats near the pointer flip down, the one under it fully down.",
  rules: [1, 3, 5, 6],
  range: [20, 40, 64],
  tour: [[164, 125], [172, 198], [228, 225], null],
  mount,
});

cameratripod.code:
/**
 * Camera tripod: a camera body with a lens barrel on a pan head, over a
 * centre column and three splayed legs, a pan handle out the back. The pointer
 * is the subject: the camera pans and tilts to aim at it, each on its own
 * spring, and the lens racks out the farther away it is. At rest the camera
 * looks off to the right, lens half out and bright. The slider is how quickly
 * it follows (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (terrain's spring, on yaw, pitch and zoom);
 * the hit is on the floor's plane, which never moves.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rad, rrect, seg, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const HZ = 62, APEX = 42, FOOT = 30, BD = 6, BW = 11, BH = 7.5, LR = 4.6;
const REST = { yaw: rad(-25), pitch: rad(-6), zoom: 1.6 };
const VIEW = [0.612, 0.612, 0.5];
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));
const lensLen = (z) => 4 + 7 * z;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.0);
  const ext = [];
  for (let k = 0; k < 3; k++) { const a = rad(105 + k * 120); ext.push([FOOT * Math.cos(a), FOOT * Math.sin(a), 0]); }
  for (let k = 0; k < 8; k++) for (const p of [rad(-24), rad(5)]) { const a = (k / 8) * Math.PI * 2, R = BD + lensLen(3) + 2; ext.push([R * Math.cos(a) * Math.cos(p), R * Math.sin(a) * Math.cos(p), HZ + R * Math.sin(p)]); }
  ext.push([0, 0, HZ + BH + 2]);
  fit(C, ext, 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const legs = [];
  for (let k = 0; k < 3; k++) {
    const a = rad(105 + k * 120), cx = Math.cos(a), cy = Math.sin(a);
    legs.push(seg(P(cx * 3, cy * 3, APEX), P(cx * FOOT, cy * FOOT, 0.8)), seg(P(cx * 3, cy * 3, APEX - 3), P(cx * (FOOT - 1.6), cy * (FOOT - 1.6), 0.8)));
    place(flatDot(g, C, 1.3, "dot off"), P(cx * FOOT, cy * FOOT, 0));
  }
  mk("path", { class: "nf sil", d: legs.join("") }, g);
  put(solid(g), prism(P, front, circ(4.5, 32), circ(3.6, 32), APEX - 3, APEX));
  put(solid(g), prism(P, front, circ(2, 16), null, APEX, HZ - 12));
  put(solid(g), prism(P, front, circ(5.5, 32), circ(4.6, 32), HZ - 12, HZ - BH - 1));
  const rig = mk("g", {}, g);
  const handle = mk("path", { class: "nf sil" }, rig), body = solid(rig);
  const lens = mk("path", { class: "sil hi" }, rig), rim = mk("path", { class: "nf" }, rig);

  const opts = { k: 100 * value, c: 18 * Math.sqrt(value) };
  const S = { yaw: spring(REST.yaw, opts), pitch: spring(REST.pitch, opts), zoom: spring(REST.zoom, opts) };
  let lastKey = "", toward = null;
  const FACE = rrect(-BW, -BH, BW, BH, 2.5, 4), FACEI = rrect(-BW + 1.2, -BH + 1.2, BW - 1.2, BH - 1.2, 1.5, 4);

  function draw() {
    const key = S.yaw.x.toFixed(4) + S.pitch.x.toFixed(4) + S.zoom.x.toFixed(3);
    if (key === lastKey) return;
    lastKey = key;
    const cy = Math.cos(S.yaw.x), sy = Math.sin(S.yaw.x), cp = Math.cos(S.pitch.x), sp = Math.sin(S.pitch.x);
    const d = [cp * cy, cp * sy, sp], u = [sy, -cy, 0], v = [-sp * cy, -sp * sy, cp];
    const at = (off, a, b) => P(...[0, 1, 2].map((j) => [0, 0, HZ][j] + d[j] * off + a * u[j] + b * v[j]));
    const face = (ring, off) => ring.map((q) => at(off, q.u, q.v));
    const circle = (off, r) => Array.from({ length: 28 }, (_, i) => { const t = (i / 28) * Math.PI * 2; return at(off, r * Math.cos(t), r * Math.sin(t)); });
    const fwd = d[0] * VIEW[0] + d[1] * VIEW[1] + d[2] * VIEW[2] > 0;
    body.sil.setAttribute("d", poly(hull(face(FACE, -BD).concat(face(FACE, BD)))));
    body.cr.setAttribute("d", poly(face(FACEI, fwd ? BD : -BD)));
    body.sil.classList.toggle("hi", !fwd);
    const L = lensLen(S.zoom.x), end = circle(BD + L, LR + 0.8);
    lens.setAttribute("d", poly(hull(circle(BD, LR).concat(end))));
    rim.setAttribute("d", fwd ? poly(end) + poly(circle(BD + L - 0.01, LR - 0.6)) : "");
    handle.setAttribute("d", seg(P(0, 0, HZ - BH - 1), P(-cy * 26, -sy * 26, HZ - BH - 8)));
    if (fwd !== toward) {
      toward = fwd;
      if (fwd) rig.append(handle, body.g, lens, rim); else rig.append(rim, lens, body.g, handle);
    }
  }

  const B = register(stage, (dt) => {
    const a = stepS(S.yaw, dt), b = stepS(S.pitch, dt), c = stepS(S.zoom, dt);
    draw();
    return a || b || c;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    if (over) {
      const r = Math.hypot(over[0], over[1]);
      if (r > 4) S.yaw.t = S.yaw.t + wrap(Math.atan2(over[1], over[0]) - S.yaw.t);
      S.pitch.t = clamp(Math.atan2(-HZ * 0.3, r), rad(-24), rad(5));
      S.zoom.t = clamp(1 + (r - 20) / 30, 1, 3);
    } else {
      S.yaw.t = S.yaw.t + wrap(REST.yaw - S.yaw.t);
      S.pitch.t = REST.pitch; S.zoom.t = REST.zoom;
    }
    read.textContent = over ? "zoom " + Math.round(S.zoom.t * 2) / 2 + "×" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y), k = Math.min(1, 80 / r);
      over = r > 110 ? null : [x * k, y * k];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const s of Object.values(S)) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "cameratripod",
  means: "A camera on a tripod: it pans and tilts to aim at the pointer, and its lens zooms out the farther the pointer is.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[290, 300], [110, 270], [250, 150], null],
  mount,
});

satellitedishes.code:
/**
 * Satellite dishes: three dishes of different sizes on a roof slab, each a
 * shallow bowl on a post with a feed arm held out in front of it. The pointer
 * is the satellite: every dish turns on its own spring to face it, and the
 * dish nearest it is bright. At rest they all face one point of the sky, each
 * a little off, the middle one bright. The slider is how quickly they follow.
 *
 * The pattern: a continuous aim (terrain's spring, on an angle per dish); the
 * hit is on the roof's plane, which never moves.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const SX = 50, SY = 36, FAV = 1;
const DISH = [
  { x: -30, y: -16, R: 13, h: 26, tilt: 40, rest: 160 },
  { x: 18, y: -20, R: 18, h: 32, tilt: 36, rest: 150 },
  { x: -4, y: 22, R: 9, h: 18, tilt: 44, rest: 172 },
];
const VIEW = [0.612, 0.612, 0.5];
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-SX, -SY, -6], [SX, SY, -6], [SX, -SY, -6], [-SX, SY, -6], [-30, -16, 48], [18, -20, 58]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-SX, -SY, SX, SY, 4, 1.6);
  put(solid(g), prism(P, front, sr, si, -6, 0));

  const dishes = DISH.map((o, k) => ({ ...o, k, c: [o.x, o.y, o.h], rest: (o.rest * Math.PI) / 180, tilt: (o.tilt * Math.PI) / 180 }))
    .sort((a, b) => a.x + a.y - (b.x + b.y));
  for (const d of dishes) {
    const grp = mk("g", {}, g);
    const [pr, pi] = rings(d.x - 5, d.y - 5, d.x + 5, d.y + 5, 2, 0.8);
    put(solid(grp), prism(P, front, pr, pi, 0, 2));
    place(flatDot(grp, C, 0.9, "dot off"), P(d.x + 3, d.y + 3, 2));
    d.post = solid(grp);
    put(d.post, prism(P, front, disc(d.x, d.y, 1.4, 16), null, 2, d.h - 2));
    d.aim = mk("g", {}, grp);
    d.arm = mk("path", { class: "nf sil" }, d.aim);
    d.bowl = mk("path", { class: "sil" }, d.aim);
    d.rim = mk("path", { class: "nf" }, d.aim);
    d.feed = mk("circle", { r: 1.4, class: "dot m" }, d.aim);
    d.sp = spring(d.rest, { k: 100 * value, c: 18 * Math.sqrt(value) });
    d.drawn = NaN; d.toward = null;
  }

  function draw(d) {
    const yaw = d.sp.x;
    if (Math.abs(yaw - d.drawn) < 1e-4) return;
    d.drawn = yaw;
    const ct = Math.cos(d.tilt), st = Math.sin(d.tilt);
    const n = [ct * Math.cos(yaw), ct * Math.sin(yaw), st];
    const u = [-Math.sin(yaw), Math.cos(yaw), 0], v = [-st * Math.cos(yaw), -st * Math.sin(yaw), ct];
    const ring = (off, r) => Array.from({ length: 32 }, (_, i) => {
      const t = (i / 32) * Math.PI * 2, q = (j) => d.c[j] + n[j] * off + r * (Math.cos(t) * u[j] + Math.sin(t) * v[j]);
      return P(q(0), q(1), q(2));
    });
    const back = ring(0, d.R * 0.3), rim = ring(d.R * 0.32, d.R);
    const fp = (j) => d.c[j] + n[j] * d.R * 0.95;
    const feed = P(fp(0), fp(1), fp(2));
    d.bowl.setAttribute("d", poly(hull(back.concat(rim))));
    const toward = n[0] * VIEW[0] + n[1] * VIEW[1] + n[2] * VIEW[2] > 0;
    d.rim.setAttribute("d", poly(toward ? rim : back));
    d.rim.setAttribute("class", toward ? (d.on ? "nf hi" : "nf") : "nf lo");
    const r0 = (s) => P(d.c[0] + n[0] * d.R * 0.32 + s * d.R * 0.92 * v[0], d.c[1] + n[1] * d.R * 0.32 + s * d.R * 0.92 * v[1], d.c[2] + n[2] * d.R * 0.32 + s * d.R * 0.92 * v[2]);
    d.arm.setAttribute("d", seg(r0(-1), feed) + seg(r0(1), feed));
    place(d.feed, feed);
    if (toward !== d.toward) {
      d.toward = toward;
      if (toward) d.aim.append(d.bowl, d.rim, d.arm, d.feed); else d.aim.append(d.arm, d.feed, d.bowl, d.rim);
    }
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const d of dishes) { if (stepS(d.sp, dt)) m = true; draw(d); }
    return m;
  });
  bag.add(B.unregister);

  let over = null, scr = null;
  function retarget() {
    let near = null, bd = Infinity;
    for (const d of dishes) {
      if (over) {
        const [hx, hy] = unproj(C, scr[0], scr[1], d.h), dist = Math.min(Math.hypot(over[0] - d.x, over[1] - d.y), Math.hypot(hx - d.x, hy - d.y));
        if (dist < bd) { bd = dist; near = d; }
        const aim = Math.hypot(over[0] - d.x, over[1] - d.y) < 4 ? d.sp.t : Math.atan2(over[1] - d.y, over[0] - d.x);
        d.sp.t = d.sp.t + wrap(aim - d.sp.t);
      } else d.sp.t = d.sp.t + wrap(d.rest - d.sp.t);
    }
    for (const d of dishes) { const on = over ? d === near : d.k === FAV; d.bowl.classList.toggle("hi", on); if (d.on !== on) { d.on = on; d.drawn = NaN; draw(d); } }
    read.textContent = near ? "dish " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0); scr = p;
      over = Math.abs(x) > SX + 30 || Math.abs(y) > SY + 30 ? null : [Math.max(-SX, Math.min(SX, x)), Math.max(-SY, Math.min(SY, y))];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const d of dishes) { d.sp.k = 100 * v; d.sp.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "satellitedishes",
  means: "Three satellite dishes on a roof: every dish turns to face the pointer, and the nearest one is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[177, 104], [262, 128], [157, 172], null],
  mount,
});

batterybank.code:
/**
 * Battery bank: a rack of six tall cells on a base plate, each with two
 * terminals on its lid, strapped in series, and a charge line round its
 * walls. The pointer charges: the levels near it rise, each on its own
 * spring, the cell under it full and bright. At rest the levels are uneven,
 * the fullest cell bright. The slider is the reach, in cells.
 *
 * The pattern: a continuous field (terrain) along one row; the hit picks the
 * cell whose rest centre is nearest the pointer's screen x.
 */
const {
  Cam, circ, clamp, facing, fit, lerp, open, prism, proj, rings, ringAt, run, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, PITCH = 15, W = 12, D = 16, H = 44, TOP = 47.5, Z0 = 4, Z1 = 40;
const REST = [0.14, 0.42, 0.72, 0.3, 0.52, 0.08], FAV = 2;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value, over = null;
  const X1 = (N - 1) * PITCH + W;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-5, -5, -5], [X1 + 5, D + 5, -5], [X1 + 5, -5, -5], [-5, D + 5, -5], [-5, -5, TOP], [X1 + 5, D + 5, TOP]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-5, -5, X1 + 5, D + 5, 3, 1.2);
  put(solid(g), prism(P, front, br, bi, -5, 0));

  const cells = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * PITCH, cx = x0 + W / 2, el = solid(g);
    const [ring, inner] = rings(x0, 0, x0 + W, D, 2.5, 1.2);
    put(el, prism(P, front, ring, inner, 0, H));
    const bars = mk("path", { class: "nf lo" }, el.g), lvl = mk("path", { class: "nf" }, el.g);
    for (const ty of [4, 12]) put(solid(el.g), prism(P, front, disc(cx, ty, 1.9), disc(cx, ty, 1.1), H, TOP));
    if (k > 0) mk("path", { class: "nf sil", d: seg(P(cx - PITCH, 12, TOP), P(cx, 4, TOP)) }, el.g);
    const vis = run(ring, front);
    cells.push({ k, cx, el, lvl, bars, vis, sx: P(cx, D / 2, H / 2)[0], rest: REST[k], sp: spring(REST[k], { eps: 0.004 }), drawn: NaN });
  }
  const box = [P(-5, D + 5, -5), P(X1 + 5, -5, TOP), P(-5, -5, TOP), P(X1 + 5, D + 5, -5)];
  const bx = [Math.min(...box.map((p) => p[0])), Math.max(...box.map((p) => p[0]))];
  const by = [Math.min(...box.map((p) => p[1])), Math.max(...box.map((p) => p[1]))];

  function draw(c) {
    const v = clamp(c.sp.x, 0, 1);
    if (Math.abs(v - c.drawn) < 1e-3) return;
    c.drawn = v;
    const z = lerp(Z0, Z1, v);
    c.lvl.setAttribute("d", open(ringAt(P, c.vis, z)));
    let d = "";
    for (let b = Z0; b < z - 2.5; b += 4) d += open(ringAt(P, c.vis, b));
    c.bars.setAttribute("d", d);
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const c of cells) { if (stepS(c.sp, dt)) m = true; draw(c); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    let hit = null;
    if (over != null) { let bd = Infinity; for (const c of cells) { const d = Math.abs(c.sx - over); if (d < bd) { bd = d; hit = c; } } }
    for (const c of cells) {
      c.sp.t = !hit ? c.rest : c === hit ? 1 : lerp(c.rest, 1, 0.85 * falloff(Math.abs(c.k - hit.k) / RAD));
      const on = hit ? c === hit : c.k === FAV;
      c.el.sil.classList.toggle("hi", on);
      c.lvl.setAttribute("class", on ? "nf hi" : "nf");
    }
    read.textContent = hit ? "cell " + (hit.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      over = p[0] > bx[0] - 8 && p[0] < bx[1] + 8 && p[1] > by[0] - 10 && p[1] < by[1] + 10 ? p[0] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "batterybank",
  means: "A rack of six battery cells: the charge levels near the pointer rise, the cell under it full and bright.",
  rules: [1, 3, 5, 9],
  range: [1, 2, 3.5],
  tour: [[168, 104], [212, 126], [246, 152], null],
  mount,
});

bowlingpins.code:
/**
 * Bowling pins: the ten pins in their triangle on the end of a lane, a ball
 * resting in front of them. The pointer is a near miss: the pins near it tilt
 * away from it, each on its own spring, the one under it most and bright. At
 * rest the head pin wobbles back, bright. The slider is the reach.
 *
 * The pattern: a continuous field (terrain) over a triangle of parts; the hit
 * is on a fixed plane through the pins' bellies, which never moves.
 */
const {
  Cam, clamp, fit, facing, open, poly, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SP = 12, ROW = 10.4, TMAX = 0.5, HZ = 6, BR = 4.3, BALL = [20, 9], X0 = -38, X1 = 30, YW = 22;
// the pin's profile, [height, radius]: foot, belly, neck, head
const PRO = [[0, 1.1], [1.5, 1.8], [3, 2.3], [4.8, 2.45], [6.6, 2.25], [8.5, 1.6], [10, 0.95], [11, 0.9], [12.2, 1.2], [13.3, 1.25], [14.3, 0.95], [15, 0.25]];
const REST = { 1: [-0.24, 0.04], 2: [-0.07, -0.06], 3: [-0.07, 0.06] }, FAV = 1;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.42 ? 1 - (u / 0.42) * 0.69 : u <= 1 ? 0.31 - ((u - 0.42) / 0.58) * 0.31 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value, over = null;
  const C = Cam(45, 0.5, 3.2);
  fit(C, [[X0, -YW, -3], [X1, YW, -3], [X1, -YW, -3], [X0, YW, -3], [-3 * ROW - 6, -20, 17], [-3 * ROW - 6, 20, 17]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the lane's end: a slab, its gutter edges and the deck's board line
  const [lr, li] = rings(X0, -YW, X1, YW, 3, 1.4);
  const lane = solid(g);
  put(lane, prism(P, front, lr, li, -3, 0));
  mk("path", { class: "nf lo", d: open([P(X0 + 3, -17, 0), P(X1 - 3, -17, 0)]) + open([P(X0 + 3, 17, 0), P(X1 - 3, 17, 0)]) + open([P(9, -17, 0), P(9, 17, 0)]) }, lane.g);

  // pins and ball, painted far to near by x + y
  const parts = [];
  for (let r = 0; r < 4; r++) for (let j = 0; j <= r; j++) {
    const n = (r * (r + 1)) / 2 + j + 1, rs = REST[n] || [0, 0];
    parts.push({ n, x: -r * ROW, y: (j - r / 2) * SP, rest: rs, tx: spring(rs[0], { eps: 0.002 }), ty: spring(rs[1], { eps: 0.002 }), last: "" });
  }
  parts.push({ ball: true, x: BALL[0], y: BALL[1] });
  parts.sort((a, b) => a.x + a.y - (b.x + b.y));
  for (const p of parts) {
    p.grp = mk("g", {}, g);
    p.sil = mk("path", { class: "sil" }, p.grp);
    p.cr = mk("path", { class: "nf lo" }, p.grp);
  }
  const pins = parts.filter((p) => !p.ball).sort((a, b) => a.n - b.n);
  const ball = parts.find((p) => p.ball);
  { // the ball: a disc on screen, with its three finger holes turned toward us
    const [cx, cy] = P(ball.x, ball.y, BR), R = BR * C.S, pts = [];
    for (let i = 0; i < 48; i++) { const a = (i / 48) * Math.PI * 2; pts.push([cx + R * Math.cos(a), cy + R * Math.sin(a)]); }
    ball.sil.setAttribute("d", poly(pts));
    const hole = (u, v, s) => { const q = []; for (let i = 0; i < 14; i++) { const a = (i / 14) * Math.PI * 2; q.push([cx + R * (u + s * Math.cos(a)), cy + R * (v + s * 0.7 * Math.sin(a))]); } return poly(q); };
    ball.cr.setAttribute("d", hole(-0.32, -0.38, 0.11) + hole(0.02, -0.5, 0.11) + hole(-0.08, 0.02, 0.13));
  }

  /** A pin's rings, tipped by the tilt (tx, ty) about the edge of its foot. */
  function ringsOf(p, tx, ty) {
    const th = Math.hypot(tx, ty), dx = th ? tx / th : -1, dy = th ? ty / th : 0, c = Math.cos(th), s = Math.sin(th);
    return PRO.map(([z, r]) => Array.from({ length: 24 }, (_, i) => {
      const t = (i / 24) * Math.PI * 2, u = r * Math.cos(t), v = r * Math.sin(t), a = u * dx + v * dy - 1.1;
      const a2 = a * c + z * s, z2 = -a * s + z * c;
      return P(p.x + u + (a2 - a) * dx, p.y + v + (a2 - a) * dy, z2);
    }));
  }
  /** The near half of a projected ring: the arc between its left and right ends that lies lower on screen. */
  function nearArc(ring) {
    const n = ring.length; let lo = 0, hi = 0;
    ring.forEach((q, i) => { if (q[0] < ring[lo][0]) lo = i; if (q[0] > ring[hi][0]) hi = i; });
    const arc = (a, b) => { const o = []; for (let i = a; ; i = (i + 1) % n) { o.push(ring[i]); if (i === b) break; } return o; };
    const A = arc(lo, hi), Bk = arc(hi, lo), mean = (q) => q.reduce((m, p) => m + p[1], 0) / q.length;
    return mean(A) > mean(Bk) ? A : Bk.reverse();
  }
  function draw(p) {
    const tx = p.tx.x, ty = p.ty.x, key = tx.toFixed(4) + ty.toFixed(4);
    if (key === p.last) return;
    p.last = key;
    const R = ringsOf(p, tx, ty), side = (f) => R.map((ring) => ring.reduce((b, q) => (f(q[0], b[0]) ? q : b)));
    const right = side((a, b) => a > b), left = side((a, b) => a < b);
    p.sil.setAttribute("d", poly(nearArc(R[0]).concat(right.slice(1), left.slice(1).reverse())));
    p.cr.setAttribute("d", open(nearArc(R[6])));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const p of pins) { if (stepS(p.tx, dt)) m = true; if (stepS(p.ty, dt)) m = true; draw(p); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    let hit = null, bd = 6.5;
    if (over) for (const p of pins) { const d = Math.hypot(p.x - over[0], p.y - over[1]); if (d < bd) { bd = d; hit = p; } }
    for (const p of pins) {
      let t = p.rest;
      if (over) {
        const ex = p.x - over[0], ey = p.y - over[1], d = Math.hypot(ex, ey), a = p === hit ? TMAX : TMAX * 0.75 * falloff(d / RAD);
        t = d > 0.6 ? [(a * ex) / d, (a * ey) / d] : [-a, 0];
      }
      p.tx.t = clamp(t[0], -TMAX, TMAX); p.ty.t = clamp(t[1], -TMAX, TMAX);
      p.sil.classList.toggle("hi", over ? p === hit : p.n === FAV);
    }
    read.textContent = hit ? "pin " + hit.n : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (q) => {
      const [x, y] = unproj(C, q[0], q[1], HZ);
      over = x > -3 * ROW - 10 && x < 12 && y > -YW - 2 && y < YW + 2 ? [x, y] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "bowlingpins",
  means: "Ten bowling pins on the lane's end: the pins near the pointer tilt away from it, the one under it most.",
  rules: [1, 3, 5, 9],
  range: [12, 22, 36],
  tour: [[209, 176], [179, 120], [98, 161], null],
  mount,
});

trophyshelf.code:
/**
 * Trophy shelf: a two-tier stand holding five trophies of different heights,
 * three cups with handles, a star on a column and a plain plaque. The pointer
 * picks a trophy by where it stands: it lifts off its tier and turns a little,
 * and its neighbours lift slightly, staggered from it. At rest the trophies
 * stand askew, the star raised a touch and bright. The slider is the stagger.
 *
 * The pattern: one of many at different heights (riffle, stepped): the hit
 * reads each trophy's rest centre on screen, never the pose drawn.
 */
const {
  Cam, circ, fit, facing, fillet, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const XL = 88, BT = 16, FT = 7, LIFT = 9, TURN = 0.55, FAV = 2;
// x, tier (0 back, 1 front), kind, size, rest turn
const SPEC = [[11, 0, "cup", 1, -0.25], [42, 1, "plaque", 1, 0.12], [41, 0, "star", 1, 0.1], [74, 1, "cup", 1.2, 0.3], [73, 0, "cup", 0.8, -0.15]];
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const turn = (ring, a, cx, cy) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-4, -4, 0], [XL, 31, 0], [XL, -4, 0], [-4, 31, 0], [41, 4, BT + 29 + LIFT], [73, 4, BT + 14 + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (el, x0, y0, x1, y1, r, b, z0, z1, a = 0, cx = 0, cy = 0) => {
    const [o, i] = rings(x0, y0, x1, y1, r, b);
    put(el, prism(P, front, turn(o, a, cx, cy), turn(i, a, cx, cy), z0, z1));
    return el;
  };

  // the back tier, its trophies, then the front tier and its trophies
  const items = SPEC.map(([x, tier, kind, s, rt], k) => ({ k, x, y: tier ? 21 : 4, z0: tier ? FT : BT, tier, kind, s, rt }));
  for (const tier of [0, 1]) {
    block(solid(g), -4, tier ? 12 : -4, XL, tier ? 31 : 12, 2.5, 1.2, 0, tier ? FT : BT);
    for (const it of items.filter((q) => q.tier === tier)) {
      it.grp = mk("g", {}, g);
      it.a = tween(it.k === FAV ? 0.35 : 0);
      it.last = NaN;
    }
  }

  /** One trophy at its lift and turn: replaces the group's paths. */
  function draw(it, amt) {
    if (amt === it.last) return;
    it.last = amt;
    it.grp.replaceChildren();
    const { x, y, s } = it, z = it.z0 + amt * LIFT, a = it.rt + amt * TURN, sils = [];
    const box = (hw, hd, z0, z1) => sils.push(block(solid(it.grp), -hw, -hd, hw, hd, 1.2, 0.6, z0, z1, a, x, y).sil);
    const ax = (u, v, h) => P(x + u * Math.cos(a) - v * Math.sin(a), y + u * Math.sin(a) + v * Math.cos(a), h);
    if (it.kind === "cup") {
      box(5 * s, 5 * s, z, z + 3 * s);
      const st = solid(it.grp);
      put(st, prism(P, front, disc(x, y, 1.3 * s, 16), disc(x, y, 0.7 * s, 16), z + 3 * s, z + 7 * s));
      const zb = z + 7 * s, H = 9 * s, R = 6.2 * s, handle = mk("path", { class: "sil nf" }, it.grp);
      let d = "";
      for (const side of [1, -1]) {
        const pts = [];
        for (let i = 0; i <= 10; i++) { const t = -Math.PI / 2 + (i / 10) * Math.PI; pts.push(ax(side * (R * 0.8 + 3 * s * Math.cos(t)), 0, zb + H * 0.55 + 2.8 * s * Math.sin(t))); }
        d += "M" + pts.map((p) => p.join(",")).join("L");
      }
      handle.setAttribute("d", d);
      const bowl = [];
      for (const [f, r] of [[0, 0.3], [0.25, 0.62], [0.55, 0.86], [0.8, 0.97], [1, 1]]) bowl.push(...ringAt(P, disc(x, y, R * r), zb + H * f));
      const cup = mk("g", {}, it.grp);
      sils.push(st.sil, handle, mk("path", { class: "sil", d: poly(hull(bowl)) }, cup));
      mk("path", { class: "nf lo", d: poly(ringAt(P, disc(x, y, R - 1, 32), zb + H)) }, cup);
    } else if (it.kind === "star") {
      box(5, 5, z, z + 3);
      const st = solid(it.grp);
      put(st, prism(P, front, disc(x, y, 1.6, 16), disc(x, y, 0.9, 16), z + 3, z + 13));
      sils.push(st.sil);
      const zc = z + 20.5, pts = [];
      for (let i = 0; i < 10; i++) { const t = Math.PI / 2 + (i / 10) * Math.PI * 2, r = i % 2 ? 3.4 : 8; pts.push([r * Math.cos(t), r * Math.sin(t)]); }
      const star = fillet(pts, pts.map(() => 0.7), 3), e = a - Math.PI / 4;
      const at = (dn) => star.map(([u, v]) => P(x + u * Math.cos(e) + dn * Math.sin(e), y + u * Math.sin(e) - dn * Math.cos(e), zc + v));
      mk("path", { d: poly(at(1.6)) }, it.grp);
      sils.push(mk("path", { class: "sil", d: poly(at(0)) }, it.grp));
    } else {
      box(9, 3.2, z, z + 3);
      box(7.5, 1.3, z + 3, z + 22);
      mk("path", { class: "nf lo", d: poly([ax(-4.5, 1.3, z + 9), ax(4.5, 1.3, z + 9), ax(4.5, 1.3, z + 17), ax(-4.5, 1.3, z + 17)]) }, it.grp);
    }
    it.sils = sils;
    for (const el of sils) el.classList.toggle("hi", it.k === lit);
  }

  let lit = FAV;
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // the hit: each trophy's rest box on screen, centred on its middle
  const mids = items.map((it) => { const h = it.kind === "star" ? 28 : it.kind === "plaque" ? 25 : 16 * it.s; return { m: P(it.x, it.y, it.z0 + h / 2), hh: (h * 0.87 * C.S) / 2 + 4 }; });
  function hit([sx, sy]) {
    let best = -1, bd = 1;
    mids.forEach(({ m, hh }, k) => { const d = Math.max(Math.abs(sx - m[0]) / 17, Math.abs(sy - m[1]) / hh); if (d < bd) { bd = d; best = k; } });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    lit = a < 0 ? FAV : a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), v = a < 0 ? (k === FAV ? 0.35 : 0) : dd === 0 ? 1 : dd === 1 ? 0.28 : 0;
      tset(it.a, v, now, from < 0 ? 0 : dd * stag);
      it.last = NaN;
    });
    read.textContent = a < 0 ? "rest" : "trophy " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "trophyshelf",
  means: "Five trophies on a two-tier stand: the one under the pointer lifts and turns, its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[160, 111], [216, 125], [245, 200], null],
  mount,
});

trafficcones.code:
/**
 * Traffic cones: six cones on square feet, each with a reflective band, set
 * round a small roadwork barrier on a patch of road. The pointer startles
 * them: the cones near it hop up, each on its own spring, the one under it
 * highest and bright. At rest the cones stand loosely round the barrier, one
 * just off the ground and bright. The slider is the reach.
 *
 * The pattern: a continuous field (terrain) over scattered parts; the hit is
 * on a fixed plane through the cones' middles, which never moves.
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const HOP = 18, HZ = 9, CH = 19, FAV = 3;
// cone feet, numbered left to right on screen
const AT = [[-16, 20], [-34, -2], [12, 22], [-10, -22], [32, 4], [14, -20]];
const REST = [0, 0, 0, 3.5, 0, 0];
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const falloff = (u) => (u <= 0 ? 1 : u <= 0.42 ? 1 - (u / 0.42) * 0.69 : u <= 1 ? 0.31 - ((u - 0.42) / 0.58) * 0.31 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value, over = null;
  const C = Cam(45, 0.5, 2.7);
  fit(C, [[-42, -30, -2], [40, 30, -2], [40, -30, -2], [-42, 30, -2], [-10, -22, CH + HOP], [14, -20, CH + HOP], [-34, -2, CH + HOP]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1, el = solid(g)) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(el, prism(P, front, o, i, z0, z1)); return el; };

  // the road patch, with a lane line across it
  const road = block(-42, -30, 40, 30, 4, 1.6, -2, 0);
  mk("path", { class: "nf lo", d: open([P(-38, 12, 0), P(-26, 12, 0)]) + open([P(-14, 12, 0), P(-2, 12, 0)]) + open([P(10, 12, 0), P(22, 12, 0)]) }, road.g);

  // cones and barrier, painted far to near by x + y
  const parts = AT.map(([x, y], k) => ({ k, x, y, key: x + y }));
  parts.push({ bar: true, key: 0 });
  parts.sort((a, b) => a.key - b.key);
  const cones = [];
  for (const p of parts) {
    if (p.bar) {
      for (const x of [-15, 15]) block(x - 2.2, -6, x + 2.2, 6, 1, 0.6, 0, 2);
      for (const x of [-15, 15]) block(x - 1, -1, x + 1, 1, 0.5, 0.3, 2, 11);
      const board = block(-21, -1.4, 21, 1.4, 1.2, 0.6, 10, 17);
      let d = "";
      for (let u = -16; u <= 16; u += 8) d += open([P(u - 2.5, 1.4, 10.8), P(u + 2.5, 1.4, 16.2)]);
      mk("path", { class: "nf lo", d }, board.g);
      continue;
    }
    p.foot = solid(g);
    p.body = mk("path", { class: "sil" }, p.foot.g);
    p.band = mk("path", { class: "nf lo" }, p.foot.g);
    p.sp = spring(REST[p.k], { eps: 0.02 });
    p.drawn = NaN;
    cones.push(p);
  }
  cones.sort((a, b) => a.k - b.k);

  function draw(c) {
    const h = clamp(c.sp.x, -2, HOP + 2);
    if (h === c.drawn) return;
    c.drawn = h;
    const [o, i] = rings(c.x - 6, c.y - 6, c.x + 6, c.y + 6, 1.6, 0.8);
    put(c.foot, prism(P, front, o, i, h, h + 1.6));
    const z0 = h + 1.6, rr = (z) => 5 - ((z - z0) / (CH - 1.6)) * 3.9;
    c.body.setAttribute("d", poly(hull(ringAt(P, disc(c.x, c.y, 5), z0).concat(ringAt(P, disc(c.x, c.y, 1.1, 16), h + CH)))));
    const arc = (z) => open(ringAt(P, run(disc(c.x, c.y, rr(z), 40), front), z));
    c.band.setAttribute("d", arc(h + 8) + arc(h + 12));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const c of cones) { if (stepS(c.sp, dt)) m = true; draw(c); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    let hit = null, bd = 7.5;
    if (over) for (const c of cones) { const d = Math.hypot(c.x - over[0], c.y - over[1]); if (d < bd) { bd = d; hit = c; } }
    for (const c of cones) {
      c.sp.t = !over ? REST[c.k] : c === hit ? HOP : HOP * 0.8 * falloff(Math.hypot(c.x - over[0], c.y - over[1]) / RAD);
      c.body.classList.toggle("hi", over ? c === hit : c.k === FAV);
    }
    read.textContent = hit ? "cone " + (hit.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (q) => {
      const [x, y] = unproj(C, q[0], q[1], HZ);
      over = x > -46 && x < 44 && y > -34 && y < 34 ? [x, y] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "trafficcones",
  means: "Six traffic cones round a roadwork barrier: the cones near the pointer hop up, the one under it highest.",
  rules: [1, 3, 5, 9],
  range: [16, 36, 50],
  tour: [[141, 129], [225, 133], [255, 198], null],
  mount,
});

medicinecabinet.code:
/**
 * Medicine cabinet: a wall cabinet with its door swung open on the left, a
 * mirror panel on the door's inside, and two shelves holding eight bottles
 * and boxes. The pointer picks an item by where it rests: that one slides
 * forward off its shelf toward the reader, the items beside it ease out a
 * little, staggered from it. At rest one bottle stands pulled forward, bright.
 * The slider is the stagger.
 *
 * The pattern: a grid on a face plane (depositboxes); the hit is the nearest
 * resting middle, so a sliding item never takes the pointer with it.
 */
const {
  Cam, circ, facing, fillet, fit, hull, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 20, SH = [31, 0], TOPZ = 60, YC = 10, OUT = 19, LIFT = 3, FAV = 6, OPEN = 14 * (Math.PI / 180);
const XC = [10, 25, 40, 54];
// row (0 the top shelf), column, bottle or box, half-width, half-depth, height
const IT = [
  [0, 0, 0, 5.5, 4, 14], [0, 1, 1, 4.5, 0, 21], [0, 2, 1, 3.5, 0, 15], [0, 3, 0, 6, 5, 19],
  [1, 0, 1, 5, 0, 23], [1, 1, 0, 6, 4.5, 16], [1, 2, 1, 4, 0, 19], [1, 3, 0, 5, 4, 24],
];
const REST = [1, 0, 2, 0, 0, 1.5, 5, 0.5];
const disc = (x, y, r) => circ(r, 28).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.55);
  const dx = -Math.sin(OPEN), dy = Math.cos(OPEN), DW = W + 6;
  fit(C, [[-3, -2, -3], [W + 3, D, -3], [W + 3, -2, TOPZ + 3], [-3 + dx * DW, D + dy * DW, -3], [-3 + dx * DW, D + dy * DW, TOPZ + 3], [10, YC + OUT + 6, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r = 1.2, b = 0.7) => { const s = solid(g), [o, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, o, i, z0, z1)); return s.g; };

  const order = [];
  order.push(box(-3, -2, W + 3, 0, -3, TOPZ + 3));
  order.push(box(-3, 0, 0, D, -3, TOPZ + 3));
  // the door: a thin plate swung past square on its left hinge, the mirror's frame on its inner face
  const door = solid(g);
  {
    const at = (u, z, v = 0) => P(-3 + dx * u - dy * v, D + dy * u + dx * v, z);
    const pts = (v) => [at(0, -3, v), at(DW, -3, v), at(DW, TOPZ + 3, v), at(0, TOPZ + 3, v)];
    const hullPts = pts(0).concat(pts(1.6));
    door.sil.setAttribute("d", poly(fillet(hull(hullPts), hull(hullPts).map(() => 1.5))));
    const m = fillet([[6, 4], [DW - 6, 4], [DW - 6, TOPZ - 4], [6, TOPZ - 4]], [2, 2, 2, 2]).map(([u, z]) => at(u, z));
    mk("path", { class: "nf lo", d: poly(m) }, door.g);
  }
  order.push(door.g);
  order.push(box(-3, -2, W + 3, D, -3, 0));

  const items = IT.map(([r, c, kind, hw, hd, h], k) => {
    const grp = mk("g", {}, g), body = solid(grp), cap = kind ? solid(grp) : null;
    return { k, r, c, kind, hw, hd, h, z0: SH[r], grp, body, cap, y: tween(REST[k]), z: tween(0), last: "" };
  });
  for (const it of items) if (it.r === 1) order.push(it.grp);
  order.push(box(0, 0, W, D - 1, SH[0] - 2, SH[0]));
  for (const it of items) if (it.r === 0) order.push(it.grp);
  order.push(box(-3, -2, W + 3, D, TOPZ, TOPZ + 3));
  order.push(box(W, 0, W + 3, D, -3, TOPZ + 3));

  function draw(it, y, z) {
    const key = y.toFixed(2) + "," + z.toFixed(2);
    if (key === it.last) return;
    it.last = key;
    const cx = XC[it.c], cy = YC + y, z0 = it.z0 + z;
    if (it.kind) {
      put(it.body, prism(P, front, disc(cx, cy, it.hw), disc(cx, cy, it.hw - 1), z0, z0 + it.h - 5));
      put(it.cap, prism(P, front, disc(cx, cy, it.hw * 0.55), null, z0 + it.h - 5, z0 + it.h));
    } else {
      const [o, i] = rings(cx - it.hw, cy - it.hd, cx + it.hw, cy + it.hd, 1.2, 0.7);
      put(it.body, prism(P, front, o, i, z0, z0 + it.h));
    }
  }

  // an item slid past the front edge is nearer than the shelves and walls: paint it last
  let painted = null;
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.y, now), tval(it.z, now)); if (!tdone(it.y, now) || !tdone(it.z, now)) moving = true; }
    const out = items.filter((it) => tval(it.y, now) > 6);
    const key = out.map((it) => it.k).join();
    if (key !== painted) {
      painted = key;
      for (const n of order) if (!out.some((it) => it.grp === n)) g.appendChild(n);
      for (const n of order) if (out.some((it) => it.grp === n)) g.appendChild(n);
    }
    return moving;
  });
  bag.add(B.unregister);

  /** The item whose resting middle is nearest the pointer; -1 off the shelves. */
  const mids = items.map((it) => P(XC[it.c], YC + 4, it.z0 + it.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.hypot(m[0] - sx, (m[1] - sy) * 0.6); if (d < bd) { bd = d; best = k; } });
    const m = mids[best];
    return Math.abs(m[0] - sx) < 16 && Math.abs(m[1] - sy) < 34 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const t = a >= 0 ? items[a] : null, d = t ? Math.abs(it.c - t.c) + 2 * Math.abs(it.r - t.r) : 0;
      const y = a < 0 ? REST[k] : [OUT, 5, 2.5, 1][Math.min(d, 3)];
      const f = from >= 0 ? items[from] : null, delay = f ? (Math.abs(it.c - f.c) + Math.abs(it.r - f.r)) * stag : 0;
      tset(it.y, y, now, delay); tset(it.z, a === k ? LIFT : 0, now, delay);
      const on = k === (a < 0 ? FAV : a);
      it.body.sil.classList.toggle("hi", on);
      if (it.cap) it.cap.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "shelf " + (items[a].r + 1) + "·" + (items[a].c + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "medicinecabinet",
  means: "A wall medicine cabinet, door open: the bottle or box under the pointer slides forward off its shelf, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[235, 155], [289, 105], [314, 126], null],
  mount,
});

aquarium.code:
/**
 * Aquarium: a glass fish tank on a low cabinet stand, a gravel bed, two
 * weed plants and five fish swimming at different depths. The pointer is what
 * the fish notice: every fish turns on its own spring to face it and swims a
 * little toward it, and the fish nearest it is bright. At rest the fish drift
 * on their own headings, one bright. The slider is how quickly they follow.
 *
 * The pattern: a continuous aim (officechairs' springs, on heading and
 * position); the hit is a fixed plane through the water, read from rest.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, open, poly, prism, proj, rings, ringAt, seg, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const X1 = 90, Y1 = 38, H = 42, ZM = 24, L = 18, HB = 9, SWIM = 13;
const FISH = [[20, 13, 31, 10], [44, 24, 18, 200], [66, 12, 32, 150], [72, 26, 12, 25], [30, 12, 12, -40]];
const FAV = 1, PLANTS = [[11, 7, 30], [54, 6, 34]];
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-3, -3, -22], [X1 + 3, Y1 + 3, -22], [X1 + 3, -3, -22], [-3, Y1 + 3, -22], [-3, -3, H], [X1 + 3, -3, H], [-3, Y1 + 3, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the stand: one solid, three cabinet doors on its front
  const [sr, si] = rings(-3, -3, X1 + 3, Y1 + 3, 2.5, 1);
  const stand = solid(g);
  put(stand, prism(P, front, sr, si, -22, 0));
  const fy = Y1 + 3, sd = (x) => seg(P(x, fy, -19), P(x, fy, -6));
  mk("path", { class: "nf lo", d: seg(P(2, fy, -4), P(X1 - 2, fy, -4)) + sd(X1 / 3) + sd((2 * X1) / 3) }, stand.g);
  // the gravel bed and its pebbles
  const [gr, gi] = rings(0.5, 0.5, X1 - 0.5, Y1 - 0.5, 2, 1);
  put(solid(g), prism(P, front, gr, gi, 0, 5));
  [[10, 26], [28, 32], [42, 9], [52, 30], [70, 20], [82, 8], [22, 18]].forEach(([x, y]) => place(flatDot(g, C, 1, "dot off"), P(x, y, 5)));

  const swim = mk("g", {}, g);
  const plants = PLANTS.map(([x, y, h]) => {
    const grp = mk("g", {}, swim), d = [];
    for (let s = 0; s < 3; s++) {
      const pts = [], top = h - s * 6, ox = (s - 1) * 2.5;
      for (let i = 0; i <= 10; i++) { const t = i / 10; pts.push(P(x + ox + Math.sin(t * 5 + s * 2) * 2.2 * t, y + s * 0.8, 5 + t * top)); }
      d.push(open(pts));
    }
    mk("path", { class: "nf", d: d.join("") }, grp);
    return { grp, key: x + y };
  });
  const fish = FISH.map(([x, y, z, h], k) => {
    const grp = mk("g", {}, swim), a = h * (Math.PI / 180);
    const tail = mk("path", { class: "sil" }, grp), body = mk("path", { class: "sil" }, grp), gill = mk("path", { class: "nf lo" }, grp);
    const opt = { k: 100 * value, c: 18 * Math.sqrt(value) };
    return { k, x0: x, y0: y, z, a0: a, grp, tail, body, gill, sx: spring(x, opt), sy: spring(y, opt), sa: spring(a, opt), last: "" };
  });
  // the glass: a silhouette and a rim, no fill, painted over what swims inside
  const [tr, ti] = rings(0, 0, X1, Y1, 1.5, 0.8), glass = prism(P, front, tr, ti, 0, H);
  mk("path", { class: "nf sil", d: glass.sil }, g);
  mk("path", { class: "nf lo", d: poly(ringAt(P, tr, H)) + poly(ringAt(P, ti, H)) }, g);
  mk("path", { class: "nf dash", d: poly(ringAt(P, ti, H - 5)) }, g);

  function draw(f) {
    const x = f.sx.x, y = f.sy.x, a = f.sa.x, key = x.toFixed(2) + y.toFixed(2) + a.toFixed(3);
    if (key === f.last) return;
    f.last = key;
    const c = Math.cos(a), s = Math.sin(a), W = (u, v, z) => P(x + u * c - v * s, y + u * s + v * c, f.z + z);
    const ring = [];
    for (let i = 0; i < 18; i++) { const t = (i / 18) * Math.PI * 2; ring.push([(L / 2) * Math.cos(t), (HB / 2) * Math.sin(t) * (Math.cos(t) > 0 ? 1 : 0.85)]); }
    const pts = ring.map(([u, z]) => W(u, 1.3, z)).concat(ring.map(([u, z]) => W(u, -1.3, z)));
    f.body.setAttribute("d", poly(hull(pts)));
    f.tail.setAttribute("d", poly(fillet([W(-L / 2 + 1.5, 0, 0), W(-L / 2 - 4.5, 0, 3.4), W(-L / 2 - 3, 0, 0), W(-L / 2 - 4.5, 0, -3.4)], [0.6, 1, 0.6, 1])));
    const side = c - s > 0 ? 1.3 : -1.3;
    f.gill.setAttribute("d", open([-2.2, -1, 0, 1, 2.2].map((z) => W(L / 4 - Math.abs(z) * 0.4, side, z))));
  }

  let painted = null;
  const B = register(stage, (dt) => {
    let m = false;
    for (const f of fish) { if (stepS(f.sx, dt)) m = true; if (stepS(f.sy, dt)) m = true; if (stepS(f.sa, dt)) m = true; draw(f); }
    // paint far to near among the fish and the weeds
    const all = fish.map((f) => ({ grp: f.grp, key: f.sx.x + f.sy.x })).concat(plants);
    all.sort((p, q) => p.key - q.key);
    const key = all.map((p) => Math.round(p.key)).join();
    if (key !== painted) { painted = key; for (const p of all) swim.appendChild(p.grp); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    for (const f of fish) {
      if (over) {
        const dx = over[0] - f.x0, dy = over[1] - f.y0, d = Math.hypot(dx, dy);
        if (d < bd) { bd = d; near = f; }
        const step = Math.min(SWIM, d * 0.5), aim = d < 3 ? f.sa.t : Math.atan2(dy, dx);
        f.sx.t = clamp(f.x0 + (d ? (dx / d) * step : 0), 12, X1 - 12);
        f.sy.t = clamp(f.y0 + (d ? (dy / d) * step : 0), 12, Y1 - 12);
        f.sa.t = f.sa.t + wrap(aim - f.sa.t);
      } else { f.sx.t = f.x0; f.sy.t = f.y0; f.sa.t = f.sa.t + wrap(f.a0 - f.sa.t); }
    }
    for (const f of fish) {
      const on = over ? f === near : f.k === FAV;
      f.body.classList.toggle("hi", on); f.tail.classList.toggle("hi", on);
    }
    read.textContent = near ? "fish " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], ZM);
      over = x < -12 || x > X1 + 12 || y < -12 || y > Y1 + 12 ? null : [clamp(x, 0, X1), clamp(y, 0, Y1)];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const f of fish) for (const sp of [f.sx, f.sy, f.sa]) { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "aquarium",
  means: "A fish tank on a stand: every fish turns and swims a little toward the pointer, and the nearest fish is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[155, 100], [190, 140], [245, 170], null],
  mount,
});

birdcages.code:
/**
 * Bird cages: three round domed cages hung at different heights from the
 * rail of a stand, each a wire drum on a tray with a domed top, a perch and
 * a little door. The pointer picks a cage by where it hangs: that cage swings
 * out toward the reader and its door opens, the others swing a little after
 * it. At rest the cages hang a touch askew, the middle door ajar and bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (bookshelf); the hit is the
 * nearest resting middle along x, so a swinging cage never moves its target.
 */
const {
  Cam, circ, facing, fillet, fit, hull, open, poly, prism, proj, rings, run, seg, tdone, tset, tval, tween,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const ZR = 84, R = 10, X1 = 116, XS = [18, 58, 98], HANG = [6, 20, 12], HT = [22, 26, 19];
const REST = [3, -2, 5], FAV = 1, SW = 24, AJAR = 25, OPEN = 65, T0 = -10 * (Math.PI / 180), TD = 0.42, D2R = Math.PI / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.25);
  const ext = [[-3, -16, 0], [X1 + 3, 16, 0], [X1 + 3, -16, 0], [-3, 16, 0], [0, 0, ZR + 3], [X1, 0, ZR + 3]];
  XS.forEach((x, k) => { const l = HANG[k] + R * 0.7 + HT[k] + 3; ext.push([x, l * Math.sin(SW * D2R) + R + 6, ZR - l * Math.cos(SW * D2R)]); });
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, 1, 0.5); put(solid(g), prism(P, front, o, i, z0, z1)); };

  // the stand: two posts on feet and the rail across them
  box(-3, -14, 3, 14, 0, 3); box(-1.8, -1.8, 1.8, 1.8, 3, ZR);
  box(-2, -1.4, X1 + 2, 1.4, ZR, ZR + 2.8);
  const cages = XS.map((cx, k) => {
    const grp = mk("g", {}, g);
    place(flatDot(grp, C, 1.2, "dot off"), P(cx, 0, ZR));
    return {
      k, cx, grp, hang: mk("path", { class: "nf" }, grp), body: mk("path", { class: "sil" }, grp), wire: mk("path", { class: "nf lo" }, grp),
      tray: solid(grp), door: mk("path", {}, grp), dbar: mk("path", { class: "nf lo" }, grp),
      th: tween(REST[k]), ph: tween(k === FAV ? AJAR : 0), last: "",
    };
  });
  box(X1 - 1.8, -1.8, X1 + 1.8, 1.8, 3, ZR); box(X1 - 3, -14, X1 + 3, 14, 0, 3);

  const wrapA = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));
  const ring = circ(R, 32), dome = [0, 0.3, 0.55, 0.78, 0.92, 1];
  function draw(c, thd, phd) {
    const key = thd.toFixed(2) + "," + phd.toFixed(2);
    if (key === c.last) return;
    c.last = key;
    const th = thd * D2R, ph = phd * D2R, ct = Math.cos(th), st = Math.sin(th);
    // the cage hangs from its hook on the rail and swings about it, in y–z
    const W = (x, y, z) => P(c.cx + x, y * ct - z * st, ZR + y * st + z * ct);
    const zt = -c.hang0 - R * 0.7, zb = zt - c.h, at = (t, r, z) => W(r * Math.cos(t), r * Math.sin(t), z);
    const domeZ = (f) => zt + R * 0.7 * Math.sin((f * Math.PI) / 2), domeR = (f) => R * Math.cos((f * Math.PI) / 2);
    const pts = ring.map((q) => W(q.u, q.v, zb));
    for (const f of dome) for (const q of ring) pts.push(W(q.u * domeR(f) / R, q.v * domeR(f) / R, domeZ(f)));
    c.body.setAttribute("d", poly(hull(pts)));
    c.hang.setAttribute("d", seg(W(0, 0, 0), W(0, 0, zt + R * 0.7)) + poly(circ(1.4, 10).map((q) => W(q.u, 0, zt + R * 0.7 + 1.4 + q.v))));
    // the wires facing us: bars, the dome's ribs, the top hoop, and the perch seen through them
    const d = [];
    for (let i = 0; i < 16; i++) {
      const t = (i / 16) * Math.PI * 2;
      if (!front({ nu: Math.cos(t), nv: Math.sin(t) })) continue;
      if (Math.abs(wrapA(t - T0)) < TD + 0.05) { d.push(open(dome.map((f) => at(t, domeR(f), domeZ(f))))); continue; }
      d.push(open([at(t, R, zb)].concat(dome.map((f) => at(t, domeR(f), domeZ(f))))));
    }
    d.push(open(run(ring, front).map((q) => W(q.u, q.v, zt))));
    d.push(seg(W(-R + 1.5, 0, zb + c.h * 0.4), W(R - 1.5, 0, zb + c.h * 0.4)));
    c.wire.setAttribute("d", d.join(""));
    const [tr, ti] = rings(-R - 1.5, -R - 1.5, R + 1.5, R + 1.5, R + 1.5, 0.8);
    c.tray.sil.setAttribute("d", poly(hull(tr.map((q) => W(q.u, q.v, zb - 3)).concat(tr.map((q) => W(q.u, q.v, zb))))));
    c.tray.cr.setAttribute("d", open(run(ti, front).map((q) => W(q.u, q.v, zb))));
    // the door: a flat panel on its near hinge, swung out by ph
    const hx = R * Math.cos(T0 + TD), hy = R * Math.sin(T0 + TD), ex = R * Math.cos(T0 - TD) - hx, ey = R * Math.sin(T0 - TD) - hy;
    const ox = hx + ex * Math.cos(ph) - ey * Math.sin(ph), oy = hy + ex * Math.sin(ph) + ey * Math.cos(ph);
    const z0 = zb + 1.5, z1 = zb + Math.min(c.h - 4, 15);
    c.door.setAttribute("d", poly(fillet([W(hx, hy, z0), W(ox, oy, z0), W(ox, oy, z1), W(hx, hy, z1)], [0.8, 0.8, 0.8, 0.8])));
    c.dbar.setAttribute("d", [1 / 3, 2 / 3].map((s) => seg(W(hx + (ox - hx) * s, hy + (oy - hy) * s, z0), W(hx + (ox - hx) * s, hy + (oy - hy) * s, z1))).join(""));
  }
  cages.forEach((c, k) => { c.hang0 = HANG[k]; c.h = HT[k]; });

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of cages) { draw(c, tval(c.th, now), tval(c.ph, now)); if (!tdone(c.th, now) || !tdone(c.ph, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  /** The cage whose resting middle is nearest the pointer along x; -1 off the row. */
  const mids = cages.map((c, k) => P(c.cx, 0, ZR - HANG[k] - R * 0.7 - HT[k] / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 45 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cages.forEach((c, k) => {
      const d = Math.abs(k - a), delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(c.th, a < 0 ? REST[k] : d === 0 ? SW : d === 1 ? 7 : 3, now, delay);
      tset(c.ph, a < 0 ? (k === FAV ? AJAR : 0) : d === 0 ? OPEN : 0, now, delay);
      c.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "cage " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "birdcages",
  means: "Three bird cages hung from a stand rail: the cage under the pointer swings out and its door opens, the others swing a little.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[136, 94], [200, 157], [264, 178], null],
  mount,
});

winerack.code:
/**
 * Wine rack: a square box frame with a criss-cross of slats on its face,
 * nine bottles lying in the diamond cells with their shoulders and necks
 * toward the reader, each neck closed by a cork. The pointer picks a bottle
 * on the rack's face: it slides out toward the reader, and the bottles
 * around it ease out a little, staggered from it. At rest the bottles sit
 * unevenly, one half drawn, bright. The slider is the stagger.
 *
 * The pattern: one of many on a face (lockers); the hit is read on a fixed
 * plane just in front of the face, through the resting bottle ends.
 */
const {
  Cam, clamp, fit, hull, open, poly, prism, proj, rings, rrect, seg, facing, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 72, D = 26, M = 4, Q = W - 2 * M, S3 = Q / 3, R = 6.4, OUT = 22, FAV = [1, 2];
const REST = [[4, 6.5, 3], [3, 5, 13], [6.5, 2.5, 4.5]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.4);
  const cells = [];
  for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) {
    const u = (i - 1) * S3, v = Q + (j - 1) * S3;
    cells.push({ i, j, cx: M + (u + v) / 2, cz: M + (v - u) / 2 });
  }
  const ext = [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, 0, W], [W, 0, W], [W, D, W], [0, D, W]];
  for (const c of cells) ext.push([c.cx - R, D + OUT + 14, c.cz - R]);
  fit(C, ext, 200, 164);
  const P = proj(C), front = facing(C);
  const ringY = (cx, cz, r, y, n = 28) => {
    const out = [];
    for (let k = 0; k < n; k++) { const a = (k / n) * Math.PI * 2; out.push(P(cx + r * Math.cos(a), y, cz + r * Math.sin(a))); }
    return out;
  };

  const g = mk("g", {}, svg);
  // the frame: a box with its opening rimmed on the face, and the slats crossing it
  const [fr, fi] = rings(0, 0, W, D, 3, 1.4);
  put(solid(g), prism(P, front, fr, fi, 0, W));
  const onFace = (x, z) => P(x, D, z);
  let lat = poly(rrect(M, M, W - M, W - M, 1.6, 3).map((q) => onFace(q.u, q.v)));
  for (const c of [-1.5, -0.5, 0.5, 1.5].map((t) => t * S3)) {
    const x0 = Math.max(0, c), x1 = Math.min(Q, Q + c);
    lat += seg(onFace(M + x0, M + x0 - c), onFace(M + x1, M + x1 - c));
    const w = Q + c, a0 = Math.max(0, w - Q), a1 = Math.min(Q, w);
    lat += seg(onFace(M + a0, M + w - a0), onFace(M + a1, M + w - a1));
  }
  mk("path", { d: lat, class: "nf lo" }, g);

  // left to right, bottom to top: a bottle reaching out runs down-left, over the ones before it
  cells.sort((a, b) => a.cx + a.cz - (b.cx + b.cz));
  for (const c of cells) {
    const grp = mk("g", {}, g);
    c.body = mk("path", { class: "sil" }, grp);
    c.cr = mk("path", { class: "nf lo" }, grp);
    c.neck = mk("path", { class: "sil" }, grp);
    c.cork = mk("path", { class: "nf lo" }, grp);
    c.rest = REST[c.i][c.j];
    c.s = tween(c.rest);
    c.last = NaN;
  }

  function draw(c, s) {
    if (s === c.last) return;
    c.last = s;
    const yb = D + s, ys = yb + 5;
    c.body.setAttribute("d", poly(hull(ringY(c.cx, c.cz, R, D).concat(ringY(c.cx, c.cz, R, yb), ringY(c.cx, c.cz, 2.3, ys)))));
    c.cr.setAttribute("d", poly(ringY(c.cx, c.cz, R - 0.6, yb + 0.9)));
    c.neck.setAttribute("d", poly(hull(ringY(c.cx, c.cz, 1.9, ys, 16).concat(ringY(c.cx, c.cz, 1.9, ys + 6, 16), ringY(c.cx, c.cz, 2.4, ys + 6.4, 16), ringY(c.cx, c.cz, 2.4, ys + 8.4, 16)))));
    c.cork.setAttribute("d", poly(ringY(c.cx, c.cz, 1.3, ys + 8.4, 16)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of cells) { draw(c, tval(c.s, now)); if (!tdone(c.s, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  /** The cell under the point, read on the plane y = D + 8, through the resting bottle ends; it never moves. */
  const YH = D + 8;
  function hit([sx, sy]) {
    const co = Math.cos(C.az), si = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + YH * si) / co, Y = x * si + YH * co, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    const X = x - M, Z = z - M, u = X - Z, v = X + Z;
    if (X < 0 || X > Q || Z < 0 || Z > Q) return null;
    const i = Math.floor(u / S3 + 1.5), j = Math.floor((v - Q) / S3 + 1.5);
    if (i < 0 || i > 2 || j < 0 || j > 2) return null;
    return cells.find((c) => c.i === i && c.j === j);
  }

  let act;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a || act;
    act = a;
    for (const c of cells) {
      const d = a ? Math.abs(c.i - a.i) + Math.abs(c.j - a.j) : 0;
      const s = !a ? c.rest : d === 0 ? OUT : d === 1 ? 10 : d === 2 ? clamp(c.rest + 2, 5, 8) : c.rest;
      tset(c.s, s, now, from ? (Math.abs(c.i - from.i) + Math.abs(c.j - from.j)) * stag : 0);
      const on = a ? c === a : c.i === FAV[0] && c.j === FAV[1];
      c.body.classList.toggle("hi", on); c.neck.classList.toggle("hi", on);
    }
    read.textContent = a ? `bottle ${a.i + 1}·${a.j + 1}` : "rest";
    B.wake();
  }
  setActive(null);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "winerack",
  means: "A criss-cross wine rack of nine bottles: the bottle under the pointer slides out toward you, and its neighbours ease out a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[137, 156], [195, 177], [188, 244], null],
  mount,
});

paintcans.code:
/**
 * Paint cans: five cans in a row on a crumpled drop cloth, each with a
 * rolled bead round its foot, a wire handle hanging down its front on two
 * ears, and a lid pressed into its rim; one can has run drips, one carries
 * a brush laid across its lid. The pointer picks a can by where it stands:
 * its lid pops up and tilts back, and the lids beside it lift a little,
 * staggered from it. At rest one lid sits ajar, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the can
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, circ, facing, fillet, fit, hull, open, poly, prism, proj, ringAt, rrect, run, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 27, R = 10, H = 22, Y = 14, FAV = 2, BRUSH = 3, DRIP = 1, LIFT = 15, TILT = 28;
const REST = [[0, 0], [0.4, 2], [4, 14], [0, 0], [0.8, -3]];
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const CLOTH = [[-16, -10], [58, -14], [146, -8], [152, 30], [104, 44], [30, 40], [-12, 34]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  const X1 = R + (N - 1) * STEP;
  fit(C, CLOTH.map(([x, y]) => [x, y, 0]).concat([[R, Y - R, H + LIFT + 8], [X1, Y - R, H + LIFT + 8]]), 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the drop cloth: a rounded, uneven sheet with its folds
  mk("path", { d: poly(fillet(CLOTH, [6, 10, 5, 8, 12, 6, 9], 4).map(([x, y]) => P(x, y, 0))) }, g);
  mk("path", { class: "nf lo", d: seg(P(4, 30, 0), P(40, 22, 0)) + seg(P(96, -6, 0), P(128, 4, 0)) + seg(P(112, 36, 0), P(140, 22, 0)) }, g);

  const e = [-Math.SQRT1_2, Math.SQRT1_2], f = [Math.SQRT1_2, Math.SQRT1_2], ZE = H - 4, RC = R + 1.2, PHI = (60 * Math.PI) / 180;
  const cans = [];
  for (let k = 0; k < N; k++) {
    const x = R + k * STEP, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, Y, R), disc(x, Y, R - 1.3), 0, H));
    let marks = open(ringAt(P, run(disc(x, Y, R, 36), front), 3));
    for (const s of [-1, 1]) { const ex = x + s * R * e[0], ey = Y + s * R * e[1]; marks += seg(P(ex, ey, ZE - 1.6), P(ex, ey, ZE + 1.6)); }
    if (k === DRIP) for (const [a, d] of [[30, 7], [52, 4.5]]) {
      const pts = [];
      for (const [da, z] of [[-2, H], [-2, H - d], [0, H - d - 1.4], [2, H - d], [2, H]]) { const t = ((a + da) * Math.PI) / 180; pts.push(P(x + R * Math.cos(t), Y + R * Math.sin(t), z)); }
      marks += open(pts);
    }
    mk("path", { class: "nf lo", d: marks }, grp);
    const lid = solid(grp), parts = k === BRUSH ? [solid(grp), solid(grp), solid(grp)] : [];
    const arc = [];
    for (let i = 0; i <= 20; i++) {
      const t = (i / 20) * Math.PI, a = RC * Math.cos(t), b = RC * Math.sin(t);
      arc.push(P(x + a * e[0] + b * Math.sin(PHI) * f[0], Y + a * e[1] + b * Math.sin(PHI) * f[1], ZE - b * Math.cos(PHI)));
    }
    mk("path", { class: "nf", d: open(arc) }, grp);
    cans.push({ k, x, lid, parts, z: tween(REST[k][0]), a: tween(REST[k][1]), last: "" });
  }

  // a point of the lid's frame: u across, v front to back, w up from the lid's seat, tilted back by a
  const lp = (c, lift, a) => (u, v, w) => P(c.x + u, Y + v * Math.cos(a), H - 0.4 + lift + w * Math.cos(a) - v * Math.sin(a));
  const slab = (L, u0, v0, u1, v1, w0, w1, inset, r) => {
    const at = (w, d) => rrect(u0 + d, v0 + d, u1 - d, v1 - d, Math.max(0.3, r - d), 3).map((q) => L(q.u, q.v, w));
    return { sil: poly(hull(at(w0, 0).concat(at(w1, inset)))), crease: poly(at(w1, inset + 0.5)) };
  };
  function draw(c, lift, deg) {
    const key = lift.toFixed(2) + "," + deg.toFixed(2);
    if (key === c.last) return;
    c.last = key;
    const L = lp(c, lift, (deg * Math.PI) / 180), ring = (r, w) => circ(r, 32).map((q) => L(q.u, q.v, w));
    put(c.lid, { sil: poly(hull(ring(R - 1.2, 0).concat(ring(R - 1.2, 1.4)))), crease: poly(ring(R - 3, 1.4)) });
    if (!c.parts.length) return;
    put(c.parts[0], slab(L, -1.6, -18, 1.6, -1, 1.4, 4, 0, 1.4));
    put(c.parts[1], slab(L, -3.6, -1, 3.6, 5, 1.4, 5, 0, 1));
    put(c.parts[2], slab(L, -3.6, 5, 3.6, 14, 1.6, 4.6, 0.8, 1.2));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of cans) { draw(c, tval(c.z, now), tval(c.a, now)); if (!tdone(c.z, now) || !tdone(c.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = cans.map((c) => P(c.x, Y, H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 50 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cans.forEach((c, k) => {
      const d = Math.abs(k - a), [z, t] = a < 0 ? REST[k] : d === 0 ? [LIFT, TILT] : d === 1 ? [4, 7] : d === 2 ? [1.4, 2] : REST[k];
      const delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(c.z, z, now, delay); tset(c.a, t, now, delay);
      c.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "can " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "paintcans",
  means: "Five paint cans on a drop cloth: the lid of the can under the pointer pops up and tilts, and its neighbours' lids lift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[120, 118], [194, 155], [269, 192], null],
  mount,
});

plantstand.code:
/**
 * Plant stand: three boards stepping up between two stepped side panels,
 * two flared pots on each, and six houseplants with their own leaf shapes:
 * upright blades, a low rosette, arching fronds, broad round leaves on
 * stems, a little palm and trailing hearts, each leaf with its midrib. The
 * pointer picks a plant by the pot it stands over: it grows taller and
 * opens its leaves, and the plants beside it grow a little, staggered from
 * it. At rest the plants are unevenly grown, one ahead and bright. The
 * slider is the stagger.
 *
 * The pattern: stepped parts at different heights; the pointer is read on
 * each plant's own resting plane, nearest middle wins.
 */
const {
  Cam, circ, fillet, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 56, DEP = 13, PH = 7, FAV = 2;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
// per plant: leaves, spread from az0, elevation el → el - open, length, width, widest point q, droop, stem height hb
const KINDS = [
  { n: 5, az0: 0.4, el: 82, open: 14, L: 17, w: 2.3, q: 0.9, droop: 0, hb: 0 },
  { n: 8, az0: 0, el: 38, open: 22, L: 7.5, w: 3.2, q: 1, droop: 0, hb: 0 },
  { n: 7, az0: 0.3, el: 55, open: 25, L: 15, w: 2.6, q: 1, droop: 0.55, hb: 0 },
  { n: 4, az0: 0.8, el: 40, open: 22, L: 11, w: 6.2, q: 0.8, droop: 0.15, hb: 5 },
  { n: 6, az0: 0.2, el: 28, open: 18, L: 10, w: 1.9, q: 1, droop: 0.45, hb: 9 },
  { n: 5, az0: 0.6, el: 18, open: 26, L: 8, w: 5, q: 0.6, droop: 0.9, hb: 1 },
];
const SPOT = [[15, 0], [41, 0], [14, 1], [40, 1], [16, 2], [42, 2]], REST = [0.15, 0.3, 0.7, 0, 0.25, 0.1];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.75);
  const yOf = (t) => 2 * DEP - t * DEP + DEP / 2, zOf = (t) => 8 + 12 * t;
  fit(C, [[-2, 0, 0], [W + 2, 3 * DEP, 0], [W + 2, 0, 0], [-2, 3 * DEP, 0], [6, 0, zOf(2) + 40], [W - 6, 0, zOf(2) + 40], [0, 3 * DEP + 6, 18]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const prof = fillet([[3 * DEP, 0], [3 * DEP, 9], [2 * DEP, 9], [2 * DEP, 21], [DEP, 21], [DEP, 33], [0, 33], [0, 0]], [1, 1.5, 1.5, 1.5, 1.5, 1.5, 1.5, 1], 3);
  const panel = (x) => mk("path", { d: poly(prof.map(([y, z]) => P(x, y, z))) }, g);
  panel(-1.5);

  const plants = SPOT.map(([x, t], k) => ({ k, x, t, y: yOf(t), z0: zOf(t), kind: KINDS[k], gr: tween(REST[k]), last: NaN }));
  for (let t = 2; t >= 0; t--) {
    const [r, i] = rings(0, yOf(t) - DEP / 2, W, yOf(t) + DEP / 2, 1.4, 0.7);
    put(solid(g), prism(P, front, r, i, zOf(t) - 2, zOf(t)));
    for (const p of plants.filter((q) => q.t === t)) {
      p.grp = mk("g", {}, g);
      const foot = disc(p.x, p.y, 3.6), top = disc(p.x, p.y, 5.2);
      p.pot = solid(p.grp);
      put(p.pot, { sil: poly(hull(ringAt(P, foot, p.z0).concat(ringAt(P, top, p.z0 + PH)))), crease: open(ringAt(P, run(disc(p.x, p.y, 4.3), front), p.z0 + PH)) });
      p.stem = mk("path", { class: "nf" }, p.grp);
      p.leaves = []; p.ribs = [];
      for (let j = 0; j < p.kind.n; j++) { p.leaves.push(mk("path", {}, p.grp)); p.ribs.push(mk("path", { class: "nf lo" }, p.grp)); }
    }
  }
  panel(W + 1.5);

  function leaf(p, j, gr) {
    const K = p.kind, az = K.az0 + (j / K.n) * Math.PI * 2, el = ((K.el + 8 - K.open * 1.4 * gr) * Math.PI) / 180, L = K.L * (0.75 + 0.85 * gr);
    const hb = K.hb * (0.8 + 1.2 * gr) + 3 * gr + (K.n > 6 ? 0 : (j % 2) * 1.2), bx = p.x, by = p.y, bz = p.z0 + PH - 1 + hb;
    const d = [Math.cos(el) * Math.cos(az), Math.cos(el) * Math.sin(az), Math.sin(el)], nx = -Math.sin(az), ny = Math.cos(az);
    const spine = (t) => [bx + d[0] * L * t, by + d[1] * L * t, bz + d[2] * L * t - K.droop * L * t * t * 0.7];
    const side = [], other = [], rib = [];
    for (let i = 0; i <= 10; i++) {
      const t = i / 10, s = spine(t), w = K.w * Math.pow(Math.sin(Math.PI * Math.pow(t, K.q)), 0.8) / 2;
      side.push(P(s[0] + nx * w, s[1] + ny * w, s[2])); other.unshift(P(s[0] - nx * w, s[1] - ny * w, s[2]));
      if (i > 0 && i < 9) rib.push(P(...s));
    }
    const tip = spine(1);
    return { depth: tip[0] + tip[1], d: poly(side.concat(other)), rib: open(rib), stem: hb > 0.5 ? seg(P(bx, by, p.z0 + PH - 1), P(bx, by, bz)) : "" };
  }
  function draw(p, gr) {
    if (gr === p.last) return;
    p.last = gr;
    const ls = [];
    for (let j = 0; j < p.kind.n; j++) ls.push(leaf(p, j, gr));
    ls.sort((a, b) => a.depth - b.depth);
    p.stem.setAttribute("d", ls.map((l) => l.stem).join(""));
    ls.forEach((l, j) => { p.leaves[j].setAttribute("d", l.d); p.ribs[j].setAttribute("d", l.rib); });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const p of plants) { draw(p, tval(p.gr, now)); if (!tdone(p.gr, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  /** Each plant's own resting plane, a little above its pot's rim; the plant whose middle the pointer lands nearest wins. */
  function hit([sx, sy]) {
    let best = -1, bd = 13;
    for (const p of plants) {
      const [x, y] = unproj(C, sx, sy, p.z0 + PH + 5), d = Math.hypot(x - p.x, y - p.y);
      if (d < bd) { bd = d; best = p.k; }
    }
    return best;
  }

  let act = -2;
  const dist = (a, b) => Math.abs(a.t - b.t) + Math.abs(Math.round((a.x - b.x) / 26));
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    for (const p of plants) {
      const d = a >= 0 ? dist(p, plants[a]) : 0, gr = a < 0 ? REST[p.k] : d === 0 ? 1 : d === 1 ? Math.max(REST[p.k], 0.5) : REST[p.k];
      tset(p.gr, gr, now, from < 0 ? 0 : dist(p, plants[from]) * stag);
      p.on = p.k === (a < 0 ? FAV : a);
      p.pot.sil.classList.toggle("hi", p.on);
      for (const l of p.leaves) l.classList.toggle("hi", p.on);
    }
    read.textContent = a < 0 ? "rest" : "plant " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "plantstand",
  means: "A three-step plant stand of six houseplants: the plant under the pointer grows taller and opens its leaves, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[153, 212], [227, 195], [256, 156], null],
  mount,
});

washingmachines.code:
/**
 * Washing machines: a laundromat row of four front loaders on one plinth,
 * each with a control strip, a dial and a small display above a round door
 * set in its collar, the drum behind it. The pointer picks a machine on the
 * row's front face: its door swings wide open on its right hinge, and the
 * doors beside it come ajar, staggered from it. At rest one door stands half
 * open, bright, and another is barely ajar. The slider is the stagger.
 *
 * The pattern: one of many on a face (lockers). Tweens per door; the hit is
 * read on the machines' front plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NM = 4, MW = 30, GAP = 2, PITCH = MW + GAP, D = 30, H = 44, R = 11, ZM = 19, T = 2.2;
const X1 = NM * PITCH - GAP, OPEN = 80, FAV = 2;
const REST = [14, 0, 48, 0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-3, -2, -3], [X1 + 3, D + 3, -3], [X1 + 3, -2, -3], [-3, D + 3, -3], [0, 0, H], [X1, 0, H], [MW / 2 + R - 4, D + 2 * R + 3, ZM - R]], 200, 166);
  const P = proj(C), front = facing(C);
  const onFace = (q, cx, cz) => P(cx + q.u, D, cz + q.v);

  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-3, -2, X1 + 3, D + 3, 2.5, 1);
  put(solid(g), prism(P, front, pr, pi, -3, 0));

  const ring = (rad) => circ(rad, 32);
  const machines = [];
  for (let i = 0; i < NM; i++) {
    const x0 = i * PITCH, x1 = x0 + MW, xm = x0 + MW / 2;
    const body = solid(g);
    const [br, bi] = rings(x0, 0, x1, D, 3, 1.4);
    put(body, prism(P, front, br, bi, 0, H));
    let d = seg(P(x0 + 1.5, D, H - 10), P(x1 - 1.5, D, H - 10));
    d += poly(rrect(x0 + 4, H - 7.4, x0 + 14, H - 3.6, 0.8, 2).map((q) => P(q.u, D, q.v)));
    d += poly(ring(3.2).map((q) => onFace(q, x1 - 8, H - 5.5))) + seg(P(x1 - 8, D, H - 5.5), P(x1 - 6, D, H - 3.3));
    d += poly(ring(R + 1.6).map((q) => onFace(q, xm, ZM))) + poly(ring(R - 1.4).map((q) => onFace(q, xm, ZM)));
    d += poly(ring(R - 5).map((q) => onFace(q, xm, ZM)));
    mk("path", { class: "nf lo", d }, body.g);
    machines.push({ i, x0, hx: xm + R, a: tween(REST[i]), last: NaN });
  }
  // the doors after every body: an open door reaches out over its own machine's face
  for (const m of machines) {
    m.door = solid(g);
    m.marks = mk("path", { class: "nf lo" }, m.door.g);
  }

  const disc = ring(R), glass = ring(R * 0.6);
  function draw(m, deg) {
    const th = (deg * Math.PI) / 180, c = Math.cos(th), s = Math.sin(th);
    const at = (u, v, n) => P(m.hx - u * c + n * s, D + u * s + n * c, ZM + v);
    const back = disc.map((q) => at(q.u + R, q.v, 0.3)), face = disc.map((q) => at(q.u + R, q.v, T));
    m.door.sil.setAttribute("d", poly(hull(back.concat(face))));
    m.door.cr.setAttribute("d", open(face.concat([face[0]])));
    m.marks.setAttribute("d", poly(glass.map((q) => at(q.u + R, q.v, T))) + seg(at(2 * R - 2.6, -3, T), at(2 * R - 2.6, 3, T)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const m of machines) {
      const v = tval(m.a, now);
      if (v !== m.last) { draw(m, v); m.last = v; }
      if (!tdone(m.a, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  /** The machine under the point, read on the front plane (y = D), which never moves. */
  function hit([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    if (x < 0 || x > X1 || z < 0 || z > H) return -1;
    return clamp(Math.floor(x / PITCH), 0, NM - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    machines.forEach((m, i) => {
      const dist = Math.abs(i - a);
      const deg = a < 0 ? REST[i] : dist === 0 ? OPEN : dist === 1 ? 30 : 9;
      tset(m.a, deg, now, from >= 0 ? Math.abs(i - from) * stag : 0);
      m.door.sil.classList.toggle("hi", i === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : `washer ${a + 1}`;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "washingmachines",
  means: "A laundromat row of four front loaders: the door of the machine under the pointer swings open, its neighbours' doors come ajar.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[96, 117], [202, 170], [255, 197], null],
  mount,
});

keyrack.code:
/**
 * Key rack: a hotel key board under its cornice, four hooks across and three
 * high, each holding a heavy tag and a key in front of it, the
 * tag dotted with its floor and room. The pointer picks a hook on the board's
 * face: its key swings out on its hook and lifts, the keys around it swing a
 * little, staggered from it. At rest the keys hang unevenly and one is half
 * swung out, bright. The slider is the stagger.
 *
 * The pattern: one of many on a face (lockers). Tweens per key; the hit is
 * read on the board's face plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, place, put, register, solid,
} = HL;

const NC = 4, NR = 3, CW = 21, RH = 26, M = 6, BD = 4, PEG = 3.4, T = 1.4;
const W = 2 * M + NC * CW, H = 2 * M + NR * RH, FAV = [2, 1], SWING = 52;
const REST = [[3, 0, 5], [0, 4, 2], [6, 34, 0], [2, 0, 4]];
const SHANK = [[-1.7, 3.8], [-0.3, 3.8], [-0.3, 13.4], [-2.8, 13.4], [-2.8, 12], [-1.7, 12], [-1.7, 11.2], [-3.2, 11.2], [-3.2, 9.8], [-1.7, 9.8]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[-3, -1, 0], [W + 3, BD + 5, 0], [-3, -1, H + 3], [W + 3, -1, H + 3], [M, BD + PEG + 15, M + 8], [W - M, BD + PEG + 15, M + 8]], 200, 164);
  const P = proj(C), front = facing(C);
  const onFace = (q) => P(q.u, BD, q.v);

  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, BD, 2, 0.8);
  put(solid(g), prism(P, front, br, bi, 0, H));
  const [cr, ci] = rings(-3, -1, W + 3, BD + 5, 2, 1);
  put(solid(g), prism(P, front, cr, ci, H, H + 3));
  let d = poly(rrect(M - 2.5, M - 2.5, W - M + 2.5, H - M + 1, 2, 3).map(onFace));

  const keys = [];
  for (let r = 0; r < NR; r++) for (let c = 0; c < NC; c++) {
    const hx = M + c * CW + CW / 2, zh = M + (r + 1) * RH - 4;
    d += seg(P(hx, BD, zh), P(hx, BD + PEG + 0.6, zh));
    keys.push({ c, r, hx, zh, rest: REST[c][r] });
  }
  mk("path", { class: "nf lo", d }, g);
  // bottom row first, left to right: a key swung out only ever covers keys below it or to its left
  for (const k of keys) {
    k.g = mk("g", {}, g);
    k.tag = solid(k.g);
    k.dots = [];
    for (let i = 0; i <= k.r; i++) k.dots.push([1.5, 7 + i * 2]);
    for (let i = 0; i <= k.c; i++) k.dots.push([3, 7 + i * 2]);
    k.dots = k.dots.map(([u, v]) => ({ u, v, el: mk("circle", { r: 0.9, class: "dot off" }, k.g) }));
    k.bow = mk("path", {}, k.g);
    k.shank = mk("path", {}, k.g);
    k.a = tween(k.rest);
    k.last = NaN;
  }

  const tagR = rrect(-4.4, 0.2, 4.4, 15.2, 1.8, 3), bowC = circ(2.2, 16);
  function draw(k, deg) {
    const ph = (deg * Math.PI) / 180, s = Math.sin(ph), c = Math.cos(ph), lift = 3 * clamp((deg - 20) / 32, 0, 1);
    const at = (u, v, n) => P(k.hx + u, BD + PEG + v * s + n * c, k.zh + lift - v * c + n * s);
    const back = tagR.map((q) => at(q.u, q.v, 0)), face = tagR.map((q) => at(q.u, q.v, T));
    k.tag.sil.setAttribute("d", poly(hull(back.concat(face))));
    k.tag.cr.setAttribute("d", open(face.concat([face[0]])));
    for (const p of k.dots) place(p.el, at(p.u, p.v, T));
    k.bow.setAttribute("d", poly(bowC.map((q) => at(q.u - 1, q.v + 1.8, T + 0.6))));
    k.shank.setAttribute("d", poly(SHANK.map(([u, v]) => at(u, v, T + 0.6))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const k of keys) {
      const v = tval(k.a, now);
      if (v !== k.last) { draw(k, v); k.last = v; }
      if (!tdone(k.a, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  /** The hook under the point, read on the board's face plane (y = BD), which never moves. */
  function hit([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + BD * s) / c, Y = x * s + BD * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    if (x < M || x > W - M || z < M || z > H - M) return -1;
    return clamp(Math.floor((z - M) / RH), 0, NR - 1) * NC + clamp(Math.floor((x - M) / CW), 0, NC - 1);
  }

  let act = -2;
  const favI = FAV[1] * NC + FAV[0];
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const ak = a >= 0 ? keys[a] : null, fk = from >= 0 ? keys[from] : null;
    keys.forEach((k, i) => {
      const dist = ak ? Math.abs(k.c - ak.c) + Math.abs(k.r - ak.r) : 0;
      const deg = a < 0 ? k.rest : dist === 0 ? SWING : dist === 1 ? 16 : dist === 2 ? 6 : 2;
      tset(k.a, deg, now, fk ? (Math.abs(k.c - fk.c) + Math.abs(k.r - fk.r)) * stag : 0);
      k.tag.sil.classList.toggle("hi", i === (a < 0 ? favI : a));
    });
    read.textContent = a < 0 ? "rest" : `room ${ak.r + 1}·${ak.c + 1}`;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "keyrack",
  means: "A hotel key board of twelve hooks: the key under the pointer swings out on its hook and lifts, the keys around it swing a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[155, 89], [222, 174], [256, 241], null],
  mount,
});

cashregister.code:
/**
 * Cash register: a till with a keypad of twelve keys on its deck, a display
 * on a tower behind them, and a cash drawer in the front with its coin
 * trays. Over the keypad the keys near the pointer press in, each on its own
 * spring, the one under it deepest and bright. Down the front the drawer
 * slides out, the further the lower the pointer. At rest one key is held
 * half down, bright, and the drawer stands a little open. The slider is the
 * keys' reach, in key widths.
 *
 * The pattern: a continuous field (terrain) of keys, read on the plane of
 * their resting tops; the drawer is read on the front plane. Neither moves.
 */
const {
  Cam, clamp, facing, fit, lerp, poly, prism, proj, rings, rrect, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 66, D = 56, H = 24, KH = 4.4, KD = 3.8, NC = 3, NR = 4, PX = 11, PY = 10, KX = 5, KY = 12;
const OUT = 30, S0 = 4, NAMES = ["7", "8", "9", "4", "5", "6", "1", "2", "3", "0", "00", "+"];
const REST = { 9: 0.6, 4: 0.3, 2: 0.2 }, FAV = 9;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * PX, over = null, low = -1;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[0, 0, 0], [W, 0, 0], [W, D + OUT, 0], [0, D + OUT, 0], [62, 4, H + 16], [0, 0, H + KH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1, el = solid(g)) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(el, prism(P, front, o, i, z0, z1)); return el; };

  // the body with the drawer's mouth on its front and a receipt cover on its deck, then the display tower
  const body = block(0, 0, W, D, 3, 1.4, 0, H);
  mk("path", {
    class: "nf lo",
    d: poly(rrect(5, 1.6, W - 5, 11.6, 1, 3).map((q) => P(q.u, D, q.v))) + poly(rrect(46, 24, 60, 46, 2, 3).map((q) => P(q.u, q.v, H))) + seg(P(49, 35, H), P(57, 35, H)),
  }, body.g);
  const tower = block(46, 4, 62, 14, 2, 1, H, H + 16);
  mk("path", { class: "nf lo", d: poly(rrect(48.5, H + 7.5, 59.5, H + 13.5, 1, 3).map((q) => P(q.u, 14, q.v))) }, tower.g);

  // keys far to near, row by row
  const keys = [];
  for (let r = 0; r < NR; r++) for (let c = 0; c < NC; c++) {
    const i = r * NC + c, x0 = KX + c * PX, y0 = KY + r * PY;
    const [ring, inner] = rings(x0, y0, x0 + PX - 1.9, y0 + PY - 1.9, 1.4, 0.7);
    const rest = (REST[i] || 0) * KD;
    keys.push({ i, c, r, cx: x0 + PX / 2, cy: y0 + PY / 2, ring, inner, el: solid(g), rest, sp: spring(rest, { eps: 0.02 }), drawn: NaN });
  }

  // the drawer: only the part outside the front is drawn, with its coin trays and a pull
  const drawer = solid(g), trays = mk("path", { class: "nf lo" }, drawer.g);
  const dr = { sp: spring(S0, { eps: 0.05 }), drawn: NaN };
  function drawDrawer() {
    const s = clamp(dr.sp.x, 0.5, OUT);
    if (s === dr.drawn) return;
    dr.drawn = s;
    const [o, i] = rings(6, D, W - 6, D + s, 1, Math.min(0.8, s * 0.3));
    put(drawer, prism(P, front, o, i, 2.2, 11));
    let d = seg(P(28, D + s, 7.4), P(36, D + s, 7.4));
    for (let k = 1; k < 5; k++) { const x = lerp(6, W - 6, k / 5); d += seg(P(x, D, 11), P(x, D + s - 1.2, 11)); }
    if (s > 6) d += seg(P(7.5, D + s * 0.55, 11), P(W - 7.5, D + s * 0.55, 11));
    trays.setAttribute("d", d);
  }
  function drawKey(key) {
    const d = clamp(key.sp.x, 0, KD);
    if (d === key.drawn) return;
    key.drawn = d;
    put(key.el, prism(P, front, key.ring, key.inner, H - d, H + KH - d));
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const key of keys) { if (stepS(key.sp, dt)) m = true; drawKey(key); }
    if (stepS(dr.sp, dt)) m = true;
    drawDrawer();
    return m;
  });
  bag.add(B.unregister);

  /** The key under a point of the keys' resting top plane, or null off the keypad. */
  function keyAt([x, y]) {
    if (x < KX - 1 || x > KX + NC * PX || y < KY - 1 || y > KY + NR * PY) return null;
    return keys[clamp(Math.floor((y - KY) / PY), 0, NR - 1) * NC + clamp(Math.floor((x - KX) / PX), 0, NC - 1)];
  }

  function retarget() {
    const hit = over ? keyAt(over) : null;
    for (const key of keys) {
      key.sp.t = !hit ? key.rest : key === hit ? KD : KD * 0.8 * falloff(Math.hypot(key.cx - over[0], key.cy - over[1]) / RAD);
      key.el.sil.classList.toggle("hi", hit ? key === hit : low < 0 && key.i === FAV);
    }
    dr.sp.t = low < 0 ? S0 : lerp(S0 + 4, OUT, low);
    drawer.sil.classList.toggle("hi", low >= 0);
    read.textContent = hit ? "key " + NAMES[hit.i] : low >= 0 ? "drawer" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      over = unproj(C, p[0], p[1], H + KH);
      low = -1;
      if (!keyAt(over)) {
        over = null;
        // the front plane (y = D), which never moves: lower on it pulls the drawer further
        const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
        const x = ((p[0] - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (p[1] - C.oy) / C.S) / zf;
        if (x > 0 && x < W && z > -26 && z < H) low = clamp((H - 4 - z) / (H + 16), 0, 1);
      }
      retarget();
    },
    leave: () => { over = null; low = -1; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v * PX; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "cashregister",
  means: "A cash register: keys near the pointer press in on springs, and down its front the cash drawer slides out further the lower the pointer.",
  rules: [1, 3, 5, 8],
  range: [1, 2, 3],
  tour: [[208, 100], [190, 133], [172, 214], null],
  mount,
});

luggagecarousel.code:
/**
 * Luggage carousel: an airport baggage belt, an oval of slats on a plinth
 * round a raised island, fed by a chute from the far side. Six suitcases ride
 * round it all the time the figure is in view. Hovering slows the belt, on a
 * spring on its rate, so a bag can be read, and the bag nearest the pointer
 * is bright. At rest the chute is bright. The slider is the slowed rate.
 *
 * The pattern: slow (dilate time), as Conveyor; a bag's group moves between
 * the layer behind the island and the one in front of it as it rounds an end.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, open, poly, prism, proj, reducedMotion, rings, rrect,
  seg, spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const HX = 34, R = 17, BI = 8, BO = 26, ZB = 10, V0 = 18;
const PER = 4 * HX + 2 * Math.PI * R;
// length along the belt, width across it, height
const BAG = [[15, 10, 6], [12, 9, 8], [16, 11, 5], [11, 8, 7], [14, 10, 6], [13, 10, 9]];

/** The belt's centre line: [x, y, heading] at distance s round it. */
function at(s) {
  s = ((s % PER) + PER) % PER;
  if (s < 2 * HX) return [-HX + s, R, 0];
  s -= 2 * HX;
  if (s < Math.PI * R) { const a = Math.PI / 2 - s / R; return [HX + R * Math.cos(a), R * Math.sin(a), a - Math.PI / 2]; }
  s -= Math.PI * R;
  if (s < 2 * HX) return [HX - s, -R, Math.PI];
  s -= 2 * HX;
  const a = -Math.PI / 2 - s / R;
  return [-HX + R * Math.cos(a), R * Math.sin(a), a - Math.PI / 2];
}
const turn = (ring, a, cx, cy) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let slow = value, over = null;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-HX - BO, -BO, 0], [HX + BO, BO, 0], [HX + BO, -BO, 0], [-HX - BO, BO, 0], [-9, -50, ZB + 25], [9, -50, ZB + 25], [0, R, ZB + 10]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const stad = (h, r, b, z0, z1) => { const s = solid(g); put(s, prism(P, front, rrect(-HX - h, -r, HX + h, r, r, 14), rrect(-HX - h + b, -r + b, HX + h - b, r - b, r - b, 14), z0, z1)); return s; };

  // the chute, sloping down from the far side to the belt's edge
  const pts = [];
  for (const x of [-9, 9]) for (const [y, z] of [[-27, ZB + 2], [-50, ZB + 22]]) pts.push(P(x, y, z), P(x, y, z + 3));
  const chute = solid(g), hp = hull(pts);
  put(chute, { sil: poly(fillet(hp, hp.map(() => 1.5))), crease: open([P(-7.8, -50, ZB + 25), P(-7.8, -27.5, ZB + 5), P(7.8, -27.5, ZB + 5), P(7.8, -50, ZB + 25)]) });

  // plinth, belt, slats, then the island between the far and near layers
  stad(BO - 3, BO - 3, 1.2, 0, 6);
  stad(BO, BO, 1.4, 6, ZB);
  const slats = mk("path", { class: "nf lo" }, g);
  const layA = mk("g", {}, g);
  stad(BI, BI, 1.2, ZB, ZB + 5);
  const layB = mk("g", {}, g);

  const bags = BAG.map(([w, d, h], k) => {
    const s = solid(layA), strap = mk("path", { class: "nf lo" }, s.g);
    const [o, i] = rings(-w / 2, -d / 2, w / 2, d / 2, 2, 0.8);
    return { k, w, d, h, s, strap, o, i, u: (k * PER) / BAG.length, lay: null, x: 0, y: 0, last: NaN };
  });

  function draw(b) {
    const [x, y, a] = at(b.u);
    b.x = x; b.y = y;
    if (Math.abs(b.u - b.last) < 0.01) return;
    b.last = b.u;
    const top = ZB + b.h;
    put(b.s, prism(P, front, turn(b.o, a, x, y), turn(b.i, a, x, y), ZB, top));
    const c = Math.cos(a), s = Math.sin(a), q = b.d / 2 - 1.2;
    b.strap.setAttribute("d", seg(P(x - s * q, y + c * q, top), P(x + s * q, y - c * q, top)));
  }

  let order = "";
  function layer() {
    const sorted = [...bags].sort((p, q) => p.x + p.y - (q.x + q.y));
    const key = sorted.map((b) => b.k + (b.x - clamp(b.x, -HX, HX) + b.y > 0 ? "b" : "a")).join("");
    if (key === order) return;
    order = key;
    for (const b of sorted) (b.x - clamp(b.x, -HX, HX) + b.y > 0 ? layB : layA).append(b.s.g);
  }

  let phase = 0, drawnPhase = NaN;
  function drawSlats() {
    if (phase === drawnPhase) return;
    drawnPhase = phase;
    let d = "";
    for (let s = phase; s < PER; s += 11) {
      const [x, y, a] = at(s), nx = -Math.sin(a) * 7.5, ny = Math.cos(a) * 7.5;
      d += seg(P(x - nx, y - ny, ZB), P(x + nx, y + ny, ZB));
    }
    slats.setAttribute("d", d);
  }

  let lit;
  const rate = spring(V0, { eps: 0.05 }), still = reducedMotion();
  const B = register(stage, (dt) => {
    let m = stepS(rate, dt);
    if (!still) {
      const du = rate.x * dt;
      phase = (phase + du) % 11;
      for (const b of bags) b.u = (b.u + du) % PER;
      m = true;
    }
    for (const b of bags) draw(b);
    layer();
    drawSlats();
    pick();
    return m;
  });
  bag.add(B.unregister);

  /** The bag nearest the pointer on screen, from where it rides now. */
  function pick() {
    let best = null, bd = Infinity;
    if (over) for (const b of bags) {
      const [sx, sy] = P(b.x, b.y, ZB + b.h / 2), d = Math.hypot(sx - over[0], sy - over[1]);
      if (d < bd) { bd = d; best = b; }
    }
    if (best === lit) return;
    lit = best;
    for (const b of bags) b.s.sil.classList.toggle("hi", b === lit);
    chute.sil.classList.toggle("hi", !lit);
    read.textContent = lit ? "bag " + (lit.k + 1) : "rest";
  }

  function retarget() { rate.t = over ? slow : V0; pick(); B.wake(); }
  bag.add(pointer(stage, { move: (p) => { over = p; retarget(); }, leave: () => { over = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  for (const b of bags) draw(b);
  layer();
  drawSlats();
  lit = undefined;
  pick();
  return { set: (v) => { slow = v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "luggagecarousel",
  means: "Suitcases ride round an airport baggage carousel: hovering slows the belt, and the bag nearest the pointer is bright.",
  rules: [1, 5, 7, 8],
  range: [0, 4, 10],
  tour: [[174, 176], [240, 205], [290, 165], null],
  mount,
});

hotairballoons.code:
/**
 * Hot air balloons: five balloons over a low hill, each an envelope of gores
 * on a throat, with a basket hung on four ropes. The pointer is a warm draught:
 * the balloons near it rise, each on its own spring, the one under it highest
 * and bright. At rest they float at different heights, the middle one bright.
 * The slider is how far they rise.
 *
 * The pattern: a continuous field (terrain) along one row; the hit is each
 * balloon's rest centre on screen x, which never moves.
 */
const {
  Cam, circ, facing, fit, hull, open, poly, proj, ringAt, run, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SPOT = [[-36, 36, 38], [-20, 8, 54], [4, 4, 42], [22, -18, 60], [40, -38, 44]], FAV = 2;
// the envelope's profile above its throat: [height, radius]
const PROF = [[0, 2.6], [3, 6], [8, 10.5], [14, 13], [20, 12.5], [25, 9.5], [28.5, 5], [30, 0.5]];
const HILL = [[0, 50], [8, 43], [16, 31], [22, 18], [25, 6]];
const GORE = [-56, -28, 0, 28, 56].map((d) => ((45 + d) * Math.PI) / 180);
const falloff = (u) => 0.09 + 0.91 * Math.exp(-u * u * 2.2);
const at = (r, x, y, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let L = 22 * value, over = null;
  const C = Cam(45, 0.5, 1.85);
  const ext = [[50, 0, 0], [-50, 0, 0], [0, 50, 0], [0, -50, 0]];
  for (const [x, y, z] of SPOT) ext.push([x - 10, y + 10, z - 11], [x + 10, y - 10, z + 30 + 33]);
  fit(C, ext, 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the hill: a low mound, its silhouette and one dim contour
  const hill = solid(g);
  put(hill, {
    sil: poly(hull([].concat(...HILL.map(([z, r]) => ringAt(P, at(r, 0, 0, 64), z))))),
    crease: open(ringAt(P, run(at(37, 0, 0, 64), front), 12)),
  });

  const balloons = SPOT.map(([x, y, z], k) => ({ k, x, y, z, sx: P(x, y, 0)[0], sp: spring(0, { eps: 0.02 }), drawn: NaN }));
  for (const b of [...balloons].sort((p, q) => p.x + p.y - (q.x + q.y))) {
    const grp = mk("g", {}, g);
    b.basket = solid(grp);
    b.ropes = mk("path", { class: "nf lo" }, grp);
    b.env = solid(grp);
    b.gores = mk("path", { class: "nf lo" }, b.env.g);
  }

  function draw(b) {
    const lift = Math.max(0, b.sp.x);
    if (Math.abs(lift - b.drawn) < 0.01) return;
    b.drawn = lift;
    const z = b.z + lift, { x, y } = b;
    let pts = [];
    for (const [h, r] of PROF) pts = pts.concat(ringAt(P, at(r, x, y), z + h));
    put(b.env, { sil: poly(hull(pts)), crease: open(ringAt(P, run(at(2.6, x, y, 16), front), z)) });
    b.gores.setAttribute("d", GORE.map((t) => open(PROF.slice(1, -1).map(([h, r]) => P(x + r * Math.cos(t), y + r * Math.sin(t), z + h)))).join(""));
    const top = z - 7, bot = z - 11, sq = [[-2.6, -2.6], [2.6, -2.6], [2.6, 2.6], [-2.6, 2.6]];
    let base = [];
    for (const zz of [bot, top]) base = base.concat(sq.map(([u, v]) => P(x + u, y + v, zz)));
    put(b.basket, { sil: poly(hull(base)), crease: open([2, 3, 0].map((i) => P(x + sq[i][0] * 0.8, y + sq[i][1] * 0.8, top))) });
    b.ropes.setAttribute("d", sq.map(([u, v]) => seg(P(x + u * 0.75, y + v * 0.75, z + 0.4), P(x + u, y + v, top))).join(""));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const b of balloons) { if (stepS(b.sp, dt)) m = true; draw(b); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    let near = null, bd = Infinity;
    if (over) for (const b of balloons) { const d = Math.abs(over[0] - b.sx); if (d < bd) { bd = d; near = b; } }
    for (const b of balloons) {
      b.sp.t = over ? L * falloff(Math.abs(over[0] - b.sx) / 60) : 0;
      b.env.sil.classList.toggle("hi", near ? b === near : b.k === FAV);
    }
    read.textContent = near ? "balloon " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, { move: (p) => { over = p; retarget(); }, leave: () => { over = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  for (const b of balloons) draw(b);
  retarget();
  return { set: (v) => { L = 22 * v; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "hotairballoons",
  means: "Five hot air balloons over a hill: the balloons near the pointer rise, the one under it highest and bright.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.5],
  tour: [[159, 125], [248, 104], [298, 150], null],
  mount,
});

sailboats.code:
/**
 * Sailboats: a small harbour, four boats moored bow-in to a jetty on calm
 * water, each a pointed hull, a mast and a triangular sail on its boom. The
 * pointer is the wind: every sail swings toward it on its own spring, held
 * within the boom's reach, and the boat nearest it is bright. At rest the
 * sails lie aft, each a little off, one boat bright. The slider is how
 * quickly the sails follow (a stiffer or softer spring).
 *
 * The pattern: a continuous aim (Office chairs); the hit is on the water's
 * plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fillet, fit, hull, open, poly, prism, proj, ringAt, rings, run, unproj,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const BOATS = [[-42, -12, -80, 22], [-14, -4, -96, -16], [16, -10, -86, 30], [44, 0, -100, -24]], FAV = 1;
const LH = 15, BH = 5.4, MAST = 2.4, MZ = 44, BOOM = 19, REACH = 1.9;
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));
/** A hull's footprint, bow toward +u, scaled; normals from the outline's own tangent. */
const lens = (su, sv) => {
  const pts = [];
  for (let i = 0; i < 40; i++) { const t = (i / 40) * Math.PI * 2, c = Math.cos(t); pts.push([LH * su * c, BH * sv * Math.sin(t) * (1 - 0.5 * Math.max(0, c))]); }
  return pts.map(([u, v], i) => {
    const [a, b] = pts[(i + 39) % 40], [c, d] = pts[(i + 1) % 40], du = c - a, dv = d - b, l = Math.hypot(du, dv);
    return { u, v, nu: dv / l, nv: -du / l };
  });
};
const turn = (ring, a, cx, cy) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.1);
  const ext = [[-64, -48, -2], [64, 26, -2], [64, -48, -2], [-64, 26, -2]];
  for (const [x, y] of BOATS) ext.push([x, y, MZ], [x - BOOM, y + BOOM, 6], [x + BOOM, y - BOOM, 6]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1) => { const s = solid(g), [o, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, o, i, z0, z1)); return s; };

  // the water, the jetty's posts, then its deck
  block(-64, -48, 64, 26, 8, 1.6, -2, 0);
  for (let x = -54; x <= 54; x += 18) put(solid(g), prism(P, front, circ(1.4, 16).map((q) => ({ ...q, u: q.u + x, v: q.v - 37.5 })), null, 0, 2.6));
  block(-62, -46, 58, -37, 1.6, 0.8, 2.4, 4.4);

  const FOOT = lens(0.72, 0.6), TOP = lens(1, 1), INNER = lens(0.9, 0.72), MASTR = circ(0.8, 12);
  const boats = BOATS.map(([x, y, hd, off], k) => {
    const h = (hd * Math.PI) / 180, stern = h + Math.PI, rest = stern + (off * Math.PI) / 180;
    return { k, x, y, h, stern, rest, sp: spring(rest, { k: 100 * value, c: 18 * Math.sqrt(value) }), drawn: NaN, first: null };
  });
  for (const b of [...boats].sort((p, q) => p.x + p.y - (q.x + q.y))) {
    const grp = mk("g", {}, g), T = (r) => turn(r, b.h, b.x, b.y);
    b.hull = solid(grp);
    put(b.hull, { sil: poly(hull(ringAt(P, T(FOOT), 0).concat(ringAt(P, T(TOP), 4)))), crease: open(ringAt(P, run(T(INNER), front), 4)) });
    b.mx = b.x + MAST * Math.cos(b.h); b.my = b.y + MAST * Math.sin(b.h);
    b.sail = solid(grp);
    b.mast = solid(grp);
    put(b.mast, prism(P, front, MASTR.map((q) => ({ ...q, u: q.u + b.mx, v: q.v + b.my })), null, 4, MZ));
  }

  function draw(b) {
    const a = b.sp.x;
    if (Math.abs(a - b.drawn) < 1e-4) return;
    b.drawn = a;
    const ex = b.mx + BOOM * Math.cos(a), ey = b.my + BOOM * Math.sin(a);
    const tri = [P(b.mx, b.my, 6), P(b.mx, b.my, MZ - 2), P(ex, ey, 6)];
    put(b.sail, { sil: poly(fillet(tri, [1.2, 1.2, 1.2])), crease: open([P(b.mx, b.my, 7.4), P(ex - Math.cos(a) * 1.4, ey - Math.sin(a) * 1.4, 7.4)]) });
    // the sail is painted before the mast when it swings to the far side
    const first = Math.cos(a) + Math.sin(a) < 0;
    if (first !== b.first) { b.first = first; if (first) b.mast.g.before(b.sail.g); else b.sail.g.before(b.mast.g); }
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const b of boats) { if (stepS(b.sp, dt)) m = true; draw(b); }
    return m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null, bd = Infinity;
    for (const b of boats) {
      let aim = b.rest;
      if (over) {
        const d = Math.hypot(over[0] - b.x, over[1] - b.y);
        if (d < bd) { bd = d; near = b; }
        aim = b.stern + clamp(wrap(Math.atan2(over[1] - b.my, over[0] - b.mx) - b.stern), -REACH, REACH);
      }
      b.sp.t = b.sp.t + wrap(aim - b.sp.t);
    }
    for (const b of boats) {
      const on = over ? b === near : b.k === FAV;
      b.sail.sil.classList.toggle("hi", on);
      b.hull.sil.classList.toggle("hi", on);
    }
    read.textContent = near ? "boat " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { over = unproj(C, p[0], p[1], 0); retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { for (const b of boats) { b.sp.k = 100 * v; b.sp.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "sailboats",
  means: "Four sailboats moored at a jetty: every sail swings toward the pointer like wind, and the boat nearest it is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[222, 188], [140, 160], [262, 215], null],
  mount,
});

laptops.code:
/**
 * Laptops: four laptops in a row on a long desk with two end panels, each a
 * thin base with a keyboard and a trackpad, its lid on a hinge at the back.
 * The pointer picks a laptop by where it stands: its lid opens fully and its
 * screen shows a few dim lines, and the lids beside it open partway,
 * staggered from it. At rest the lids stand at different angles, one open
 * and bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the pick is the laptop
 * whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, facing, fillet, fit, hull, poly, prism, proj, rings, ringAt, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 30, D = 22, STEP = 40, M = 9, L = 20, T = 1.3, BZ = 2, Y0 = 13, DY = 44, LEG = 30;
const X1 = 2 * M + (N - 1) * STEP + W;
const REST = [28, 104, 0, 64], FAV = 1, FALL = [112, 70, 38, 16];
const LID = fillet([[0, 0], [W, 0], [W, L], [0, L]], [0.6, 0.6, 2.2, 2.2], 3);
const SCR = fillet([[2.2, 2], [W - 2.2, 2], [W - 2.2, L - 2.2], [2.2, L - 2.2]], [1, 1, 1, 1], 2);
const LINES = [[5, 4, 14], [5, 7, 19], [5, 10, 11], [5, 13, 17]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[0, 0, -LEG], [X1, DY, -LEG], [X1, 0, -LEG], [0, DY, -LEG], [0, 4, BZ + L + 2], [X1, 4, BZ + L + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the desk: two end panels, then the top over them
  for (const x of [7, X1 - 11]) { const [r, i] = rings(x, 5, x + 4, DY - 5, 1, 0.6); put(solid(g), prism(P, front, r, i, -LEG, -4)); }
  const [dr, di] = rings(0, 0, X1, DY, 3, 1.4);
  put(solid(g), prism(P, front, dr, di, -4, 0));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = M + k * STEP, grp = mk("g", {}, g);
    const [r, i] = rings(x0, Y0, x0 + W, Y0 + D, 2, 1);
    put(solid(grp), prism(P, front, r, i, 0, BZ));
    const keys = poly(ringAt(P, rrect(x0 + 3, Y0 + 3, x0 + W - 3, Y0 + 12, 1, 3), BZ));
    const pad = poly(ringAt(P, rrect(x0 + W / 2 - 5, Y0 + 14, x0 + W / 2 + 5, Y0 + 19.5, 1, 3), BZ));
    mk("path", { class: "nf lo", d: keys + pad }, grp);
    const lid = mk("path", { class: "sil" }, grp), face = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x0, lid, face, a: tween(REST[k]), last: NaN });
  }

  // the lid: a thin plate turning about the hinge; o is the offset along its normal, 0 on the screen side
  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const th = (deg * Math.PI) / 180, c = Math.cos(th), s = Math.sin(th);
    const at = ([u, t], o) => P(it.x0 + u, Y0 + 1 + t * c - o * s, BZ + t * s + o * c);
    const inner = LID.map((q) => at(q, 0)), outer = LID.map((q) => at(q, T));
    it.lid.setAttribute("d", poly(hull(inner.concat(outer))));
    const screen = deg > 40;
    let d = poly(screen ? inner : outer);
    if (screen) d += poly(SCR.map((q) => at(q, 0)));
    if (deg > 95) for (const [u, t, w] of LINES) d += seg(at([u, L - t], 0), at([u + w, L - t], 0));
    it.face.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x0 + W / 2, Y0 + D / 2, BZ + 6));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 50 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const deg = a < 0 ? REST[k] : FALL[Math.abs(k - a)];
      tset(it.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "laptop " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "laptops",
  means: "Four laptops on a desk: the lid under the pointer opens fully to a lit screen, and the lids beside it open partway.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[170, 141], [224, 168], [278, 195], null],
  mount,
});

printer.code:
/**
 * Printer: an office printer, a rounded body with a scanner lid on top, an
 * output slot on the front over a tray, and a paper drawer at the foot. Five
 * sheets lie fanned in the tray. As the pointer moves along the front, the
 * sheets nearest its place slide further out of the slot, each on its own
 * spring; low on the front, the paper drawer opens instead. At rest the top
 * sheet is bright. The slider is how far the sheets reach.
 *
 * The pattern: a continuous place along a row (springs), plus one discrete
 * part (a tween); the hit is on the front face's fixed plane.
 */
const {
  Cam, clamp, facing, fillet, fit, poly, prism, proj, rings, ringAt, rrect, seg, spring, stepS, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 64, Y1 = 44, H = 40, N = 5, TZ = 26, SX0 = 12, SX1 = 52, TR = 14;
const REST = [9, 12, 7, 11, 13], DZ = 12, DOUT = 16;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.85);
  fit(C, [[0, 0, 0], [X1, Y1 + 34, 0], [X1, 0, 0], [0, Y1 + 34, 0], [0, 0, H + 5], [X1, 0, H + 5]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the body, the scanner lid on it, and the marks on the front: the output slot and the drawer's seam
  const [br, bi] = rings(0, 0, X1, Y1, 5, 1.6);
  const body = solid(g);
  put(body, prism(P, front, br, bi, 0, H));
  const [lr, li] = rings(1.5, 1.5, X1 - 1.5, Y1 - 4, 4, 1.4);
  put(solid(g), prism(P, front, lr, li, H, H + 4));
  const face = (x0, z0, x1, z1, r) => poly(fillet([[x0, z0], [x1, z0], [x1, z1], [x0, z1]], [r, r, r, r], 3).map(([x, z]) => P(x, Y1, z)));
  mk("path", { class: "nf lo", d: face(SX0 - 2, TZ + 1.5, SX1 + 2, TZ + 5, 1.2) + seg(P(X1 - 14, Y1, H - 6), P(X1 - 6, Y1, H - 6)) }, g);

  // the drawer: a box sliding out along y, with its paper showing once it is out
  const drawer = solid(g), paper = mk("path", { class: "nf lo" }, drawer.g), handle = mk("path", { class: "nf lo" }, drawer.g);
  const dz = tween(0);
  let dLast = NaN;
  function drawDrawer(o) {
    if (o === dLast) return;
    dLast = o;
    const yf = Y1 + 0.8 + o, [r, i] = rings(5, Y1, X1 - 5, yf, 1.2, 0.6);
    put(drawer, prism(P, front, r, i, 2, DZ));
    paper.setAttribute("d", o > 4 ? poly(ringAt(P, rrect(9, Y1 + 1.5, X1 - 9, yf - 1.5, 1, 3), DZ)) : "");
    handle.setAttribute("d", seg(P(X1 / 2 - 7, yf, DZ - 3), P(X1 / 2 + 7, yf, DZ - 3)));
  }

  // the tray under the slot, then the sheets, bottom to top
  const [tr, ti] = rings(SX0 - 3, Y1, SX1 + 3, Y1 + TR, 1.5, 0.8);
  put(solid(g), prism(P, front, tr, ti, TZ - 1.4, TZ));
  const sheets = REST.map((e, k) => ({ k, el: mk("path", { class: "sil" }, g), sp: spring(e, { eps: 0.02 }), last: NaN }));
  function drawSheet(s) {
    const e = Math.round(s.sp.x * 100) / 100;
    if (e === s.last) return;
    s.last = e;
    const z = TZ + 0.4 + s.k * 0.9;
    s.el.setAttribute("d", poly(fillet([[SX0, Y1], [SX1, Y1], [SX1, Y1 + e], [SX0, Y1 + e]], [0, 0, 1.2, 1.2], 3).map(([x, y]) => P(x, y, z))));
  }

  const B = register(stage, (dt, now) => {
    let moving = !tdone(dz, now);
    drawDrawer(tval(dz, now));
    for (const s of sheets) { if (stepS(s.sp, dt)) moving = true; drawSheet(s); }
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the pointer on the front face's plane y = Y1, solved for x along the printer and z up it
  const O = P(0, Y1, 0), ex = P(1, Y1, 0), ez = P(0, Y1, 1);
  const a = ex[0] - O[0], b = ez[0] - O[0], c = ex[1] - O[1], d = ez[1] - O[1], det = a * d - b * c;
  function hit([sx, sy]) {
    const u = sx - O[0], v = sy - O[1], x = (u * d - b * v) / det, z = (a * v - c * u) / det;
    if (x < -2 || x > X1 + 2 || z < 0 || z > H + 20) return null;
    return z < DZ ? "drawer" : clamp((x - SX0) / (SX1 - SX0), 0, 1);
  }

  let act = null, top = -2;
  function setActive(h) {
    const now = performance.now();
    act = h;
    const c0 = typeof h === "number" ? h * (N - 1) : -1;
    sheets.forEach((s, k) => {
      const f = c0 < 0 ? 0 : Math.max(0.12, 1 - Math.abs(N - 1 - k - c0) * 0.42);
      s.sp.t = REST[k] + (16 + 16 * reach) * f;
    });
    const pick = c0 < 0 ? (h === "drawer" ? -1 : 0) : Math.round(c0);
    if (pick !== top) {
      top = pick;
      sheets.forEach((s, k) => s.el.classList.toggle("hi", N - 1 - k === pick));
    }
    drawer.sil.classList.toggle("hi", h === "drawer");
    tset(dz, h === "drawer" ? DOUT : 0, now, 0);
    read.textContent = h === null ? "rest" : h === "drawer" ? "drawer" : "sheet " + (Math.round(c0) + 1);
    B.wake();
  }
  setActive(null);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; setActive(act); }, destroy: bag.dispose };
}

hairline({
  name: "printer",
  means: "An office printer: sheets slide out of the slot where the pointer runs along it; low on the front, the paper drawer opens.",
  rules: [1, 3, 5, 8],
  range: [0, 0.5, 1],
  tour: [[154, 135], [226, 171], [190, 207], null],
  mount,
});

pencup.code:
/**
 * Pen cup: a round desk cup holding seven pens and pencils of different
 * lengths, each leaning out from the rim, beside a ruled notepad. The pointer
 * picks a pen by its resting shaft: it rises out of the cup and tilts
 * further, and the pens beside it round the rim rise a little, staggered
 * from it. At rest the pens stand at uneven heights, one raised and bright.
 * The slider is the stagger.
 *
 * The pattern: one of many round a ring (riffle); each pen pivots on its own
 * point inside the rim, so it never passes through the wall.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, run, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 13, CH = 26, RQ = 9.5, N = 7, LIFT = 22, TILT = 18, FAV = 4;
// [angle round the rim, length, pencil?, rest lean, rest lift]
const PENS = [[205, 46, 1, 9, 0], [250, 52, 0, 6, 3], [295, 42, 1, 11, 1], [340, 49, 0, 5, 0], [25, 54, 1, 8, 8], [75, 44, 0, 12, 2], [130, 48, 0, 7, 0]];
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const S = 2.75, C = Cam(45, 0.5, S);
  fit(C, [[-R, -R, 0], [54, 22, 0], [54, -16, 0], [-R, R, 0], [-8, -8, 68], [8, 8, 76]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the notepad, flat on the desk to the right, with its binding and ruled lines
  const [nr, ni] = rings(22, -16, 54, 22, 2, 1);
  const pad = solid(g);
  put(pad, prism(P, front, nr, ni, 0, 3));
  let rule = seg(P(22.5, -11, 3), P(53.5, -11, 3));
  for (let y = -5; y < 20; y += 4.5) rule += seg(P(26, y, 3), P(50, y, 3));
  mk("path", { class: "nf lo", d: rule }, pad.g);

  // the cup's back: its whole silhouette and the rim, under the pens
  const outer = disc(0, 0, R), inner = disc(0, 0, R - 1.6);
  const cup = solid(g);
  put(cup, prism(P, front, outer, inner, 0, CH));
  mk("path", { class: "nf lo", d: poly(ringAt(P, inner, CH)) }, cup.g);

  // pens, far to near: a capsule in screen space; pencils end in a cone, pens carry a cap band
  const rr = 1.5 * S;
  const pens = PENS.map(([deg, len, pencil, lean, lift], k) => {
    const a = (deg * Math.PI) / 180, q = [RQ * Math.cos(a), RQ * Math.sin(a), CH];
    return { k, a, q, len, pencil, lean, lift, grp: null, sil: null, band: null, z: tween(lift), t: tween(lean), last: "" };
  });
  for (const p of pens.slice().sort((m, n) => m.q[0] + m.q[1] - (n.q[0] + n.q[1]))) {
    p.grp = mk("g", {}, g);
    p.sil = mk("path", { class: "sil" }, p.grp);
    p.band = mk("path", { class: "nf lo" }, p.grp);
  }
  const fr = run(outer, front);
  mk("path", { class: "sil", d: poly(ringAt(P, fr, CH).concat(ringAt(P, fr, 0).reverse())) }, g);

  // the pen's axis: through its pivot inside the rim, leaning out by t degrees, slid up by z
  function axis(p, z, t) {
    const tr = (t * Math.PI) / 180, d = [Math.sin(tr) * Math.cos(p.a), Math.sin(tr) * Math.sin(p.a), Math.cos(tr)];
    const below = (CH - 3) / d[2] - z;
    return (s) => P(p.q[0] + d[0] * (s - below), p.q[1] + d[1] * (s - below), p.q[2] + d[2] * (s - below));
  }
  const capsule = (a, b, ra, rb) => {
    const pts = [];
    for (let i = 0; i < 12; i++) { const w = (i / 12) * Math.PI * 2, c = Math.cos(w), s = Math.sin(w); pts.push([a[0] + ra * c, a[1] + ra * s], [b[0] + rb * c, b[1] + rb * s]); }
    return poly(hull(pts));
  };
  function draw(p, z, t) {
    const key = z.toFixed(2) + "," + t.toFixed(2);
    if (key === p.last) return;
    p.last = key;
    const at = axis(p, z, t), L = p.len;
    if (p.pencil) {
      p.sil.setAttribute("d", poly(hull([...hullPts(at(0), rr), ...hullPts(at(L - 6), rr), ...hullPts(at(L), rr * 0.25)])));
      p.band.setAttribute("d", bandAt(at, L - 6));
    } else {
      p.sil.setAttribute("d", capsule(at(0), at(L), rr, rr));
      p.band.setAttribute("d", bandAt(at, L - 14));
    }
  }
  const hullPts = (c, r) => { const o = []; for (let i = 0; i < 12; i++) { const w = (i / 12) * Math.PI * 2; o.push([c[0] + r * Math.cos(w), c[1] + r * Math.sin(w)]); } return o; };
  function bandAt(at, s) {
    const a = at(s), b = at(s + 1), dx = b[0] - a[0], dy = b[1] - a[1], m = Math.hypot(dx, dy) || 1, nx = (-dy / m) * rr * 0.85, ny = (dx / m) * rr * 0.85;
    return seg([a[0] - nx, a[1] - ny], [a[0] + nx, a[1] + ny]);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const p of pens) { draw(p, tval(p.z, now), tval(p.t, now)); if (!tdone(p.z, now) || !tdone(p.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest resting shaft above the rim, in screen space
  const shafts = pens.map((p) => { const at = axis(p, p.lift, p.lean); return [at((CH - 3) / Math.cos((p.lean * Math.PI) / 180) - p.lift + 2), at(p.len)]; });
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    shafts.forEach(([a, b], k) => {
      const vx = b[0] - a[0], vy = b[1] - a[1], u = Math.max(0, Math.min(1, ((sx - a[0]) * vx + (sy - a[1]) * vy) / (vx * vx + vy * vy)));
      const dd = Math.hypot(sx - a[0] - u * vx, sy - a[1] - u * vy);
      if (dd < bd) { bd = dd; best = k; }
    });
    return bd < 12 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    pens.forEach((p, k) => {
      const d = a < 0 ? -1 : Math.min(Math.abs(k - a), N - Math.abs(k - a));
      const z = d < 0 ? p.lift : d === 0 ? LIFT : d === 1 ? 7 : d === 2 ? 3 : 0, t = d < 0 ? p.lean : d === 0 ? p.lean + TILT : d === 1 ? p.lean + 5 : p.lean;
      const delay = from < 0 ? 0 : Math.min(Math.abs(k - from), N - Math.abs(k - from)) * stag;
      tset(p.z, z, now, delay); tset(p.t, t, now, delay);
      p.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "pen " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "pencup",
  means: "A desk pen cup of seven pens and pencils: the one under the pointer rises out and tilts, and those beside it rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[123, 105], [165, 83], [186, 106], null],
  mount,
});

hospitalbeds.code:
/**
 * Hospital beds: a ward of three beds side by side under a ceiling curtain
 * rail, each bed on four casters with a headboard, a footboard, side rails, a
 * mattress in two sections and a pillow on the head section. The pointer
 * picks a bed: its head section raises, and the beds beside it raise a
 * little, staggered from it. At rest the heads sit at different angles, the
 * middle one bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the hit is each bed's
 * rest box, the nearest bed first, which never moves.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, run, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, W = 26, L = 58, SP = 42, HS = 27, ZF = 12, ZM = 15, MT = 5, X1 = (N - 1) * SP + W;
const REST = [16, 40, 6], FAV = 1, UP = 68;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.72);
  fit(C, [[-8, -12, 0], [X1 + 4, L + 4, 0], [X1 + 4, -12, 0], [-8, L + 4, 0], [-8, -12, 74], [X1 + 6, -12, 74]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1, parent = g) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const el = solid(parent); put(el, prism(P, front, o, i, z0, z1)); return el; };

  // the curtain rail on the ceiling, its hangers, and a curtain gathered at its far end
  const hang = [];
  for (const hx of [4, X1 / 2, X1 - 2]) hang.push(seg(P(hx, -10, 66), P(hx, -10, 74)));
  mk("path", { class: "nf lo", d: hang.join("") }, g);
  const cur = block(-6, -12, 6, -9, 2, 0.8, 20, 64);
  const folds = [];
  for (const fx of [-2, 2]) folds.push(seg(P(fx, -9, 61), P(fx, -9, 23)));
  mk("path", { class: "nf lo", d: folds.join("") }, cur.g);
  block(-8, -11, X1 + 6, -9, 1, 0.4, 64, 66.5);

  const beds = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * SP, x1 = x0 + W, grp = mk("g", {}, g);
    for (const [lx, ly] of [[x0 + 3, 3], [x1 - 3, 3], [x0 + 3, L - 3], [x1 - 3, L - 3]].sort((p, q) => p[0] + p[1] - q[0] - q[1])) {
      put(solid(grp), prism(P, front, disc(lx, ly, 2.4), null, 0, 3.6));
      put(solid(grp), prism(P, front, disc(lx, ly, 1, 12), null, 3.6, ZF));
    }
    block(x0, 0, x1, L, 2, 0.8, ZF, ZM, grp);
    block(x0 - 1, -3, x1 + 1, 0, 1.2, 0.6, ZF, ZF + 24, grp);
    block(x0 - 3, HS + 3, x0 - 1.4, L - 8, 0.7, 0.4, ZM + 1, ZM + 9, grp);
    block(x0 + 1, HS + 0.6, x1 - 1, L - 1, 2, 0.9, ZM, ZM + MT, grp);
    const head = solid(grp), pillow = solid(grp);
    block(x1 + 1.4, HS + 3, x1 + 3, L - 8, 0.7, 0.4, ZM + 1, ZM + 9, grp);
    block(x0 - 1, L, x1 + 1, L + 3, 1.2, 0.6, ZF, ZF + 17, grp);
    const hr = rings(x0 + 1, 0, x1 - 1, HS - 0.6, 2, 0.9), pr = rings(x0 + 4, HS - 14, x1 - 4, HS - 3, 4, 1.4);
    const box = [];
    for (const [bx, by] of [[x0 - 3, -3], [x1 + 3, -3], [x0 - 3, L + 3], [x1 + 3, L + 3]]) box.push(P(bx, by, 0), P(bx, by, 44));
    beds.push({ k, head, pillow, hr, pr, hit: hull(box), t: tween(REST[k]), last: NaN });
  }

  /** A plate on the head section: local u is x, v runs from the hinge to the head, h is height off the section's base. */
  function slab(el, [ring, inner], a, h0, h1) {
    const c = Math.cos(a), s = Math.sin(a);
    const at = (q, h) => P(q.u, HS - q.v * c + h * s, ZM + q.v * s + h * c);
    const sil = poly(hull(ring.map((q) => at(q, h0)).concat(ring.map((q) => at(q, h1)))));
    put(el, { sil, crease: open(run(inner, (q) => front({ ...q, nv: -q.nv })).map((q) => at(q, h1))) });
  }
  function draw(bed, deg) {
    if (deg === bed.last) return;
    bed.last = deg;
    const a = (deg * Math.PI) / 180;
    slab(bed.head, bed.hr, a, 0, MT);
    slab(bed.pillow, bed.pr, a, MT, MT + 4);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const bed of beds) { draw(bed, tval(bed.t, now)); if (!tdone(bed.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const inside = (poly, [x, y]) => poly.every((p, i) => { const q = poly[(i + 1) % poly.length]; return (q[0] - p[0]) * (y - p[1]) - (q[1] - p[1]) * (x - p[0]) >= 0; }) ||
    poly.every((p, i) => { const q = poly[(i + 1) % poly.length]; return (q[0] - p[0]) * (y - p[1]) - (q[1] - p[1]) * (x - p[0]) <= 0; });
  function hit(pt) {
    for (let k = N - 1; k >= 0; k--) if (inside(beds[k].hit, pt)) return k;
    return -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    beds.forEach((bed, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? REST[k] : dd === 0 ? UP : dd === 1 ? 26 : 8;
      tset(bed.t, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      bed.head.sil.classList.toggle("hi", on);
      bed.pillow.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "bed " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "hospitalbeds",
  means: "A ward of three hospital beds: the head section of the bed under the pointer raises, and its neighbours raise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[165, 116], [219, 169], [230, 240], null],
  mount,
});

toyblocks.code:
/**
 * Toy blocks: twelve wooden cubes scattered in a loose four-by-three grid on
 * a play mat, a few with raised dots on their tops. The pointer plays: the
 * blocks near it hop up and turn a little, each on its own springs, the one
 * under it highest and bright. At rest the blocks sit askew, one bright. The
 * slider is the reach, in block spacings.
 *
 * The pattern: a continuous field (terrain) over a grid; the hit is on the
 * plane of the blocks' resting tops, which never moves. A lifted block
 * leaves a dashed footprint on the mat where it rests.
 */
const {
  Cam, circ, clamp, facing, fit, poly, prism, proj, ringAt, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NI = 4, NJ = 3, SP = 27, HB = 8, BH = 16, HOP = 24, FAV = 6;
const JIT = [[0, 1, -8], [2, -1, 14], [-1, 2, 4], [1, 0, -16], [-2, 1, 10], [1, -2, -4], [0, 1, 18], [2, 2, -12], [1, -1, 6], [-1, 0, -20], [2, 1, 12], [0, -2, -6]];
const DOTS = { 1: 1, 4: 2, 6: 1, 11: 1 };
const MX = NI * SP + 4, MY = NJ * SP + 4;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);
const turn = (ring, a, cx, cy) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * SP, over = null;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -4, -3], [MX, MY, -3], [MX, -4, -3], [-4, MY, -3], [8, 8, BH + HOP + 4], [MX - 8, 8, BH + HOP + 4]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mo, mi] = rings(-4, -4, MX, MY, 6, 2.2);
  put(solid(g), prism(P, front, mo, mi, -3, 0));

  const [CUBE, CIN] = rings(-HB, -HB, HB, HB, 2.6, 1.2);
  const DISC = circ(2.6, 20), DIN = circ(1.6, 20);
  const blocks = [];
  for (let j = 0; j < NJ; j++) for (let i = 0; i < NI; i++) {
    const n = j * NI + i, [jx, jy, yaw] = JIT[n];
    blocks.push({ n, i, j, cx: SP / 2 + 2 + i * SP + jx, cy: SP / 2 + 2 + j * SP + jy, rest: (yaw * Math.PI) / 180, dots: DOTS[n] || 0 });
  }
  blocks.sort((p, q) => p.cx + p.cy - (q.cx + q.cy));
  for (const b of blocks) {
    b.grp = mk("g", {}, g);
    b.foot = mk("path", { class: "nf dash" }, b.grp);
    b.el = solid(b.grp);
    b.dEl = [];
    for (let d = 0; d < b.dots; d++) b.dEl.push(solid(b.grp));
    b.lift = spring(0, { eps: 0.02 });
    b.yaw = spring(b.rest, { eps: 0.002 });
    b.drawn = "";
  }

  function draw(b) {
    const z = clamp(b.lift.x, 0, HOP), a = b.yaw.x, key = z.toFixed(2) + "," + a.toFixed(4);
    if (key === b.drawn) return;
    b.drawn = key;
    put(b.el, prism(P, front, turn(CUBE, a, b.cx, b.cy), turn(CIN, a, b.cx, b.cy), z, z + BH));
    b.foot.setAttribute("d", z > 1.5 ? poly(ringAt(P, turn(CUBE, b.rest, b.cx, b.cy), 0)) : "");
    b.dEl.forEach((el, d) => {
      const off = b.dots === 1 ? 0 : d === 0 ? -4 : 4, ox = b.cx + off * Math.cos(a + 0.785), oy = b.cy + off * Math.sin(a + 0.785);
      put(el, prism(P, front, turn(DISC, 0, ox, oy), turn(DIN, 0, ox, oy), z + BH, z + BH + 1.4));
    });
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const b of blocks) { if (stepS(b.lift, dt)) m = true; if (stepS(b.yaw, dt)) m = true; draw(b); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    let hit = null, bd = 13;
    if (over) for (const b of blocks) { const d = Math.hypot(b.cx - over[0], b.cy - over[1]); if (d < bd) { bd = d; hit = b; } }
    for (const b of blocks) {
      const f = over ? (b === hit ? 1 : 0.7 * falloff(Math.hypot(b.cx - over[0], b.cy - over[1]) / RAD)) : 0;
      b.lift.t = HOP * f;
      b.yaw.t = b.rest + (b.rest >= 0 ? 1 : -1) * 0.4 * f;
      const on = over ? b === hit : b.n === FAV;
      b.el.sil.classList.toggle("hi", on);
      for (const el of b.dEl) el.sil.classList.toggle("hi", on);
    }
    read.textContent = hit ? "block " + (hit.i + 1) + "·" + (hit.j + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], BH);
      over = x > -6 && x < MX + 2 && y > -6 && y < MY + 2 ? [x, y] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v * SP; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "toyblocks",
  means: "Twelve toy blocks on a play mat: the blocks near the pointer hop up and turn a little, the one under it highest.",
  rules: [1, 3, 5, 9],
  range: [1, 2, 3.5],
  tour: [[180, 124], [140, 181], [259, 205], null],
  mount,
});

swingset.code:
/**
 * Swing set: a playground frame, two A-shaped ends joined by a top bar, with
 * three seats hung on pairs of chains over a rubber pad. The pointer picks a
 * swing by where it hangs: its seat swings forward toward the reader, and
 * the swings beside it swing a little, staggered from it. At rest the seats
 * hang at different angles, one bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the hit is each swing's
 * rest centre on screen, which never moves.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NS = 3, SP = 26, X1 = (NS + 1) * SP, H = 58, D = 24, LC = 40, SW = 7, ST = 3.2;
const REST = [-10, 14, 28], FAV = 2, UP = 48;
const disc = (x, y, r, n = 14) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-8, -D - 8, -3], [X1 + 8, D + 14, -3], [X1 + 8, -D - 8, -3], [-8, D + 14, -3], [0, 0, H + 3], [X1, 0, H + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [po, pi] = rings(-8, -D - 8, X1 + 8, D + 14, 8, 2.4);
  put(solid(g), prism(P, front, po, pi, -3, 0));
  const leg = (xe, ye) => mk("path", { class: "sil", d: poly(hull(ringAt(P, disc(xe, ye, 1.8), 0).concat(ringAt(P, disc(xe, ye * 0.08, 1.6), H)))) }, g);
  leg(0, -D); leg(X1, -D); leg(0, D);
  // the top bar: a round rail along x
  const bar = [];
  for (const xe of [-3, X1 + 3]) for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; bar.push(P(xe, 2.2 * Math.cos(t), H + 2.2 * Math.sin(t))); }
  mk("path", { class: "sil", d: poly(hull(bar)) }, g);

  const swings = [];
  const [SR, SI] = rings(-SW, -ST, SW, ST, 1.6, 0.8);
  for (let k = 0; k < NS; k++) {
    const sx = (k + 1) * SP, grp = mk("g", {}, g);
    const chains = mk("path", { class: "nf" }, grp);
    swings.push({ k, sx, chains, seat: solid(grp), t: tween(REST[k]), last: NaN });
  }
  leg(X1, D);

  function draw(s, deg) {
    if (deg === s.last) return;
    s.last = deg;
    const a = (deg * Math.PI) / 180, c = Math.cos(a), n = Math.sin(a);
    const cy = LC * n, cz = H - LC * c;
    const at = (q, h) => P(s.sx + q.u, cy + q.v * c - h * n, cz + q.v * n + h * c);
    s.chains.setAttribute("d", seg(P(s.sx - SW + 1, 0, H - 1), at({ u: -SW + 1, v: 0 }, 0)) + seg(P(s.sx + SW - 1, 0, H - 1), at({ u: SW - 1, v: 0 }, 0)));
    const sil = poly(hull(SR.map((q) => at(q, -1.8)).concat(SR.map((q) => at(q, 0)))));
    put(s.seat, { sil, crease: open(run(SI, front).map((q) => at(q, 0))) });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const s of swings) { draw(s, tval(s.t, now)); if (!tdone(s.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = swings.map((s) => P(s.sx, 0, H - LC / 2));
  const half = (P(SP, 0, 0)[0] - P(0, 0, 0)[0]) / 2;
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < half && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    swings.forEach((s, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? REST[k] : dd === 0 ? UP : dd === 1 ? 16 : 5;
      tset(s.t, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      s.seat.sil.classList.toggle("hi", on);
      s.chains.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "swing " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "swingset",
  means: "A playground swing set with three swings: the swing under the pointer swings forward, and its neighbours swing a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[167, 116], [204, 134], [241, 153], null],
  mount,
});

gardentools.code:
/**
 * Garden tools: a shed wall of boards with a batten, six tools hanging on its
 * pegs (rake, spade, fork, hoe, shears, trowel), each a flat profile with its
 * thickness. The pointer picks a tool by where it hangs: it swings out toward
 * the reader and lifts off its peg, and its neighbours swing a little,
 * staggered from it. At rest one tool is swung out part way, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), hanging; the pick is the
 * tool whose resting middle is nearest the pointer's x on screen.
 */
const {
  Cam, fillet, fit, facing, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RZ = 84, WALL = RZ + 14, SWING = 34, LIFT = 7, FAV = 1, PY = 3;
const teeth = (cs, hw, d0, d1) => cs.flatMap((c) => [[c + hw, d0], [c + hw, d1], [c - hw, d1], [c - hw, d0]]);
const spread = (a, b, n) => Array.from({ length: n }, (_, i) => b - ((b - a) * i) / (n - 1));
const tgrip = (hw, d1, rest) => [[-5, -5], [5, -5], [5, -1.5], [hw, -1.5], [hw, d1], ...rest, [-hw, d1], [-hw, -1.5], [-5, -1.5]];
// each profile in its own plane: u across (centred on the peg), d down from the peg
const TOOLS = [
  { w: 22, p: [[-1.5, -5], [1.5, -5], [1.5, 60], [11, 60], ...teeth(spread(-10.2, 10.2, 6), 0.8, 64, 71), [-11, 60], [-1.5, 60]] },
  { w: 14, p: tgrip(1.5, 38, [[6, 40], [6.5, 58], [0, 63], [-6.5, 58], [-6, 40]]) },
  { w: 14, p: tgrip(1.5, 38, [[6, 39], [6, 43], ...teeth(spread(-4.8, 4.8, 4), 0.8, 43, 62), [-6, 43], [-6, 39]]) },
  { w: 16, p: [[-1.2, -5], [1.2, -5], [1.2, 60], [2.6, 64], [8, 64], [8, 70], [-8, 70], [-8, 64], [-2.6, 64], [-1.2, 60]] },
  { w: 12, p: [[-6, -4], [-3, -4], [0, 13], [3, -4], [6, -4], [2, 16], [2.6, 40], [0.6, 42], [0, 26], [-0.6, 42], [-2.6, 40], [-2, 16]] },
  { w: 10, p: [[-1.8, -4], [1.8, -4], [1.8, 12], [0.6, 12], [0.6, 15], [4.5, 16], [4, 26], [0, 33], [-4, 26], [-4.5, 16], [-0.6, 15], [-0.6, 12], [-1.8, 12]] },
];
const GAP = 7;
let cx = 8;
for (const t of TOOLS) { t.x = cx + t.w / 2; cx += t.w + GAP; t.len = Math.max(...t.p.map((q) => q[1])); t.p = fillet(t.p, t.p.map(() => 0.6)); }
const X1 = cx + 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  const tip = PY + 71 * Math.sin(rad(SWING));
  fit(C, [[-4, -4, -3], [X1 + 4, 34, -3], [X1 + 4, -4, -3], [-4, 34, -3], [-4, -4, WALL], [X1 + 4, -4, WALL], [12, tip, RZ + LIFT - 71 * Math.cos(rad(SWING))]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the floor, the wall of boards with its seams, the batten
  { const [r, i] = rings(-4, -4, X1 + 4, 34, 3, 1.2); put(solid(g), prism(P, front, r, i, -3, 0)); }
  const wall = solid(g);
  { const [r, i] = rings(-4, -4, X1 + 4, 0, 1.5, 0.8); put(wall, prism(P, front, r, i, 0, WALL)); }
  let seams = "";
  for (let x = 14; x < X1; x += 16) seams += seg(P(x, 0, 1), P(x, 0, WALL - 1));
  mk("path", { class: "nf lo", d: seams }, wall.g);
  { const [r, i] = rings(-3, 0, X1 + 3, 2.4, 1, 0.5); put(solid(g), prism(P, front, r, i, RZ - 3, RZ + 3)); }

  const tg = mk("g", {}, g);
  const tools = TOOLS.map((t, k) => {
    const grp = mk("g", {}, tg);
    const peg = mk("path", { class: "nf" }, grp);
    peg.setAttribute("d", seg(P(t.x, 2.4, RZ), P(t.x, 6, RZ)) + seg(P(t.x, 6, RZ), P(t.x, 6, RZ + 2.5)));
    const back = mk("path", { class: "lo" }, grp), face = mk("path", { class: "sil" }, grp);
    const pegTip = mk("path", { class: "nf", d: seg(P(t.x, PY + 0.5, RZ), P(t.x, 6, RZ)) + seg(P(t.x, 6, RZ), P(t.x, 6, RZ + 2.5)) }, grp);
    return { k, ...t, grp, back, face, pegTip, a: tween(k === FAV ? SWING * 0.45 : 0), z: tween(0), last: "" };
  });

  function draw(t, a, z) {
    const key = a.toFixed(2) + "," + z.toFixed(2);
    if (key === t.last) return;
    t.last = key;
    const ca = Math.cos(rad(a)), sa = Math.sin(rad(a));
    // swung about the peg's line (the x axis): down is (0, sa, -ca), the face's normal (0, ca, sa)
    const w = (u, d, off) => P(t.x + u, PY + d * sa + off * ca, RZ + z - d * ca + off * sa);
    t.face.setAttribute("d", poly(t.p.map(([u, d]) => w(u, d, 0))));
    t.back.setAttribute("d", poly(t.p.map(([u, d]) => w(u, d, -1.3))));
  }

  let painted = "";
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const t of tools) { draw(t, tval(t.a, now), tval(t.z, now)); if (!tdone(t.a, now) || !tdone(t.z, now)) moving = true; }
    // the more a tool swings out, the nearer it is: paint it later
    const order = tools.slice().sort((p, q) => tval(p.a, now) - tval(q.a, now) || p.k - q.k);
    const key = order.map((t) => t.k).join();
    if (key !== painted) { painted = key; for (const t of order) tg.appendChild(t.grp); }
    return moving;
  });
  bag.add(B.unregister);

  const mids = tools.map((t) => P(t.x, PY, RZ - t.len / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 18 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    tools.forEach((t, k) => {
      const d = Math.abs(k - a), delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(t.a, a < 0 ? (k === FAV ? SWING * 0.45 : 0) : d === 0 ? SWING : d === 1 ? 9 : d === 2 ? 3 : 0, now, delay);
      tset(t.z, a === k ? LIFT : 0, now, delay);
      t.face.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tool " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "gardentools",
  means: "Six garden tools on a shed wall: the one under the pointer swings out and lifts off its peg, its neighbours swing a little.",
  rules: [1, 2, 5, 10],
  range: [0, 40, 80],
  tour: [[148, 103], [210, 128], [292, 159], null],
  mount,
});

greenhouse.code:
/**
 * Greenhouse: a small glass house on a plinth, pitched roof, glazing bars on
 * every face and seed trays inside, four vents in the near roof slope hinged
 * at the ridge. The pointer is where the air should go: the vents near it
 * open, each on its own spring, the one under it widest and bright. At rest
 * the vents stand a little ajar, unevenly, one bright. The slider is the
 * reach, in vent widths.
 *
 * The pattern: a continuous field (terrain) along one row; the hit is on the
 * plane of the near roof slope at rest, which never moves.
 */
const {
  Cam, clamp, fillet, fit, facing, poly, prism, proj, rad, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 120, WD = 60, H = 36, R = 22, Z0 = 6, VW = 18, VT = 4, VL = 26, OPEN = 50;
const VX = [18, 46, 74, 102], REST = [8, 0, 24, 4], FAV = 2;
const TH = Math.atan2(R, WD / 2);
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * 28, over = null;
  const C = Cam(45, 0.5, 2.0);
  const ridge = (x, t, a) => [x, WD / 2 + t * Math.cos(TH - rad(a)), H + R - t * Math.sin(TH - rad(a))];
  fit(C, [[-3, -3, 0], [L + 3, WD + 3, 0], [L + 3, -3, 0], [-3, WD + 3, 0], [0, WD / 2, H + R], [L, WD / 2, H + R], ridge(VX[0], VL, OPEN), ridge(VX[3], VL, OPEN)], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const S = (a, b) => seg(P(...a), P(...b));
  const block = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const el = solid(g); put(el, prism(P, front, o, i, z0, z1)); return el; };

  block(-3, -3, L + 3, WD + 3, 3, 1.2, 0, Z0);
  // the far glass: back wall, far gable, far roof slope and their bars
  let far = S([0, 0, Z0], [0, 0, H]) + S([0, 0, H], [L, 0, H]) + S([0, 0, H], [0, WD / 2, H + R]) + S([0, WD / 2, H + R], [0, WD, H]) + S([0, WD / 2, Z0], [0, WD / 2, H + R]);
  for (let x = 20; x < L; x += 20) far += S([x, 0, Z0], [x, 0, H]) + S([x, 0, H], [x, WD / 2, H + R]);
  mk("path", { class: "nf lo", d: far }, g);
  // seed trays on the floor, each with its cells
  [[8, 18], [36, 24], [64, 16], [92, 22]].forEach(([x, y]) => {
    const el = block(x, y, x + 22, y + 16, 1.5, 0.6, Z0, Z0 + 4);
    let cells = "";
    for (const u of [5.5, 11, 16.5]) cells += S([x + u, y + 1, Z0 + 4], [x + u, y + 15, Z0 + 4]);
    cells += S([x + 1, y + 8, Z0 + 4], [x + 21, y + 8, Z0 + 4]);
    mk("path", { class: "nf lo", d: cells }, el.g);
  });
  // the near glass: front wall, near gable, near slope's bars between the vents and the openings' frames
  let near = S([L, 0, Z0], [L, WD / 2, Z0]) + S([L, WD / 2, Z0], [L, WD / 2, H + R]);
  for (let x = 20; x < L; x += 20) near += S([x, WD, Z0], [x, WD, H]);
  for (const x of [32, 60, 88]) near += S([x, WD / 2, H + R], [x, WD, H]);
  for (const vx of VX) near += poly([ridge(vx - VW / 2, VT, 0), ridge(vx + VW / 2, VT, 0), ridge(vx + VW / 2, VL, 0), ridge(vx - VW / 2, VL, 0)].map((q) => P(...q)));
  mk("path", { class: "nf lo", d: near }, g);
  const frame = [[0, 0, H], [0, WD / 2, H + R], [L, WD / 2, H + R], [L, 0, H], [L, 0, Z0], [L, WD, Z0], [L, WD, H], [0, WD, H], [0, WD, Z0], [L, WD, Z0]];
  mk("path", { class: "nf sil", d: S([0, WD, Z0], [0, WD, H]) + S([0, WD, H], [0, WD / 2, H + R]) + S([L, WD, H], [L, WD / 2, H + R]) + S([L, 0, H], [L, WD, H]) + frame.slice(0, 6).reduce((d, q, i, a) => (i ? d + seg(P(...a[i - 1]), P(...q)) : d), "") + S([0, WD, H], [L, WD, H]) + S([0, WD, Z0], [L, WD, Z0]) }, g);

  const vents = VX.map((x, k) => {
    const grp = mk("g", {}, g);
    return { k, x, stay: mk("path", { class: "nf lo" }, grp), pane: mk("path", { class: "nf sil" }, grp), sp: spring(REST[k], { eps: 0.05 }), drawn: NaN };
  });
  function draw(v) {
    const a = clamp(v.sp.x, 0, OPEN);
    if (a === v.drawn) return;
    v.drawn = a;
    const pts = [ridge(v.x - VW / 2, VT, a), ridge(v.x + VW / 2, VT, a), ridge(v.x + VW / 2, VL, a), ridge(v.x - VW / 2, VL, a)].map((q) => P(...q));
    v.pane.setAttribute("d", poly(fillet(pts, [1.2, 1.2, 1.2, 1.2])));
    v.stay.setAttribute("d", S(ridge(v.x, VL - 1, 0), ridge(v.x, VL - 1, a)) + S(ridge(v.x - VW / 2 + 1.5, (VT + VL) / 2, a), ridge(v.x + VW / 2 - 1.5, (VT + VL) / 2, a)));
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const v of vents) { if (stepS(v.sp, dt)) m = true; draw(v); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    const hit = over && over[1] ? vents.find((v) => Math.abs(v.x - over[0]) <= VW / 2 + 5) : null;
    for (const v of vents) {
      v.sp.t = !over ? REST[v.k] : v === hit ? OPEN : OPEN * 0.8 * falloff(Math.abs(v.x - over[0]) / RAD);
      v.pane.classList.toggle("hi", over ? v === hit : v.k === FAV);
    }
    read.textContent = hit ? "vent " + (hit.k + 1) : "rest";
    B.wake();
  }

  /** The pointer on the near roof slope at rest: where its ray meets that plane. */
  function onRoof([sx, sy]) {
    const [, ya] = unproj(C, sx, sy, 0), [, yb] = unproj(C, sx, sy, 100), b = (yb - ya) / 100;
    const z = (H + 2 * R - (2 * R / WD) * ya) / (1 + (2 * R / WD) * b), y = ya + b * z, [x] = unproj(C, sx, sy, z);
    return [x, y];
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = onRoof(p);
      const roof = y > WD / 2 - 2 && y < WD + 2;
      over = x > -6 && x < L + 6 && y > -10 && y < WD + 30 ? [clamp(x, 0, L), roof] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v * 28; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "greenhouse",
  means: "A glass greenhouse with four roof vents: the vents near the pointer open, the one under it widest.",
  rules: [1, 3, 5, 9],
  range: [1, 2, 3.5],
  tour: [[124, 99], [163, 119], [242, 159], null],
  mount,
});

windchimes.code:
/**
 * Wind chimes: seven tubes of different lengths hung on cords in a ring
 * under a round top, a striker disc among them on its own cord, all from one
 * hook. The pointer is the breeze: the tubes near it swing away from it, each
 * on its own spring, the one under it furthest and bright. At rest the tubes
 * lean a little, unevenly, as in a light wind, one bright. The slider is the
 * reach.
 *
 * The pattern: a continuous field (terrain) around a ring; the pick is the
 * tube whose resting middle is nearest the pointer on screen.
 */
const {
  Cam, circ, clamp, fillet, fit, facing, hull, poly, prism, proj, rad, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TOP = 100, RT = 14, RC = 10, RTUBE = 1.7, GAP = 14, MAXA = 30, FAV = 4, ZS = TOP - 46, SAIL = [ZS - 18, ZS - 40];
const LEN = [58, 50, 44, 38, 33, 29, 26];
const REST = [5, 3, 7, 2, 6, 4, 3];
const ZM = TOP - 40;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);
const disc = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value, over = null;
  const C = Cam(45, 0.5, 2.9);
  const low = SAIL[1];
  fit(C, [[-RT - 14, -RT - 14, low], [RT + 14, RT + 14, low], [RT + 14, -RT - 14, low], [-RT - 14, RT + 14, low], [0, 0, TOP + 14]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const cords = mk("path", { class: "nf lo" }, g);

  const tubes = LEN.map((len, k) => {
    const t = rad(-90 + (k * 360) / LEN.length), x = RC * Math.cos(t), y = RC * Math.sin(t);
    const grp = mk("g", {}, g);
    return { k, x, y, len, grp, body: mk("path", { class: "sil" }, grp), rim: mk("path", { class: "nf lo" }, grp), sx: spring(REST[k] * 0.7, { eps: 0.03 }), sy: spring(-REST[k] * 0.3, { eps: 0.03 }), last: "" };
  });
  // the striker hangs in the middle, among the tubes; paint all far to near
  const striker = { x: 0, y: 0, grp: mk("g", {}, g) };
  const stEl = solid(striker.grp);
  put(stEl, prism(P, front, disc(5.5), disc(4.6), ZS, ZS + 2.2));
  // the sail under the striker, a flat leaf turned to the wind
  const leaf = [[0, 0], [5, 4], [6, 12], [3, 20], [0, 22], [-3, 20], [-6, 12], [-5, 4]].map(([w, d]) => P(w * 0.7, -w * 0.7, SAIL[0] - d));
  mk("path", { class: "nf lo", d: seg(P(0, 0, ZS), P(0, 0, SAIL[0])) }, striker.grp);
  mk("path", { d: poly(fillet(leaf, leaf.map(() => 2))) }, striker.grp);
  [...tubes, striker].sort((a, b) => a.x + a.y - (b.x + b.y)).forEach((o) => g.appendChild(o.grp));
  const topEl = solid(g);
  put(topEl, prism(P, front, disc(RT, 48), disc(RT - 1.4, 48), TOP, TOP + 3));
  mk("path", { class: "nf", d: seg(P(0, 0, TOP + 3), P(0, 0, TOP + 9)) + poly(circ(3, 16).map((q) => P(q.u, 0, TOP + 12 + q.v))) }, g);

  /** A tube hanging from its cord's end, tilted by (ax, ay) degrees about x and y. */
  function drawTube(tb) {
    const ax = clamp(tb.sx.x, -MAXA, MAXA), ay = clamp(tb.sy.x, -MAXA, MAXA);
    const key = ax.toFixed(2) + "," + ay.toFixed(2);
    if (key === tb.last) return false;
    tb.last = key;
    let d = [Math.sin(rad(ax)), Math.sin(rad(ay)), -1];
    const n = Math.hypot(...d); d = d.map((v) => v / n);
    const top = [tb.x, tb.y, TOP - GAP], u = [1, 0, -d[0] / d[2] * 0], v = [0, 1, 0];
    const ring = (o) => circ(RTUBE, 16).map((q) => P(top[0] + d[0] * o + q.u * u[0] + q.v * v[0], top[1] + d[1] * o + q.v * v[1], top[2] + d[2] * o));
    const a = ring(0), b = ring(tb.len);
    tb.body.setAttribute("d", poly(hull(a.concat(b))));
    tb.rim.setAttribute("d", poly(a));
    return true;
  }
  let cordKey = "";
  const B = register(stage, (dt) => {
    let m = false;
    for (const tb of tubes) { if (stepS(tb.sx, dt)) m = true; if (stepS(tb.sy, dt)) m = true; drawTube(tb); }
    const key = tubes.map((t) => t.last).join();
    if (key !== cordKey) {
      cordKey = key;
      let d = seg(P(0, 0, TOP), P(0, 0, ZS + 2.2));
      for (const tb of tubes) d += seg(P(tb.x, tb.y, TOP), P(tb.x, tb.y, TOP - GAP));
      cords.setAttribute("d", d);
    }
    return m;
  });
  bag.add(B.unregister);

  const mids = tubes.map((tb) => P(tb.x, tb.y, TOP - GAP - tb.len / 2));
  function retarget(p) {
    let hit = null;
    if (p) {
      let bd = Infinity;
      mids.forEach((m, k) => { const dd = Math.hypot(m[0] - p[0], (m[1] - p[1]) * 0.35); if (dd < bd) { bd = dd; hit = tubes[k]; } });
      if (bd > 9) hit = null;
    }
    for (const tb of tubes) {
      if (!over) { tb.sx.t = REST[tb.k] * 0.7; tb.sy.t = -REST[tb.k] * 0.3; }
      else {
        // away from the pointer across the view, so the swing is seen, never foreshortened
        const r = Math.hypot(tb.x - over[0], tb.y - over[1]), side = mids[tb.k][0] >= p[0] ? 1 : -1;
        const amp = (tb === hit ? MAXA : MAXA * 0.75 * falloff(r / RAD)) * side * Math.SQRT1_2;
        tb.sx.t = amp; tb.sy.t = -amp;
      }
      tb.body.classList.toggle("hi", over ? tb === hit : tb.k === FAV);
    }
    read.textContent = hit ? "tube " + (hit.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], ZM);
      over = Math.hypot(x, y) < RT + 34 ? [x, y] : null;
      retarget(over ? p : null);
    },
    leave: () => { over = null; retarget(null); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget(null);
  return { set: (v) => { RAD = v; }, destroy: bag.dispose };
}

hairline({
  name: "windchimes",
  means: "A wind chime of seven tubes under a round top: the tubes near the pointer swing away from it, the one under it most.",
  rules: [1, 3, 5, 9],
  range: [12, 24, 40],
  tour: [[173, 122], [221, 137], [196, 170], null],
  mount,
});

espressomachine.code:
/**
 * Espresso machine: a two-group machine, a body under a deep top that hangs
 * over the drip tray, two group heads with their spouts and portafilter
 * handles, a pressure gauge on the top's face, a steam wand at the end, and
 * four cups on the tray. The pointer picks a cup by where it is along the
 * tray: it slides back under the nearer spout and fills, its level rising in
 * the cup; its neighbours fill a little, staggered from it. At rest one cup
 * stands under a spout half full, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the hit is the cups'
 * rest centres along the screen's x.
 */
const {
  Cam, circ, facing, fit, hull, open, poly, prism, proj, rings, ringAt, run, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const XS = [12, 34, 56, 78], SPOUT = [30, 62], CY = 49, SY = 37, TRAY = 5, CR = 5.6, CF = 4, CH = 8;
const REST = [[0, 0.3], [0, 0], [1, 0.55], [0, 0.15]], FAV = 2;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [96, 0, 56], [0, 60, 0], [96, 60, 0], [0, 46, 56], [96, 46, 56]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the body, the group heads under the top, the top, the handles, the tray, the wand
  const [br, bi] = rings(2, 0, 94, 30, 5, 1.2);
  put(solid(g), prism(P, front, br, bi, 0, 38));
  for (const x of SPOUT) {
    put(solid(g), prism(P, front, disc(x, SY, 5.5, 32), disc(x, SY, 4.6, 32), 30, 38));
    put(solid(g), prism(P, front, disc(x, SY, 1.4, 16), null, 25, 30));
  }
  const [tr, ti] = rings(0, 0, 96, 46, 6, 1.4);
  const top = solid(g);
  put(top, prism(P, front, tr, ti, 38, 54));
  const gauge = [];
  for (let i = 0; i < 28; i++) { const a = (i / 28) * Math.PI * 2; gauge.push(P(46 + 4.5 * Math.cos(a), 46, 46 + 4.5 * Math.sin(a))); }
  mk("path", { class: "nf lo", d: poly(gauge) + seg(P(46, 46, 46), P(48.5, 46, 48.5)) }, top.g);
  for (const x of SPOUT) {
    const [hr, hi] = rings(x - 1.6, SY + 4, x + 1.6, 56, 1.2, 0.5);
    put(solid(g), prism(P, front, hr, hi, 30, 32.4));
  }
  const [yr, yi] = rings(4, 32, 92, 60, 4, 1.4);
  const tray = solid(g);
  put(tray, prism(P, front, yr, yi, 0, TRAY));
  mk("path", { class: "sil", d: poly(hull(ringAt(P, disc(93, 43, 1.4, 16), 37).concat(ringAt(P, disc(94.5, 47, 1.2, 16), 22)))) }, g);
  mk("path", { class: "nf lo", d: [10, 20, 30, 40, 50, 60, 70, 80].map((x) => seg(P(x, 36, TRAY), P(x, 56, TRAY))).join("") }, tray.g);

  const cups = XS.map((x, k) => {
    const grp = mk("g", {}, g);
    return {
      k, x, grp, handle: mk("path", { class: "nf sil" }, grp), sil: mk("path", { class: "sil" }, grp),
      rim: mk("path", { class: "nf lo" }, grp), lvl: mk("path", { class: "nf lo" }, grp),
      s: tween(REST[k][0]), f: tween(REST[k][1]), last: "",
    };
  });
  const near = (x) => (Math.abs(x - SPOUT[0]) < Math.abs(x - SPOUT[1]) ? SPOUT[0] : SPOUT[1]);

  function draw(c, s, f) {
    const key = s.toFixed(3) + "," + f.toFixed(3);
    if (key === c.last) return;
    c.last = key;
    const x = c.x + (near(c.x) - c.x) * s, y = CY + (SY - CY) * s, z0 = TRAY, z1 = TRAY + CH;
    c.sil.setAttribute("d", poly(hull(ringAt(P, disc(x, y, CF), z0).concat(ringAt(P, disc(x, y, CR), z1)))));
    c.rim.setAttribute("d", poly(ringAt(P, disc(x, y, CR - 0.6), z1)));
    const h = [];
    for (let i = 0; i <= 12; i++) { const a = (i / 12) * Math.PI * 2; h.push(P(x + (CF + 2.6 + 2 * Math.cos(a)) * 0.707, y - (CF + 2.6 + 2 * Math.cos(a)) * 0.707, z0 + 4.2 + 2.2 * Math.sin(a))); }
    c.handle.setAttribute("d", poly(h));
    // the level: the part of the liquid's ring seen through the rim's opening
    const zl = z0 + 1 + f * (CH - 2.2), rl = CF + (CR - 0.6 - CF) * ((zl - z0) / CH);
    const seen = (q) => { const [wx, wy] = unproj(C, ...P(q.u, q.v, zl), z1); return Math.hypot(wx - x, wy - y) < CR - 0.7; };
    c.lvl.setAttribute("d", f > 0.02 ? open(ringAt(P, run(disc(x, y, rl, 40), seen), zl)) : "");
  }

  const B = register(stage, (_dt, now) => {
    let m = false;
    for (const c of cups) { draw(c, tval(c.s, now), tval(c.f, now)); if (!tdone(c.s, now) || !tdone(c.f, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  // the hit: the nearest cup by its rest centre along the screen's x, inside the tray's band
  const mids = cups.map((c) => P(c.x, CY, TRAY + CH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 28 && Math.abs(mids[best][1] - sy) < 34 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cups.forEach((c, k) => {
      const dd = Math.abs(k - a), delay = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(c.s, a < 0 ? REST[k][0] : dd === 0 ? 1 : 0, now, delay);
      tset(c.f, a < 0 ? REST[k][1] : dd === 0 ? 0.9 : dd === 1 ? Math.max(0.35, REST[k][1]) : REST[k][1], now, delay + (dd === 0 ? 250 : 0));
      const on = k === (a < 0 ? FAV : a);
      c.sil.classList.toggle("hi", on);
      c.handle.classList.toggle("hi", on);
    });
    // paint order follows where each cup is going
    const depth = (c) => { const t = tTarget(c); return c.x + (near(c.x) - c.x) * t + CY + (SY - CY) * t; };
    [...cups].sort((p, q) => depth(p) - depth(q)).forEach((c) => g.appendChild(c.grp));
    read.textContent = a < 0 ? "rest" : "cup " + (a + 1);
    B.wake();
  }
  function tTarget(c) { return act < 0 ? REST[c.k][0] : c.k === act ? 1 : 0; }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "espressomachine",
  means: "A two-group espresso machine: the cup under the pointer slides under a spout and fills; its neighbours fill a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[111, 163], [146, 181], [218, 217], null],
  mount,
});

teaset.code:
/**
 * Tea set: a round tray with a teapot in the middle, a squat body under a lid
 * and knob, a spout and a loop handle, and four cups on saucers around it.
 * The pointer picks a cup: the teapot turns on one spring to face it and tips
 * on another, spout down, as if to pour, and that cup is bright. At rest the
 * pot sits almost upright, turned a little off one cup, which is bright. The
 * slider is how far the pot tips.
 *
 * The pattern: a continuous aim (officechairs' spring on an angle) and a
 * tilt; the hit is on the cups' fixed plane, which never moves.
 */
const {
  Cam, circ, facing, fit, hull, poly, prism, proj, ringAt, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RT = 50, RC = 33, K = 1.2, PHI = [225, 315, 45, 135], FAV = 2, CZ = 4.2, HIT = 13;
const BODY = [[7, 0], [11, 2.5], [13, 6.5], [12.6, 10.5], [10.2, 13.8], [7.2, 15.6]];
const LID = [[7.2, 15.4], [5.6, 17.6], [2.6, 18.8], [1.6, 19.2], [1.6, 20.6], [2.4, 21.4], [1.2, 22.4]];
const SPOUT = [[11, 4.5, 2.8], [15, 7, 2.2], [18.5, 11, 1.7], [21, 15, 1.3]], PIV = 7;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));
const rad = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tip = value;
  const C = Cam(45, 0.5, 2.6);
  const ext = [];
  for (let k = 0; k < 12; k++) { const a = (k / 12) * Math.PI * 2; ext.push([RT * Math.cos(a), RT * Math.sin(a), 0], [22 * Math.cos(a), 22 * Math.sin(a), 34]); }
  fit(C, ext, 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(RT, 96), circ(RT - 2, 96), 0, 3));

  const cups = PHI.map((phi, k) => {
    const th = rad(phi - 45);
    return { k, x: RC * Math.cos(th), y: RC * Math.sin(th), d: Math.sin(rad(phi)) };
  });
  function cup(c) {
    const grp = mk("g", {}, g), { x, y } = c;
    put(solid(grp), prism(P, front, disc(x, y, 9.5, 40), disc(x, y, 7.6, 40), 3, CZ));
    const h = [];
    for (let i = 0; i <= 12; i++) { const a = (i / 12) * Math.PI * 2, o = 6.2 + 2 * Math.cos(a); h.push(P(x + o * 0.707, y - o * 0.707, CZ + 4 + 2.1 * Math.sin(a))); }
    c.handle = mk("path", { class: "nf sil", d: poly(h) }, grp);
    c.sil = mk("path", { class: "sil", d: poly(hull(ringAt(P, disc(x, y, 3.6), CZ).concat(ringAt(P, disc(x, y, 5.6), CZ + 6.5)))) }, grp);
    mk("path", { class: "nf lo", d: poly(ringAt(P, disc(x, y, 5, 32), CZ + 6.5)) }, grp);
  }
  cups.filter((c) => c.d < 0).sort((a, b) => a.d - b.d).forEach(cup);
  const pot = mk("g", {}, g);
  const el = { handle: mk("path", { class: "nf sil" }, pot), body: mk("path", { class: "sil" }, pot), lid: mk("path", { class: "sil" }, pot), spout: mk("path", { class: "sil" }, pot) };
  cups.filter((c) => c.d >= 0).sort((a, b) => a.d - b.d).forEach(cup);

  const aim0 = Math.atan2(cups[FAV].y, cups[FAV].x) - rad(16);
  const ang = spring(aim0), tilt = spring(rad(4));
  let drawn = "", facingUs = null;

  function draw() {
    const key = ang.x.toFixed(4) + "," + tilt.x.toFixed(4);
    if (key === drawn) return;
    drawn = key;
    const ca = Math.cos(ang.x), sa = Math.sin(ang.x), ct = Math.cos(tilt.x), st = Math.sin(tilt.x);
    // local u along the spout, v across, w up; tipped about the base's front edge, then turned
    const W = (u, v, w) => {
      const du = u - PIV, u2 = PIV + du * ct + w * st, w2 = -du * st + w * ct;
      return P(K * (u2 * ca - v * sa), K * (u2 * sa + v * ca), 3 + K * w2);
    };
    const rings = (prof, n = 28) => prof.flatMap(([r, w]) => Array.from({ length: n }, (_, i) => { const a = (i / n) * Math.PI * 2; return W(r * Math.cos(a), r * Math.sin(a), w); }));
    const along = (pts) => pts.flatMap(([u, w, r]) => Array.from({ length: 16 }, (_, i) => { const a = (i / 16) * Math.PI * 2; return W(u + r * Math.cos(a), r * Math.sin(a), w); }));
    el.body.setAttribute("d", poly(hull(rings(BODY))));
    el.lid.setAttribute("d", poly(hull(rings(LID, 20))));
    el.spout.setAttribute("d", poly(hull(along(SPOUT))));
    el.handle.setAttribute("d", poly(Array.from({ length: 20 }, (_, i) => { const a = (i / 20) * Math.PI * 2; return W(-12 + 4.6 * Math.cos(a), 0, 8.5 + 4.6 * Math.sin(a)); })));
    // the spout is painted over the body when it points at us, the handle when it points away
    const fu = ca + sa > 0;
    if (fu !== facingUs) {
      facingUs = fu;
      (fu ? [el.handle, el.body, el.lid, el.spout] : [el.spout, el.body, el.lid, el.handle]).forEach((e) => pot.appendChild(e));
    }
  }

  const B = register(stage, (dt) => {
    const m1 = stepS(ang, dt), m2 = stepS(tilt, dt);
    draw();
    return m1 || m2;
  });
  bag.add(B.unregister);

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    const aim = a < 0 ? aim0 : Math.atan2(cups[a].y, cups[a].x);
    ang.t = ang.t + wrap(aim - ang.t);
    tilt.t = a < 0 ? rad(4) : rad(tip);
    cups.forEach((c) => {
      const on = c.k === (a < 0 ? FAV : a);
      c.sil.classList.toggle("hi", on);
      c.handle.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "cup " + (a + 1);
    B.wake();
  }
  // the hit: the pointer on the cups' plane, the nearest cup within reach
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, CZ + 3);
    let best = -1, bd = HIT;
    cups.forEach((c, k) => { const d = Math.hypot(x - c.x, y - c.y); if (d < bd) { bd = d; best = k; } });
    return best;
  }
  setActive(-1);
  draw();
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tip = v; if (act >= 0) { tilt.t = rad(tip); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "teaset",
  means: "A teapot on a tray with four cups: the pot turns and tips toward the cup under the pointer, and that cup is bright.",
  rules: [1, 3, 5, 8],
  range: [6, 16, 24],
  tour: [[139, 138], [261, 138], [261, 199], null],
  mount,
});

cupcakestand.code:
/**
 * Cupcake stand: a three-tier round cake stand on a foot, its plates on one
 * pole with a finial, and nine cupcakes on the tiers, four, three and two,
 * each a pleated paper case under a domed frosting swirl. The pointer is a
 * field: the cupcakes near it rise on their springs, the one under it highest
 * and bright, the lift falling off with distance. At rest they sit unevenly,
 * one on the middle tier raised, bright. The slider is the field's reach.
 *
 * The pattern: a field of springs (terrain); the hit unprojects onto each
 * cupcake's own rest top, so stepped tiers never pick the part behind.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, ringAt, run, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

// each tier: plate top z, plate radius, cupcake ring radius, screen angles (90 is nearest)
const TIERS = [[9.5, 46, 33, [45, 135, 225, 315]], [33.5, 32, 20, [210, 90, 330]], [55.5, 19, 10, [210, 30]]];
const REST = [[0, 1.5, 0.5, 0], [1, 6, 0], [0.5, 0]], FAV = [1, 1], LIFT = 15, HIT = 11;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.4);
  const ext = [];
  for (let k = 0; k < 12; k++) { const a = (k / 12) * Math.PI * 2; ext.push([46 * Math.cos(a), 46 * Math.sin(a), 0], [46 * Math.cos(a), 46 * Math.sin(a), 9.5]); }
  ext.push([0, 0, 66], [-7, 7, 55.5 + 15 + LIFT]);
  fit(C, ext, 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const cakes = [];
  TIERS.forEach(([z0, , rc, angs], t) => angs.forEach((phi, j) => {
    const th = ((phi - 45) * Math.PI) / 180;
    cakes.push({ t, j, x: rc * Math.cos(th), y: rc * Math.sin(th), z0, d: rc * Math.sin((phi * Math.PI) / 180), sp: spring(REST[t][j]), last: NaN });
  }));
  const tierCakes = (t, near) => cakes.filter((c) => c.t === t && (c.d > 0) === near).sort((a, b) => a.d - b.d);
  const pole = (z0, z1) => put(solid(g), prism(P, front, circ(1.8, 20), null, z0, z1));
  const plate = (zt, R) => put(solid(g), prism(P, front, circ(R, 72), circ(R - 1.6, 72), zt - 1.6, zt));
  function cupcake(c) {
    const grp = mk("g", {}, g);
    c.cs = mk("path", { class: "sil" }, grp);
    c.pl = mk("path", { class: "nf lo" }, grp);
    c.fr = mk("path", { class: "sil" }, grp);
    c.sw = mk("path", { class: "nf lo" }, grp);
  }

  // back to front: foot, then tier by tier its far cupcakes; the near ones after everything above them
  put(solid(g), prism(P, front, circ(14, 48), circ(12.6, 48), 0, 2.2));
  pole(2.2, 7.9);
  plate(9.5, 46);
  tierCakes(0, false).forEach(cupcake);
  pole(9.5, 31.9);
  plate(33.5, 32);
  tierCakes(1, false).forEach(cupcake);
  pole(33.5, 53.9);
  plate(55.5, 19);
  tierCakes(2, false).forEach(cupcake);
  pole(55.5, 61);
  const ball = [];
  for (let i = 0; i <= 6; i++) { const a = (i / 6) * Math.PI - Math.PI / 2; ball.push(...ringAt(P, circ(3 * Math.cos(a), 16), 63.5 + 3 * Math.sin(a))); }
  mk("path", { class: "sil", d: poly(hull(ball)) }, g);
  [2, 1, 0].forEach((t) => tierCakes(t, true).forEach(cupcake));

  function draw(c) {
    const lift = c.sp.x;
    if (Math.abs(lift - c.last) < 1e-3) return;
    c.last = lift;
    const z = c.z0 + lift, zt = z + 5.5, { x, y } = c;
    c.cs.setAttribute("d", poly(hull(ringAt(P, disc(x, y, 4.6), z).concat(ringAt(P, disc(x, y, 6), zt)))));
    const pleats = [];
    for (let i = 0; i < 5; i++) {
      const th = ((50 + i * 20 - 45) * Math.PI) / 180, cx = Math.cos(th), sy = Math.sin(th);
      pleats.push(seg(P(x + 4.6 * cx, y + 4.6 * sy, z), P(x + 6 * cx, y + 6 * sy, zt - 0.4)));
    }
    c.pl.setAttribute("d", pleats.join(""));
    const dome = [];
    for (let i = 0; i <= 6; i++) { const a = (i / 6) * (Math.PI / 2); dome.push(...ringAt(P, disc(x, y, 6.8 * Math.cos(a) + 0.01), zt + 6.2 * Math.sin(a))); }
    dome.push(...ringAt(P, disc(x + 0.6, y - 0.6, 1.4, 12), zt + 8.2));
    c.fr.setAttribute("d", poly(hull(dome)));
    c.sw.setAttribute("d", [[6.8, 0.2], [5.6, 3.2], [3.4, 5.4]].map(([r, h]) => open(ringAt(P, run(disc(x, y, r), front), zt + h))).join(""));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const c of cakes) { if (stepS(c.sp, dt)) m = true; draw(c); }
    return m;
  });
  bag.add(B.unregister);

  // the hit: each cupcake tests the pointer on its own rest top, the nearest middle wins
  let pt = null;
  function retarget() {
    const ds = cakes.map((c) => {
      if (!pt) return Infinity;
      const [wx, wy] = unproj(C, pt[0], pt[1], c.z0 + REST[c.t][c.j] + 6);
      return Math.hypot(wx - c.x, wy - c.y);
    });
    let a = -1;
    ds.forEach((d, k) => { if (d < HIT && (a < 0 || d < ds[a])) a = k; });
    cakes.forEach((c, k) => {
      const f = a < 0 ? 0 : k === a ? 1 : clamp(0.6 * Math.exp(-((ds[k] / reach) ** 2)), 0.09, 0.6);
      c.sp.t = a < 0 ? REST[c.t][c.j] : LIFT * f;
      const on = a < 0 ? c.t === FAV[0] && c.j === FAV[1] : k === a;
      c.cs.classList.toggle("hi", on);
      c.fr.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "cupcake " + (cakes[a].t + 1) + "·" + (cakes[a].j + 1);
    B.wake();
  }
  retarget();
  bag.add(pointer(stage, { move: (p) => { pt = p; retarget(); }, leave: () => { pt = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "cupcakestand",
  means: "A three-tier stand of nine cupcakes: those near the pointer rise, the one under it highest and bright.",
  rules: [1, 3, 5, 8],
  range: [10, 22, 36],
  tour: [[256, 221], [200, 167], [221, 103], null],
  mount,
});

globe.code:
/**
 * Globe: a desk globe on a tilted axis, held at its poles by a half-meridian
 * ring that stands on a stem and a round foot, its sphere drawn with lines of
 * latitude and longitude. The pointer spins it: the globe turns on its axis
 * toward the side the pointer is on (a spring on its angle), and the meridian
 * facing the pointer is bright. At rest the prime meridian is bright, a little
 * off centre. The slider is how far the globe turns.
 *
 * The pattern: a continuous aim on one angle (spotlights); the globe never
 * moves, so the hit is on the screen, and the meridian is read from the target.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 40, RR = 50, TILT = 23, STEP = 30, REST = 20, LATS = [-60, -30, 0, 30, 60];
// the axis leans 23° from upright toward screen right; b is the ring's plane beside it, w faces the viewer
const s2 = Math.SQRT1_2, Z = [0, 0, 1], e1 = [s2, -s2, 0], v = [0.866 * s2, 0.866 * s2, 0.5], wx = [s2, s2, 0];
const mix = (p, q, a, b) => p.map((x, j) => x * a + q[j] * b);
const ax = mix(Z, e1, Math.cos(rad(TILT)), Math.sin(rad(TILT))), bx = mix(Z, e1, -Math.sin(rad(TILT)), Math.cos(rad(TILT)));
const ZC = 64, CTR = [0, 0, ZC];
const at = (d, r) => CTR.map((c, j) => c + d[j] * r);
const dot3 = (p, q) => p[0] * q[0] + p[1] * q[1] + p[2] * q[2];
const wrapD = (a) => a - 360 * Math.round(a / 360);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, 2.1);
  const ext = [[-19, -19, 0], [19, 19, 0], [19, -19, 0], [-19, 19, 0]];
  for (let k = 0; k < 24; k++) { const t = (k / 24) * Math.PI * 2; ext.push(at(mix(ax, bx, Math.cos(t), Math.sin(t)), RR + 2), at(mix(e1, Z, Math.cos(t), Math.sin(t)), R)); }
  fit(C, ext, 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the foot and stem, straight under the ring's lowest point
  put(solid(g), prism(P, front, circ(19, 48), circ(17.4, 48), 0, 3.5));
  put(solid(g), prism(P, front, circ(4.5, 32), circ(3.6, 32), 3.5, 6));
  put(solid(g), prism(P, front, circ(1.8, 24), null, 6, ZC - RR));

  // the sphere: outline, latitudes (they do not move with the spin), meridians; only the near side is drawn
  const dir = (lat, lon) => { const c = Math.cos(rad(lat)); return ax.map((_, j) => c * Math.sin(rad(lon)) * bx[j] + c * Math.cos(rad(lon)) * wx[j] + Math.sin(rad(lat)) * ax[j]); };
  const near = (ds) => {
    let out = "", run = [];
    for (const d of ds) { if (dot3(d, v) > 0.01) run.push(P(...at(d, R))); else { if (run.length > 1) out += open(run); run = []; } }
    return run.length > 1 ? out + open(run) : out;
  };
  const samples = [];
  for (let la = -90; la <= 90; la += 10) for (let lo = 0; lo < 360; lo += 10) samples.push(P(...at(dir(la, lo), R)));
  mk("path", { class: "sil", d: poly(hull(samples)) }, g);
  const lats = LATS.map((la) => { const q = []; for (let lo = 0; lo <= 360; lo += 5) q.push(dir(la, lo)); return near(q); }).join("");
  mk("path", { class: "nf lo", d: lats }, g);
  const merLo = mk("path", { class: "nf lo" }, g), merHi = mk("path", { class: "nf hi" }, g);

  // the half-meridian ring round the poles, a band of two arcs, with its pivots (the far one only outside the sphere)
  const arc = (r) => { const q = []; for (let t = -4; t <= 184; t += 4) q.push(P(...at(mix(ax, bx, Math.cos(rad(t)), Math.sin(rad(t))), r))); return q; };
  mk("path", { class: "sil", d: poly(arc(RR + 1.6).concat(arc(RR - 1.2).reverse())) }, g);
  mk("path", { class: "nf lo", d: open(arc(RR + 0.2)) }, g);
  mk("path", { class: "nf sil", d: open([P(...at(ax, R)), P(...at(ax, RR - 1.2))]) + open([P(...at(ax, -R * 1.14)), P(...at(ax, -(RR - 1.2)))]) }, g);

  const sp = spring(REST);
  let drawn = NaN, drawnB = -1, bright = 0;
  function draw() {
    const phi = sp.x;
    if (Math.abs(phi - drawn) < 0.02 && drawnB === bright) return;
    drawn = phi; drawnB = bright;
    let lo = "", hi = "";
    for (let m = 0; m < 360 / STEP; m++) {
      const q = []; for (let la = -90; la <= 90; la += 5) q.push(dir(la, m * STEP + phi));
      if (m === bright) hi = near(q); else lo += near(q);
    }
    merLo.setAttribute("d", lo); merHi.setAttribute("d", hi);
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  // the globe stands still, so the hit is the pointer's offset across its face, read against the spring's target
  const c0 = P(...CTR), b1 = P(...at(e1, 1)), bs = [b1[0] - c0[0], b1[1] - c0[1]], bn = Math.hypot(...bs), RS = R * bn;
  let u = null;
  function retarget() {
    if (u === null) { sp.t = REST; bright = 0; read.textContent = "rest"; }
    else {
      sp.t = REST + gain * u;
      const lon = wrapD(Math.asin(clamp(u, -0.95, 0.95)) * (180 / Math.PI) - sp.t);
      bright = ((Math.round(lon / STEP) % 12) + 12) % 12;
      { const L = wrapD(bright * STEP); read.textContent = "lon " + Math.abs(L) + "°" + (L < 0 ? "W" : L > 0 ? "E" : ""); }
    }
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const dx = sx - c0[0], dy = sy - c0[1];
      u = Math.hypot(dx, dy) > RS * 1.25 ? null : clamp((dx * bs[0] + dy * bs[1]) / (bn * RS), -1, 1);
      retarget();
    },
    leave: () => { u = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (x) => { gain = x; if (u !== null) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "globe",
  means: "A desk globe on a tilted axis: it spins toward the pointer, and the meridian facing the pointer is bright.",
  rules: [1, 3, 5, 8],
  range: [40, 80, 120],
  tour: [[150, 150], [245, 140], [200, 200], null],
  mount,
});

microscope.code:
/**
 * Microscope: a lab microscope on a foot, a pillar with coarse and fine focus
 * knobs, a stage holding a slide over the lamp, an objective turret with three
 * lenses of different lengths under the head, and an inclined eyepiece tube.
 * The pointer's height raises the stage toward the lens (a spring), and the
 * pointer's side picks a lens: the turret turns to swing it into place, and
 * it is bright. At rest the shortest lens is in place, the stage half raised.
 * The slider is how quickly the stage follows.
 *
 * The pattern: a continuous input (height, a spring) beside a discrete choice
 * (which lens, a 700ms tween on the turret); the hit is on the screen, by bands
 * fixed at rest.
 */
const {
  Cam, circ, clamp, facing, fit, hull, lerp, poly, prism, proj, rings, spring, stepS, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TX = -5, TR = 5, TZ = 57, LEN = [7, 10, 13], ZLO = 25, REST_LENS = 0, REST_F = 0.4;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.8);
  fit(C, [[-24, -16, 0], [16, 16, 0], [16, -16, 0], [-24, 16, 0], [-24, 0, 96], [-6, 0, 74]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  /** A round tube between two world points, radius r0 to r1: its outline, and the far end's rim as a crease. */
  function tube(p0, p1, r0, r1) {
    const d = p1.map((x, j) => x - p0[j]), n = Math.hypot(...d), a = d.map((x) => x / n);
    const ref = Math.abs(a[2]) < 0.9 ? [0, 0, 1] : [1, 0, 0];
    let u = [a[1] * ref[2] - a[2] * ref[1], a[2] * ref[0] - a[0] * ref[2], a[0] * ref[1] - a[1] * ref[0]];
    const un = Math.hypot(...u); u = u.map((x) => x / un);
    const w = [a[1] * u[2] - a[2] * u[1], a[2] * u[0] - a[0] * u[2], a[0] * u[1] - a[1] * u[0]];
    const ring = (p, r) => Array.from({ length: 28 }, (_, i) => { const t = (i / 28) * Math.PI * 2; return P(...p.map((c, j) => c + r * (Math.cos(t) * u[j] + Math.sin(t) * w[j]))); });
    const e = ring(p1, r1);
    return { sil: poly(hull(ring(p0, r0).concat(e))), crease: poly(ring(p1, r1 * 0.78)) };
  }
  const box = (x0, y0, x1, y1, r, b, z0, z1, parent = g) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(parent); put(s, prism(P, front, o, i, z0, z1)); return s; };

  box(-25, -16, 15, 16, 6, 1.6, 0, 5);
  put(solid(g), prism(P, front, disc(0, 0, 4.5), disc(0, 0, 3.6), 5, 7.5));
  box(-21, -6, -11, 6, 3, 1, 5, 62);
  put(solid(g), tube([-16, 6, 19], [-16, 10, 19], 5.5, 5.5));
  put(solid(g), tube([-16, 10, 19], [-16, 13.5, 19], 3.2, 3.2));
  // the stage and its slide move together, on a spring
  const stg = solid(g), slide = solid(g), clips = mk("path", { class: "nf lo" }, g);
  const objs = mk("g", {}, g);
  const lenses = LEN.map((L, k) => ({ k, L, g: mk("g", {}, objs), barrel: null, tip: null }));
  for (const l of lenses) { l.barrel = solid(l.g); l.tip = solid(l.g); }
  put(solid(g), prism(P, front, disc(TX, 0, 9.5, 40), disc(TX, 0, 8, 40), TZ, TZ + 4));
  box(-21, -6.5, 5, 6.5, 3.5, 1.2, TZ + 4, TZ + 15);
  put(solid(g), tube([-8, 0, 70], [-21, 0, 90], 3.4, 3.4));
  put(solid(g), tube([-21, 0, 90], [-23, 0, 93], 4.4, 4.4));

  const zs = spring(lerp(ZLO, 40 - LEN[REST_LENS], REST_F), { k: 100 * value, c: 18 * Math.sqrt(value) });
  const tu = tween(0);
  let tuT = 0, dz = NaN, dt0 = NaN, lens = REST_LENS, painted = "";
  function draw(now) {
    const z = zs.x, t = tval(tu, now);
    if (!(Math.abs(z - dz) < 1e-3)) {
      dz = z;
      const [o, i] = rings(-11, -13, 12, 13, 2.2, 1); put(stg, prism(P, front, o, i, z, z + 3));
      const [so, si] = rings(-4, -10, 4, 10, 0.8, 0.4); put(slide, prism(P, front, so, si, z + 3, z + 3.8));
      clips.setAttribute("d", poly([P(-9, -6, z + 3.1), P(-3, -6, z + 3.9)]).replace("Z", "") + poly([P(-9, 6, z + 3.1), P(-3, 6, z + 3.9)]).replace("Z", ""));
    }
    if (!(Math.abs(t - dt0) < 1e-4)) {
      dt0 = t;
      for (const l of lenses) {
        const a = t + (l.k * 2 * Math.PI) / 3, x = TX + TR * Math.cos(a), y = TR * Math.sin(a);
        l.depth = x + y;
        put(l.barrel, prism(P, front, disc(x, y, 2.3), null, TZ - l.L, TZ));
        put(l.tip, prism(P, front, disc(x, y, 1.5), null, TZ - l.L - 2.5, TZ - l.L));
      }
      const order = lenses.slice().sort((p, q) => p.depth - q.depth), key = order.map((l) => l.k).join();
      if (key !== painted) { painted = key; for (const l of order) objs.appendChild(l.g); }
    }
  }
  const B = register(stage, (dt, now) => { const m = stepS(zs, dt); draw(now); return m || !tdone(tu, now); });
  bag.add(B.unregister);

  // bands fixed at rest: the pointer's side picks the lens, its height the stage
  const c0 = P(0, 0, 40), yLo = P(0, 0, 18)[1], yHi = P(0, 0, 70)[1];
  function aim(p) {
    const on = p && Math.abs(p[0] - c0[0]) < 110 && p[1] > yHi - 50 && p[1] < yLo + 50;
    const k = on ? (p[0] < c0[0] - 22 ? 1 : p[0] > c0[0] + 22 ? 2 : 0) : REST_LENS;
    const f = on ? clamp((yLo - p[1]) / (yLo - yHi), 0, 1) : REST_F;
    const now = performance.now();
    if (k !== lens || !on) {
      const want = (-k * 2 * Math.PI) / 3, cur = tuT;
      tuT = cur + Math.atan2(Math.sin(want - cur), Math.cos(want - cur)); tset(tu, tuT, now, 0);
    }
    lens = k;
    zs.t = lerp(ZLO, TZ - LEN[k] - 2.5 - 4.5, f);
    lenses.forEach((l) => { l.barrel.sil.classList.toggle("hi", l.k === k); l.tip.sil.classList.toggle("hi", l.k === k); });
    read.textContent = on ? `lens ${k + 1} · ${1 + Math.round(f * 4)}` : "rest";
    B.wake();
  }
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return { set: (v) => { zs.k = 100 * v; zs.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "microscope",
  means: "A lab microscope: the pointer's height raises the stage toward the lens, and its side swings a lens into place.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[150, 120], [250, 150], [200, 200], null],
  mount,
});

flasks.code:
/**
 * Flasks: six lab flasks in a row on a bench, conical, round-bottom on a cork
 * ring and volumetric with a mark on its long neck, each holding liquid. The
 * pointer is a field along the row: liquid rises in the flasks near it, each
 * level on its own spring, and the flask under it fills and is bright, with
 * bubbles over its liquid. At rest the levels are uneven and one flask is
 * bright. The slider is the field's reach.
 *
 * The pattern: one of many in a single row (bookshelf's pick by screen x) and
 * a field with a floor (terrain), on springs.
 */
const {
  Cam, circ, clamp, fit, hull, lerp, open, poly, prism, proj, rings, spring, stepS,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

// kind, body radius, neck radius, neck height, rest level (0 to 1), size
const F = [["cone", 12, 3.2, 10, 0.45], ["round", 10, 2.8, 14, 0.3], ["vol", 9, 2, 24, 0.6], ["cone", 9, 2.6, 8, 0.25], ["round", 8, 2.4, 11, 0.55], ["vol", 11, 2.4, 26, 0.35]];
const GAP = 26, FAV = 2, X0 = 12;
const D = Math.PI / 180;

/** A flask's profile: z0 (bottom of glass), zs (shoulder: where the neck starts), zt (rim), r(z). */
function profile([kind, R, rn, nh]) {
  if (kind === "cone") { const H = R * 2.1; return { z0: 0, zs: H, zt: H + nh, r: (z) => (z < H ? lerp(R, rn, z / H) : rn) }; }
  const zc = kind === "round" ? 2 + R * 0.92 : R * 0.72, z0 = kind === "round" ? zc - R : 0, zs = zc + Math.sqrt(R * R - rn * rn);
  return { z0, zs, zt: zs + nh, zc, r: (z) => (z < zs ? Math.sqrt(Math.max(0, R * R - (z - zc) ** 2)) : rn) };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const X1 = X0 * 2 + GAP * (F.length - 1);
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, -14, -5], [X1, 14, -5], [X1, -14, -5], [0, 14, -5], [X0, 0, 48], [X1 - X0, 0, 52]], 200, 170);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, -16, X1, 16, 3, 1.4);
  put(solid(g), prism(P, (q) => q.nu + q.nv > 0, br, bi, -5, 0));

  const ring = (cx, r, z, a0, a1, n = 24) => Array.from({ length: n + 1 }, (_, i) => { const a = lerp(a0, a1, i / n) * D; return P(cx + r * Math.cos(a), r * Math.sin(a), z); });
  const flasks = F.map((f, k) => {
    const cx = X0 + k * GAP, pr = profile(f), [kind, R, rn] = f, fg = mk("g", {}, g);
    if (kind === "round") put(solid(fg), prism(P, (q) => q.nu + q.nv > 0, ...[R * 0.55, R * 0.55 - 1].map((r) => circ(r, 32).map((q) => ({ ...q, u: q.u + cx }))), 0, 2.4));
    // the body is convex: the hull of its rings; then the liquid, then the neck over it, filled, its sides and rim stroked
    const pts = [];
    for (let z = pr.z0; z <= pr.zs + 0.01; z += (pr.zs - pr.z0) / 20) pts.push(...ring(cx, pr.r(z), z, 0, 360, 32));
    const body = mk("path", { class: "sil", d: poly(hull(pts)) }, fg);
    const liq = mk("path", { class: "nf lo" }, fg);
    mk("path", { class: "fo", d: poly(hull(ring(cx, rn, pr.zs - 0.3, 0, 360).concat(ring(cx, rn, pr.zt, 0, 360)))) }, fg);
    const neck = mk("path", { class: "nf sil", d: open([ring(cx, rn, pr.zs, 135, 135, 1)[0], ...ring(cx, rn, pr.zt, 135, 315)].concat([ring(cx, rn, pr.zs, 315, 315, 1)[0]])) }, fg);
    mk("path", { class: "nf lo", d: open(ring(cx, rn, pr.zt, -45, 135)) + open(ring(cx, rn + 0.1, pr.zs, -45, 135)) + (kind === "vol" ? open(ring(cx, rn, lerp(pr.zs, pr.zt, 0.55), -45, 135)) : "") }, fg);
    const liqN = mk("path", { class: "nf lo" }, fg);
    const full = kind === "vol" ? lerp(pr.zs, pr.zt, 0.55) : lerp(pr.zs, pr.zt, 0.4), lo = pr.z0 + (pr.zs - pr.z0) * 0.12;
    return { k, cx, pr, rn, body, neck, liq, liqN, full, lo, rest: f[4], sp: spring(f[4]), drawn: NaN, mid: P(cx, 0, pr.zt / 2) };
  });
  const bubbles = [0, 1, 2].map(() => mk("circle", { r: 1.1, class: "dot" }, g));

  function draw(f) {
    const lv = f.sp.x;
    if (Math.abs(lv - f.drawn) < 1e-3) return;
    f.drawn = lv;
    // the liquid: the body's shape inset below the level, its surface, and up the neck once it is past the shoulder
    const pr = f.pr, z = lerp(f.lo, f.full, clamp(lv, 0, 1)), inNeck = z > pr.zs, top = Math.min(z, pr.zs), pts = [];
    for (let i = 0; i <= 12; i++) { const zz = lerp(pr.z0 + 1.6, top, i / 12); pts.push(...ring(f.cx, Math.max(0.3, pr.r(zz) - 1.8), zz, 0, 360, 32)); }
    const rs = inNeck ? f.rn - 0.9 : Math.max(0.3, pr.r(z) - 1.8), surf = poly(ring(f.cx, rs, z, 0, 360, 40));
    f.liq.setAttribute("d", poly(hull(pts)) + (inNeck ? "" : surf));
    f.liqN.setAttribute("d", inNeck ? surf : "");
  }
  let bright = FAV;
  function placeBubbles() {
    const f = flasks[bright], z = lerp(f.lo, f.full, clamp(f.sp.t, 0, 1)), top = f.sp.t >= 0.99 ? f.pr.zt : Math.max(z, f.pr.zs);
    bubbles.forEach((b, j) => place(b, P(f.cx + [-0.8, 0.9, -0.2][j], 0, top + 3 + j * 3.6)));
  }

  const B = register(stage, (dt) => { let m = false; for (const f of flasks) { if (stepS(f.sp, dt)) m = true; draw(f); } return m; });
  bag.add(B.unregister);

  /** The flask whose resting middle is nearest the pointer's x on screen; the field reads the same distance. */
  const step = Math.abs(flasks[1].mid[0] - flasks[0].mid[0]);
  function aim(p) {
    let best = -1, bd = Infinity;
    flasks.forEach((f) => { const d = Math.abs(f.mid[0] - p[0]); if (d < bd) { bd = d; best = f.k; } });
    const on = bd < 26 && Math.abs(flasks[best].mid[1] - p[1]) < 80;
    flasks.forEach((f) => {
      const t = on ? Math.abs(f.mid[0] - p[0]) / (step * reach) : Infinity;
      const pull = f.k === best ? 1 : Math.max(0.1, Math.exp(-(t * t) / 3.5));
      f.sp.t = on ? Math.max(f.rest, pull) : f.rest;
    });
    bright = on ? best : FAV;
    for (const f of flasks) {
      for (const el of [f.body, f.neck, f.liq, f.liqN]) el.classList.toggle("hi", f.k === bright);
      for (const el of [f.liq, f.liqN]) el.classList.toggle("lo", f.k !== bright);
    }
    placeBubbles();
    read.textContent = on ? "flask " + (best + 1) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, { move: aim, leave: () => aim([-999, -999]) }));
  bag.add(() => svg.replaceChildren());
  aim([-999, -999]);
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

